/**
 * Everything a Tier-2 rebuild needs that is not the nodes themselves: the active view options
 * (which decide the display scaffolding a rebuild re-materializes) and the `getMarker` seam (the
 * stylesheet lookup driving sentinel classification and kind checks — a project `StyleInfo` when
 * one is active, the bundled table otherwise). The engine's transforms extend this as
 * `MarkerEditContext` (markerEditTier1.utils.ts); read-only consumers (the settle mirror, test
 * harnesses) build it directly.
 */
export interface Tier2Context {
  viewOptions: ViewOptions;
  getMarker: MarkerLookup;
  logger?: LoggerBasic;
}

/**
 * One contiguous byte range `[start, end)` of a fragment's text and the node key it came from —
 * the map that lets a rebuild carry the caret across re-tokenization by BYTE position
 * (`$selectAtFragmentByteAnchor`) and lets the read-only mirror attribute settled bytes back to
 * serialized nodes. `isSentinel` marks the one-byte U+FFFC stand-ins for atomically-preserved
 * nodes.
 */
export interface FragmentSpan {
  key: string;
  start: number;
  end: number;
  isSentinel: boolean;
}

/**
 * A resolved position in a tree, in Lexical's own point terms: `type: "text"` is an offset within
 * the TextNode `key` names, `type: "element"` a child-index boundary within the ElementNode it
 * names. Produced by {@link $resolveFragmentByteAnchor}; an element point is how a position past a
 * construct the caret cannot enter (a closing glyph, a preserved node run) is expressed.
 */
export interface FragmentPoint {
  key: NodeKey;
  offset: number;
  type: "text" | "element";
}

/**
 * A settle scope's displayed bytes flattened for the tokenizer: the fragment `text` (with each
 * atomically-preserved node as a one-byte U+FFFC placeholder), the {@link FragmentSpan} map back
 * to the contributing nodes, and the preserved node runs to re-insert where each placeholder
 * lands. Built by the fragment builders (`$buildParaFragment` and kin); consumed by the rebuild's
 * tokenize-and-splice and by caret restoration.
 */
export interface FragmentAccumulator {
  text: string;
  spans: FragmentSpan[];
  /** One entry per U+FFFC, in fragment order; each entry is a node RUN to re-insert. */
  sentinels: LexicalNode[][];
}

function pushText(out: FragmentAccumulator, node: LexicalNode, text: string): void {
  out.spans.push({
    key: node.getKey(),
    start: out.text.length,
    end: out.text.length + text.length,
    isSentinel: false,
  });
  out.text += text;
}

function pushSentinel(out: FragmentAccumulator, nodes: LexicalNode[]): void {
  // The tokenizer ends a marker name at a placeholder, as it does at the `\` the node's own bytes
  // start with. A preserved node directly after an opener whose separator was deleted (a note,
  // milestone, or attribute span right after `\wj`) is still spelled with the separator the file
  // writes after an opening marker; it is structural there (consumed by the opener's separator
  // scan), and mid-word placements (`wa` + note + `tta`) are unaffected. After a bare `\` it is
  // not structural — the tokenizer keeps `\ ` as text — so it is spelled as a no-break space no
  // other fragment byte is, and {@link tokenizeFragment} takes it back out.
  const tail = UNTERMINATED_MARKER_TAIL.exec(out.text)?.[0];
  if (tail !== undefined) out.text += tail === "\\" ? NBSP : " ";
  out.spans.push({
    key: nodes[0].getKey(),
    start: out.text.length,
    end: out.text.length + 1,
    isSentinel: true,
  });
  out.sentinels.push(nodes);
  out.text += ATOMIC_SENTINEL;
}

/** Display text → USFM fragment text: structural NBSP separators become plain spaces. Applied to
 * GLYPH text, attribute runs, and the para-prefix separator in every view, and to content text
 * under standard-view whitespace (see {@link contentFragmentText} for why content differs by
 * view). Also the normalization both signature builders apply to every text field — deliberately
 * view-independent there: the signature only ever compares the live scope against its own fresh
 * rebuild, so as long as BOTH sides flatten identically the comparison is exact, and a
 * view-dependent signature would buy nothing while opening a mirror-drift surface. */
export function toFragmentText(text: string): string {
  return text.replaceAll(NBSP, " ");
}

/** The separator `pushSentinel` puts between a bare `\` and a preserved node's placeholder, as the
 * tokenizer hands it back. */
const BARE_BACKSLASH_SEPARATED_SENTINEL = `\\${NBSP}${ATOMIC_SENTINEL}`;

/** Drop `pushSentinel`'s bare-backslash separators from tokenized `content`, in place. */
function withoutBareBackslashSeparators(content: MarkerContent[]): MarkerContent[] {
  content.forEach((item, index) => {
    if (typeof item === "string")
      content[index] = item.replaceAll(BARE_BACKSLASH_SEPARATED_SENTINEL, `\\${ATOMIC_SENTINEL}`);
    else if (item.content) withoutBareBackslashSeparators(item.content);
  });
  return content;
}

/**
 * The fragment byte of a line break that is display only: the one a view without spacing shows
 * before every verse, which the USJ export skips and loading puts back. It is whitespace to every
 * fragment reader that counts positions (`/\s/`), so the caret positions on either side of the
 * break stay apart exactly as a plain space would keep them, but {@link tokenizeFragment} removes
 * it: the file has nothing between the verse and the bytes before it, and a space there would
 * re-tokenize as text. No other fragment byte is this character.
 */
const DISPLAY_LINE_BREAK = String.fromCharCode(0x2028);

/** `text` as the tokenizer reads it: without the display-only line breaks
 * ({@link DISPLAY_LINE_BREAK}). */
function withoutDisplayLineBreaks(text: string): string {
  return text.replaceAll(DISPLAY_LINE_BREAK, "");
}

/** The bytes a line break stands for in a rebuild's fragment and signature: a display-only one
 * before a verse is {@link DISPLAY_LINE_BREAK}, and any other reads as the space between its
 * neighbors. */
function lineBreakFragmentText(isBeforeVerse: boolean): string {
  return isBeforeVerse ? DISPLAY_LINE_BREAK : " ";
}

/** What the preserved node run behind a placeholder stands for, as the tokenizer reads it. */
function preservedNodeKind(run: LexicalNode[]): PreservedNodeKind {
  if ($isNoteNode(run[0])) return "note";
  if ($isVerseNode(run[0])) return "verse";
  return "other";
}

/**
 * Tokenize a rebuild fragment. Every settle that tokenizes a fragment holding preserved-node
 * placeholders goes through here, so each placeholder parses as the node it stands for (a note or
 * a verse ends the note open in front of it), and a bare `\` the user left in front of a preserved
 * node stays exactly that: the separator `pushSentinel` spells after it is not a byte of the
 * document, and the file reads `\` directly followed by the node's own marker the same way.
 */
export function tokenizeFragment(
  fragment: FragmentAccumulator,
  options: Omit<UsfmFragmentOptions, "placeholders">,
): MarkerContent[] {
  return withoutBareBackslashSeparators(
    usfmFragmentToUsjContent(withoutDisplayLineBreaks(fragment.text), {
      ...options,
      placeholders: fragment.sentinels.map(preservedNodeKind),
    }),
  );
}

/**
 * Display text → USFM fragment text for a CONTENT run — plain text that is not glyph bytes, not
 * an attribute run, and not the para-prefix separator. What an NBSP byte in such a run MEANS
 * depends on the view, so the flattening must too:
 *
 * - Standard-view whitespace: a data NBSP displays as `~` (usjTextToDisplay), so an NBSP byte in
 *   display text is always a display artifact — a space-run member or a structural separator —
 *   and flattens to " " ({@link toFragmentText}).
 * - Unformatted (editable without the standard whitespace mapping): a content NBSP IS the data
 *   byte. It is spelled `~` — the tokenizer's input convention (`usjText` maps `~` back to NBSP,
 *   PT9 UsfmParser) — so a settle that rewrites the paragraph round-trips it instead of
 *   corrupting it to a plain space. Two structural shapes still flatten to " " even here: a node
 *   that is EXACTLY one NBSP (the engine-owned spacer / empty-char placeholder shape, which
 *   serialization also treats as structural — the lone-NBSP byte test in editor-usj.adaptor.ts)
 *   unless it is a no-break space an annotation mark split off content (`isNbspContent`, from
 *   `$isNbspContentAtMark`), and the one structural leading NBSP fused onto a char span's first
 *   content child (`structuralLead` — the twin of the conversion's positional separator strip,
 *   `precedesOpeningCharGlyph` in editor-usj.adaptor.ts). When that first content child has LOST
 *   its separator, its leading bytes run on as the opener's marker name, and the name ends at the
 *   first space the screen shows — an NBSP there included, which flattens to " " so the name never
 *   swallows it (`\wLord⍽God` reads as `\wLord` followed by `God`, as `\wLord God` does).
 *
 * ONE definition for every fragment producer: the mutating rebuilds and the read-only settle both
 * build their fragments through `$appendNodesFragment` below, so the mirror can never flatten a
 * content NBSP differently from the live path (a disagreement there is a fixed-point refusal —
 * the editor refusing to settle).
 */
export function contentFragmentText(
  text: string,
  viewOptions: ViewOptions | undefined,
  structuralLead = false,
  isNbspContent = false,
): string {
  if (hasStandardViewWhitespace(viewOptions)) return toFragmentText(text);
  if (text === NBSP && !isNbspContent) return " ";
  const hasLead = structuralLead && text.startsWith(NBSP);
  const body = hasLead ? text.slice(1) : text;
  const runOnName = structuralLead && !hasLead ? NAME_ENDING_AT_NBSP_REGEX.exec(body) : null;
  if (runOnName)
    return `${runOnName[0]} ${body.slice(runOnName[0].length + 1).replaceAll(NBSP, "~")}`;
  return (hasLead ? " " : "") + body.replaceAll(NBSP, "~");
}

/** Leading bytes the tokenizer's name scan runs through (anything but whitespace, a zero-width
 * space, `\`, `|` and `*`), when an NBSP is what ends them. */
const NAME_ENDING_AT_NBSP_REGEX = /^[^\s\u200B\\|*]+(?=\u00A0)/;

/**
 * A TextNode's contribution to the rebuild fragment. The para-prefix trailing-space node is
 * structurally a single display separator, so it normally contributes a plain " " regardless of
 * its NBSP content — but when the user has TYPED INTO it (the content-start caret position lands
 * inside it), it carries a literal run that must reach the tokenizer (e.g. `\zz `
 * typed at content start was dropped here, so the rebuild reproduced the paragraph unchanged and
 * the literal never settled). Substitute the separator only while the node is pure whitespace.
 */
function $textNodeFragmentText(node: TextNode): string {
  const text = node.getTextContent();
  if (!$isMarkerTrailingSeparator(node)) return text;
  return /^[\s\u00A0]*$/.test(text) ? " " : text;
}

/**
 * Display siblings after a MilestoneNode that belong to its run: opening
 * MarkerNode, optional attribute TextNode, self-closing MarkerNode. They ride
 * inside the milestone's sentinel so the visible glyphs survive the rebuild.
 *
 * Delegates to the shared {@link $milestoneAttributeRunPieces} — the single definition of "a
 * milestone's run" — so the rebuild and the self-healing sync (attributeDisplay.utils.ts) can
 * never disagree about which siblings make up the run. The rebuild consumes a CONTIGUOUS run
 * starting at the opening glyph (it advances the loop index past `run.length`), so a milestone
 * with no opening glyph contributes no run here; the tolerant scanner can also surface a detached
 * attribute/closer with no opening, but that partial shape never reaches a settled rebuild.
 *
 * When the pieces were found inside an `AttributeRunNode` wrapper, the returned run is
 * `[wrapper]` — ONE element, not the wrapper's unpacked children — so the caller's `index +=
 * run.length` advances past the ONE sibling slot the wrapper occupies. `$appendNodesFragment`'s
 * generic ElementNode branch already flattens a transparent wrapper's children into the fragment
 * (the same branch TypedMarkNode relies on), so the fragment bytes come out byte-identical to the
 * loose shape without any special-casing there.
 *
 * This is SLOT accounting, so it deliberately does NOT require the run's glyphs to still be
 * canonical, even though `$milestoneAttributeRunPieces` reports a byte-damaged glyph as absent
 * (correct for the self-healing sync, which needs the damage to read as divergence). Skipping the
 * run because a byte is pending in its opening glyph leaves the run's bytes behind as an
 * unconsumed sibling: the milestone degrades to a preserved sentinel AND its own bytes flow into
 * the fragment as ordinary text, so the tokenizer re-derives a SECOND milestone from them while
 * the sentinel restores the first — one milestone on screen, two in the file.
 *
 * An attached-but-EMPTY wrapper still occupies its slot and is still returned; what protects a
 * bare-but-wrapped milestone from being silently spliced away is the callers' byte gate
 * ({@link milestoneRunRendersBytes}), not a zero-length run.
 */
function $milestoneDisplayRun(children: LexicalNode[], index: number): LexicalNode[] {
  const milestone = children[index];
  if (!$isMilestoneNode(milestone)) return [];
  const { attribute, closing, wrapper } = $milestoneAttributeRunPieces(milestone);
  if (wrapper) return [wrapper];
  // No wrapper found: the shared scanner above can still surface a genuinely LOOSE run (a
  // pre-flip editor state, an undo stack, or a collab-materialized bare milestone that hasn't
  // gone through heal-forward yet) — unpacked as individual pieces here, rather than one wrapper
  // node, since that is how they actually ride in the tree. Reporting nothing for a loose-but-
  // present run would misclassify a re-tokenizable milestone as content-less (see the byte gate
  // at both call sites below), stranding its bytes as ordinary text right next to the milestone's
  // own now-empty sentinel instead of flowing them as its run. The opening SLOT is claimed from
  // the sibling directly, for the same canonicality reason as the wrapper above; the trailing
  // pieces come from the shared scanner, and a damaged opening simply leaves them to flow as the
  // adjacent text they already are (the same bytes, in the same order).
  const next = milestone.getNextSibling();
  if (
    !$isMarkerNode(next) ||
    next.getMarkerSyntax() !== "opening" ||
    next.getMarker() !== milestone.getMarker()
  )
    return [];
  const run: LexicalNode[] = [next];
  if (attribute) run.push(attribute);
  if (closing) run.push(closing);
  return run;
}

/**
 * Whether a milestone's display run actually RENDERS bytes — the gate deciding whether the
 * milestone can re-tokenize from its run (it can only be re-derived from bytes that exist) or
 * must ride through the rebuild as a preserved sentinel together with its run.
 *
 * Byte-valued rather than length-valued on purpose: a run's slot can be occupied by an empty
 * `AttributeRunNode` wrapper, or by a bare milestone with no run at all (the collab materializer
 * `$createMilestone` builds these), and both contribute ZERO bytes — so re-tokenizing would
 * splice the milestone away entirely, a silent deletion. The spec's "state not recoverable from
 * displayed bytes → atomic" self-protection.
 */
function milestoneRunRendersBytes(run: LexicalNode[]): boolean {
  return run.some((node) => node.getTextContent().length > 0);
}

/**
 * Display siblings after a VerseNode that belong to its \va/\vp display triplets: an opening
 * MarkerNode, an attribute TextNode, and a closing MarkerNode for `\va`, then the same shape for
 * `\vp` (displayRunSync.utils.ts's `$syncDisplayRun`, parameterized by the `va`/`vp` descriptors in
 * displayRunRegistry.ts; usj-editor.adaptor's
 * `addVerseAttributes`). A verse that re-tokenizes (the common case — see `verseNeedsSentinel`)
 * flows the run as ordinary fragment content right after the verse's own glyph text, so the
 * tokenizer's attrCapture folds `\va`/`\vp` back onto the freshly re-derived verse exactly as it
 * would for literal typed text. Only a still-sentinel verse (`unknownAttributes`) absorbs the run
 * into its OWN sentinel — see `$milestoneDisplayRun`'s non-re-tokenizable branch for the same
 * shape — so the tokenizer never sees `\va`/`\vp` immediately after an opaque U+FFFC placeholder
 * with no verse to fold onto (which would degrade them into unrelated standalone markers).
 *
 * For either marker, when the next sibling slot is a matching `AttributeRunNode`
 * wrapper, that ONE node is pushed instead of its unpacked pieces (mirrors `$milestoneDisplayRun`
 * — the generic ElementNode branch in `$appendNodesFragment` flattens it for the fragment builder
 * without any further special-casing) — even an attached-but-EMPTY wrapper is pushed: it occupies
 * exactly one slot in `children` regardless of emptiness, and contributes zero bytes/signature
 * entries downstream (flattening an empty element yields nothing), so including it keeps the
 * per-marker slot accounting exact without changing what either caller sees.
 *
 * `\va` and `\vp` are each attempted INDEPENDENTLY at their own position: a marker with no piece
 * there AT ALL — the common "this verse has no `\va`" case, or a `\vp`-only verse (a real,
 * permanent shape the sync builds, not just mid-edit debris) — contributes nothing and leaves the
 * slot for the OTHER marker to claim, rather than aborting the whole scan. Only a PARTIAL match
 * (an opener found but its value/closer missing or wrong) stops the scan entirely: such debris'
 * true extent can't be inferred from here, so continuing risks misreading the OTHER marker's own
 * content as part of it.
 *
 * Delegates each marker's scan to the shared {@link $verseAttributeRunPieces} — the single
 * definition of "a verse marker's run pieces", also used by the self-healing sync
 * (attributeDisplay.utils.ts) — rather than re-walking siblings independently here, so the two can
 * never disagree about which shape (wrapped, loose, or partial) is present at a given position.
 * That scanner already tolerates a genuinely LOOSE run too (a pre-flip editor state, an undo
 * stack, or a collab-materialized bare verse mid-heal-forward), so its pieces are still reported
 * here as individual nodes when found unwrapped — dropping them would misread a re-tokenizable
 * `\va`/`\vp` as absent, stranding its bytes as ordinary text beside the verse instead of flowing
 * them as its run.
 */
function $verseAttributeRun(children: LexicalNode[], index: number): LexicalNode[] {
  const run: LexicalNode[] = [];
  let anchor: LexicalNode = children[index];
  for (const marker of ["va", "vp"] as const) {
    const { opener, value, closer, wrapper } = $verseAttributeRunPieces(anchor, marker);
    if (wrapper) {
      run.push(wrapper);
      anchor = wrapper;
    } else if (opener && value && closer) {
      run.push(opener, value, closer);
      anchor = closer;
    } else if (opener || value || closer) {
      break; // partial match — true extent can't be inferred from here, so stop the scan
    }
  }
  return run;
}

/**
 * A verse whose state is not fully recoverable from its visible text stays atomic.
 * altnumber/pubnumber round-trip through the \va/\vp display run
 * (displayRunSync.utils.ts's `$syncDisplayRun`, usj-editor.adaptor's
 * `addVerseAttributes`), and `sid` is reconciled separately by carry-over in `$rebuildParas`
 * (pairing old and new verses by position/number) rather than kept alive by atomicity — only
 * `unknownAttributes`, which has no display representation at all, forces the sentinel.
 */
function verseNeedsSentinel(node: VerseNode): boolean {
  return Boolean(node.getUnknownAttributes());
}

/**
 * Whether `marker` re-tokenizes as a milestone, mirroring the tokenizer's OWN classification
 * (`usfmFragmentToUsjContent`) exactly: stylesheet-declared `MarkerType.Milestone`, or — when the
 * effective stylesheet doesn't know the marker at all (the bundled table has no milestone
 * entries; a project `StyleInfo` might) — the same stylesheet-family name heuristic the tokenizer
 * falls back to. A name the heuristic deliberately excludes (a heuristic-gap name like bare `ts`,
 * valid per `MilestoneNode.isValidMarker` but not a stylesheet-declared milestone name) would
 * tokenize back as something else entirely — such a marker must stay atomic.
 */
// Exported for the read-only settle's serialized-side signature mirror (virtualSettle.utils.ts) —
// classifying a freshly-tokenized milestone's re-tokenizability must use the exact same rule on
// both the live and the JSON side.
export function $isReTokenizableMilestone(marker: string, getMarkerFn: MarkerLookup): boolean {
  const kind = getMarkerFn(marker)?.type;
  return kind === MarkerType.Milestone || (kind === undefined && isMilestoneHeuristicName(marker));
}

/**
 * Whether an expanded note's own opening or closing glyph holds bytes that make it a literal: they
 * no longer spell the note's marker, and they are not a rename the note takes in place (a bare or
 * terminated opener naming another note marker, which `$applyOpenerRename` applies). Such a note
 * is re-tokenized from its bytes within its paragraph, exactly as a char span with a damaged glyph
 * is, instead of being preserved whole: its own content-only scope never reads its glyphs, so the
 * bytes would stay on screen and never reach the file.
 *
 * A note carrying attributes its bytes cannot spell (anything but `closed`) stays preserved.
 * Collapsed notes never qualify: their glyphs are not typed into. Nor does a note whose shell the
 * host governs (`ViewOptions.isNoteShellEditable: false`, its glyphs built in `token` mode): its
 * glyphs are not text, so their bytes never read as anything but the note's own.
 *
 * Read-only: safe inside `editor.getEditorState().read(...)` or an update.
 */
export function $isLiteralNoteShell(note: NoteNode): boolean {
  if (note.getIsCollapsed() !== false) return false;
  if (note.getChildren().some((child) => $isMarkerNode(child) && child.getMode() === "token"))
    return false;
  const attributes = Object.keys(note.getUnknownAttributes() ?? {});
  if (attributes.some((name) => name !== "closed")) return false;
  return note.getChildren().some((child) => {
    if (!$isMarkerNode(child) || $isCanonicalMarkerNode(child)) return false;
    if (child.getMarkerSyntax() !== "opening") return true;
    const text = child.getTextContent();
    const name = (BARE_OPENER_REGEX.exec(text) ?? TERMINATED_OPENER_REGEX.exec(text))?.[1];
    return (
      name === undefined ||
      name.startsWith("+") ||
      !NoteNode.isValidMarker(name) ||
      child.getMarker() !== note.getMarker()
    );
  });
}

/**
 * Mirrors `$appendChildrenFragment`'s "preserve this node atomically" classification. A milestone
 * re-tokenizes exactly when its marker classifies as one (`$isReTokenizableMilestone`): its
 * display run (opening glyph, optional attribute text, self-closing glyph) is ordinary text among
 * its paragraph siblings, and the tokenizer's `scanMilestone` re-derives sid/eid/unknownAttributes
 * from it — a genuine round trip, not a preserved blob. A char span's attribute bytes are
 * similarly no longer classified wholesale: a span WITH a closing glyph renders its attributes as
 * an ordinary `|…` display run among its children (attributeDisplay.utils.ts), so the fragment
 * builder re-tokenizes it like any other char content and `extractAttributes` re-derives the
 * attribute set. A span with NO closing glyph (implicitly-closed footnote/cross-reference content,
 * or explicit `closed="false"`) never gets a display run at all, so any OTHER attribute it carries
 * (`link-href` on an auto-closed `\xt`, say) has no visible bytes to re-derive from —
 * `$hasUnrecoverableAttributes` keeps exactly that shape atomic. A verse is classified the same
 * way (`verseNeedsSentinel`): its \va/\vp display run is ordinary content among its paragraph
 * siblings when the verse re-tokenizes, and only `unknownAttributes` — which has no visible
 * representation at all — forces the sentinel. `sid` plays no part in this classification: it is
 * derived data, invisible in display bytes, reconciled by carry-over in `$rebuildParas` after the
 * rebuild rather than by atomicity.
 *
 * Exported for the read-only settle's own live-side structural-marker walk
 * (virtualSettle.utils.ts's `$liveStructuralMarkers`), which must treat a node as opaque under
 * the EXACT SAME rule `$appendSignature` does — that walk collects a live ParaNode's/CharNode's
 * own `marker` field to compensate for a blind spot in the signature comparison, and a sentinel
 * node's nested markers are not a blind spot at all: `$appendSignature` already collapses the
 * WHOLE sentinel to one opaque character before ever reaching a CharNode/generic-element branch
 * that would recurse into it, so the live walk must stop at exactly the same boundary or it
 * collects markers the JSON side (built from a tree where the sentinel is already just one
 * character inside a text node, with nothing to recurse into) can never have a counterpart for.
 */
export function $isRebuildSentinel(node: LexicalNode, getMarkerFn: MarkerLookup): boolean {
  if ($isMilestoneNode(node)) return !$isReTokenizableMilestone(node.getMarker(), getMarkerFn);
  if ($isNoteNode(node)) return !$isLiteralNoteShell(node);
  if ($isUnknownNode(node)) return true;
  if ($isVerseNode(node)) return verseNeedsSentinel(node);
  if ($isCharNode(node)) return $charNeedsSentinel(node, getMarkerFn);
  return false;
}

/**
 * Whether a char span must be preserved whole rather than re-tokenized — the one authority for
 * that question, shared with the fragment builder's own CharNode branch. The two decide the same
 * thing about the same node and MUST agree: the builder replaces a sentinel span with a single
 * placeholder character, and {@link $isRebuildSentinel} is what tells the signature and the
 * read-only settle's live walk to stop at exactly that boundary.
 *
 * Two shapes are not text-recoverable. A span carrying attribute bytes with nowhere visible to
 * re-derive them from ({@link $hasUnrecoverableAttributes}), and a span whose marker the
 * stylesheet does not declare — a custom.sty marker the tokenizer would degrade to literal text.
 * Inside a note it does not: in note context the tokenizer reads an undeclared marker as a
 * character span, so such a span re-tokenizes like any other there, unless it carries attributes
 * (the tokenizer does not extract those for a marker it has no definition of). Re-tokenizing it
 * is also what keeps it where it is: its placeholder would read as text of an unclosed run before
 * it (`\ft asdf ` then `\df`), and splice it back INSIDE that run, nested (`\+df`).
 *
 * An ATTRIBUTE marker is exempt from the stylesheet test, because for those the stylesheet is
 * not the authority: the tokenizer's own table folds them onto their host, so the round trip is
 * defined without a stylesheet entry. `\cat` is the case this exists for — the only attribute
 * marker usfm.sty omits, and so the only one a stylesheet-keyed test mistakes for a custom
 * marker. Preserved as a sentinel it can never settle: its bytes stop reaching the tokenizer, the
 * category fold never fires, and every later pass reports a fixed point, so a typed `\cat` run
 * becomes a category only by round-tripping through the file.
 */
function $charNeedsSentinel(char: CharNode, getMarkerFn: MarkerLookup): boolean {
  return $charNeedsSentinelAs(char, char.getMarker(), getMarkerFn);
}

/**
 * {@link $charNeedsSentinel} for `char` as it will be once renamed to `marker` — the read-only
 * settle's question about a span a pending rename has not renamed yet.
 *
 * Read-only: call inside a read or an update.
 */
export function $charNeedsSentinelAs(
  char: CharNode,
  marker: string,
  getMarkerFn: MarkerLookup,
): boolean {
  if ($hasUnrecoverableAttributes(char)) return true;
  if (isAttributeMarker(marker) || getMarkerFn(marker) !== undefined) return false;
  if ($isInsideNote(char) && !$hasAttributesBesidesClosed(char)) return false;
  // An undeclared marker is kept whole only while its own glyphs still spell it. Once the user has
  // edited one (deleted the `\` to turn the marker back into text, say), those bytes are the
  // instruction: preserved as a sentinel they never reach the tokenizer, the span survives the
  // settle unchanged, and the damaged glyph is later healed back to the marker it no longer says.
  // A span about to be renamed is asked about as renamed: the rename re-spells its glyphs to
  // `marker`, so they spell it again.
  return marker !== char.getMarker() || !$hasEditedOwnGlyph(char);
}

/** Whether `node` is inside a note's content. */
function $isInsideNote(node: LexicalNode): boolean {
  const parent = node.getParent();
  return parent !== null && $findFirstAncestorNoteNode(parent) !== undefined;
}

/** Whether a char span carries attributes other than the derived `closed` flag. */
function $hasAttributesBesidesClosed(char: CharNode): boolean {
  const attributes = char.getUnknownAttributes();
  return !!attributes && Object.keys(attributes).some((name) => name !== "closed");
}

/**
 * Whether one of `char`'s own marker glyphs no longer reads canonically, or its opener is gone
 * while its closer remains - a span the user has started turning back into text.
 *
 * A span with no glyphs at all (markers hidden, or an unclosed span whose opener was deleted) is
 * not counted: nothing on screen records an edit there.
 */
function $hasEditedOwnGlyph(char: CharNode): boolean {
  const ownGlyphs = char
    .getChildren()
    .filter((child) => $isMarkerNode(child) && child.getMarker() === char.getMarker())
    .filter($isMarkerNode);
  if (ownGlyphs.some((glyph) => !$isCanonicalMarkerNode(glyph))) return true;
  const hasOpener = ownGlyphs.some((glyph) => glyph.getMarkerSyntax() === "opening");
  const hasCloser = ownGlyphs.some((glyph) => glyph.getMarkerSyntax() === "closing");
  return !hasOpener && hasCloser;
}

/** Whether the next content after `lineBreak` in its paragraph is a verse, looking through any
 * annotation mark wrapping either of them (a mark contributes no bytes). */
function $isVerseLineBreak(lineBreak: LexicalNode): boolean {
  let at: LexicalNode = lineBreak;
  let parent = at.getParent();
  while (!at.getNextSibling() && $isTypedMarkNode(parent)) {
    at = parent;
    parent = at.getParent();
  }
  let next = at.getNextSibling();
  while ($isTypedMarkNode(next)) next = next.getFirstChild();
  return $isVerseNode(next);
}

/**
 * Delimiter (never present in scripture text) opening a structural element's span inside a
 * signature string ({@link $signatureOf}), so a structural change is always visible in the
 * signature even when the flattened text is unchanged. Exported for the read-only settle's
 * serialized-side signature mirror (virtualSettle.utils.ts), which must compose signatures
 * byte-identically or the two fixed-point refusal checks would disagree.
 */
export const SIGNATURE_OPEN = String.fromCharCode(1);
/** Closing counterpart of {@link SIGNATURE_OPEN}. */
export const SIGNATURE_CLOSE = String.fromCharCode(2);

/**
 * Flattens any `AttributeRunNode`(s) in `run` into their own children, so a wrapped run's
 * signature is structurally IDENTICAL to the loose equivalent's — no extra "attribute-run"
 * type-tagged span the generic `$isElementNode` branch below would otherwise add. Unlike the
 * fragment builder (whose generic ElementNode branch already flattens a transparent wrapper's
 * bytes for free, since fragment text carries no structural tagging), the SIGNATURE tags every
 * element's type, so the wrapper itself must be skipped explicitly here, not just its bytes.
 */
function $flattenAttributeRuns(run: LexicalNode[]): LexicalNode[] {
  return run.flatMap((node) => ($isAttributeRunNode(node) ? node.getChildren() : [node]));
}

/**
 * A CharNode's own children with every `TypedMarkNode` (at any depth) replaced by its children,
 * plus the set of nodes a mark boundary separates from the node before them. A mark splits the
 * text node it starts or ends in, so the span's leading `NBSP` separator can become a node of its
 * own (`NBSP` + `mark["name"]`) where a re-tokenization keeps it fused (`NBSPname`), and
 * `charOwnChildSignatureText` reads those two shapes differently. `$appendSignature` rejoins text
 * across these boundaries only, so a lone-NBSP spacer in front of a nested CharNode stays a node of
 * its own.
 */
function $charChildrenThroughMarks(children: LexicalNode[]): {
  nodes: LexicalNode[];
  splitByMark: Set<LexicalNode>;
} {
  const nodes: LexicalNode[] = [];
  const splitByMark = new Set<LexicalNode>();
  let atMarkBoundary = false;
  const visit = (node: LexicalNode): void => {
    if ($isTypedMarkNode(node)) {
      atMarkBoundary = true;
      node.getChildren().forEach(visit);
      atMarkBoundary = true;
      return;
    }
    if (atMarkBoundary && nodes.length > 0) splitByMark.add(node);
    atMarkBoundary = false;
    nodes.push(node);
  };
  children.forEach(visit);
  return { nodes, splitByMark };
}

/** Whether `node` is text `$appendSignature` signs as plain content (its generic text branch). */
function $isPlainSignatureText(
  node: LexicalNode | undefined,
  getMarkerFn: MarkerLookup,
): node is TextNode {
  return (
    $isTextNode(node) &&
    !$isVerseNode(node) &&
    !$isMarkerNode(node) &&
    !$isImmutableUnmatchedNode(node) &&
    !$isRebuildSentinel(node, getMarkerFn) &&
    $getState(node, textTypeState) !== "attribute"
  );
}

/**
 * Structure-aware, sentinel-normalized signature of a node list, used ONLY to detect
 * a `$rebuildParas` no-op (fixed point). Marker glyphs and text contribute their
 * fragment text; every structural element (paragraph, CharNode span, verse-as-text,
 * transparent wrapper) contributes a delimited, type-tagged span — so any structural
 * change a real rebuild makes (e.g. flat `\nd x\nd*` literal text becoming a CharNode)
 * yields a different signature and is never mistaken for a no-op. Preserved (sentinel)
 * nodes and the U+FFFC placeholders that stand in for them until `$replaceSentinels`
 * both collapse to `ATOMIC_SENTINEL`, so a pre-splice rebuild output and the paragraphs
 * it was derived from compare equal IFF the rebuild changed nothing that matters.
 *
 * `insideCharChildren` is true only while appending a CharNode's OWN direct children (set by this
 * function's own CharNode branch below) — mirrors `editor-usj.adaptor.ts`'s `recurseNodes`'s
 * `isCharChild` parameter exactly, including how it resets for anything nested one level deeper
 * that is not itself another CharNode (which gets its own fresh `true` at its own branch). See
 * `charOwnChildSignatureText`'s doc comment (settleShared.utils.ts) for what it gates. A CharNode's
 * children arrive with their marks flattened away (`$charChildrenThroughMarks`), and `splitByMark`
 * names the nodes a mark boundary split from the text before them.
 */
function $appendSignature(
  children: LexicalNode[],
  out: string[],
  getMarkerFn: MarkerLookup,
  insideCharChildren = false,
  splitByMark?: Set<LexicalNode>,
): void {
  for (let index = 0; index < children.length; index++) {
    const node = children[index];
    if ($isMilestoneNode(node)) {
      // Mirror `$appendChildrenFragment`: a re-tokenizable milestone's display run (opening
      // MarkerNode, optional attribute text, self-closing MarkerNode) is ordinary signature
      // content. The run text ALONE is not enough, though — like a char span's display run
      // (see the char branch below), it is a derived cache that can lag the node's true
      // attribute state: an in-place value edit (the leading NBSP kept, only the value bytes
      // changed) produces run text byte-identical to what re-tokenizing it would regenerate,
      // so both comparison sides render the same bytes and only the milestone's own STALE
      // sid/eid/unknownAttributes reveal that the rebuild is not a no-op. Fold that state in
      // alongside the recursed run, or the fixed-point refusal silently discards the edit. A
      // non-re-tokenizable milestone's run is instead absorbed into the SAME single sentinel
      // the fragment builder produces for it — the post-splice NEW side's sentinel already
      // stands in for the whole run, so the pre-splice OLD side must collapse the run the
      // same way or the signatures never compare equal and the refusal never fires.
      const run = $milestoneDisplayRun(children, index);
      // A run with no displayable bytes (the collab materializer builds bare MilestoneNodes with
      // no display-run siblings) has nothing to re-tokenize, so it must collapse to the same
      // single sentinel `$appendNodesFragment` produces for it — else this side would fold in the
      // milestone's state while the fragment side dropped it, and the fixed-point check would
      // spuriously diverge (mirror the fragment builder's byte gate below).
      if (
        $isReTokenizableMilestone(node.getMarker(), getMarkerFn) &&
        milestoneRunRendersBytes(run)
      ) {
        out.push(
          SIGNATURE_OPEN,
          "ms",
          // `marker` is part of the state for the same reason the attributes below are, and it is
          // the one the SAVE leg reads: `createMilestoneMarker` (editor-usj.adaptor.ts) emits the
          // milestone's own `marker` field, never the glyph bytes. Renaming the opening glyph
          // (`\qt-s` → `\qt1-s`) leaves those bytes identical on both sides of this comparison —
          // the OLD side shows the user's edit, and re-tokenizing that same text regenerates the
          // identical glyph — so only the milestone's STALE `marker` reveals the rebuild is not a
          // no-op. Without this fold the fixed-point refusal fires, the rename never reaches node
          // state, and the file keeps the old name while the screen shows the new one.
          //
          // `attributeOrder` is part of the state: the serialized key order follows it, so a
          // USER EDIT that only REORDERS the run's attributes (values unchanged, displayed
          // bytes identical to their own re-tokenization) is a real document change — without
          // this fold both sides compare equal, the fixed-point refusal fires, and the stale
          // order silently survives the settle. An unedited non-canonical load stays a fixed
          // point: the fresh side re-derives the same authored order from the same bytes.
          JSON.stringify({
            marker: node.getMarker(),
            sid: node.getSid() ?? null,
            eid: node.getEid() ?? null,
            unknownAttributes: node.getUnknownAttributes() ?? null,
            attributeOrder: node.getAttributeOrder() ?? null,
          }),
        );
        $appendSignature($flattenAttributeRuns(run), out, getMarkerFn);
        out.push(SIGNATURE_CLOSE);
      } else out.push(ATOMIC_SENTINEL);
      index += run.length;
    } else if ($isVerseNode(node)) {
      // A sentinel verse's \va/\vp display run (if any) is absorbed into the SAME single
      // sentinel `$appendNodesFragment` produces for it — same reasoning as the non-re-
      // tokenizable milestone case above: the post-splice NEW side's sentinel already stands in
      // for verse + run together, so the pre-splice OLD side must collapse them the same way.
      const run = $verseAttributeRun(children, index);
      if (verseNeedsSentinel(node)) out.push(ATOMIC_SENTINEL);
      else {
        // The run text is a DERIVED CACHE ($syncDisplayRun, displayRunSync.utils.ts)
        // that can lag the verse's own altnumber/pubnumber state — an in-place value edit that
        // keeps the triplet's structural NBSP and changes only the value bytes produces run text
        // byte-identical on both sides of this comparison (it was edited directly on the live OLD
        // node, and re-tokenizing that same edited text regenerates the identical NEW run), so
        // only the verse's own STALE field reveals the rebuild is not a no-op — the same reason
        // a re-tokenizable milestone folds its own sid/eid/unknownAttributes in alongside its
        // recursed run above. Fold number/altnumber/pubnumber in alongside the recursed run.
        // `unknownAttributes` is omitted: this branch runs only when `verseNeedsSentinel` is
        // false, so it is always undefined here by construction.
        //
        // `sid` is DELIBERATELY excluded. This comparison runs on the OLD side (still carrying
        // its sid) against the freshly re-tokenized NEW side, which never has one — sid
        // carry-over (`$rebuildParas`, after the splice) runs strictly AFTER this fixed-point
        // check has already decided whether a rebuild happens at all. Folding raw sid in here
        // would make every sid-bearing verse compare unequal forever (a real value vs. an
        // always-absent one), forcing an endless splice-then-refuse rebuild on every unrelated
        // edit anywhere else in the same paragraph.
        //
        // The verse's own GLYPH TEXT is folded in (fragment-normalized, so its NBSP separator
        // matches the re-tokenized NEW side's): a VerseNode is a TextNode, and this branch
        // shortcuts the generic TextNode case below, so without this a whitespace-only glyph edit
        // (`\v 2 ` → `\v 2  `) that leaves number/altnumber/pubnumber unchanged would compare equal
        // to its canonical re-tokenization and refuse forever — a permanent non-settling state.
        out.push(
          SIGNATURE_OPEN,
          "verse",
          toFragmentText(node.getTextContent()),
          JSON.stringify({
            number: node.getNumber(),
            altnumber: node.getAltnumber() ?? null,
            pubnumber: node.getPubnumber() ?? null,
          }),
        );
        $appendSignature($flattenAttributeRuns(run), out, getMarkerFn);
        out.push(SIGNATURE_CLOSE);
      }
      index += run.length;
    } else if ($isMarkerNode(node)) {
      // Delimited and tagged (not bare glyph text) so text moving across the
      // glyph/content boundary — e.g. glyph "\q extra" vs. glyph "\q" + content
      // "extra" — changes the signature instead of silently canceling out.
      out.push(SIGNATURE_OPEN, "marker", toFragmentText(node.getTextContent()), SIGNATURE_CLOSE);
    } else if ($isImmutableUnmatchedNode(node)) {
      // Tagged for the same reason as marker glyphs: an unmatched element's BYTES are identical
      // to the literal text it resolves from (`\*` typed as text vs the flagged element), so a
      // bare-text contribution would make that resolution signature-invisible and the
      // fixed-point refusal would block it forever. Its stored marker is part of it too: bytes
      // typed into the element (`\qt-s*` → `\qt-sx*`) re-tokenize into an element spelling them
      // the same way, and only the marker the file gets tells the two apart.
      out.push(
        SIGNATURE_OPEN,
        "unmatched",
        toFragmentText(node.getTextContent()),
        node.getMarker(),
        SIGNATURE_CLOSE,
      );
    } else if ($isRebuildSentinel(node, getMarkerFn)) {
      out.push(ATOMIC_SENTINEL);
    } else if ($isLineBreakNode(node)) {
      out.push(lineBreakFragmentText($isVerseLineBreak(node)));
    } else if ($isTextNode(node) && $getState(node, textTypeState) === "attribute") {
      // Tagged like a glyph: bytes typed into an attribute run at its start read as the span's
      // content once re-tokenized (`\w gracex|g\w*`), and only the run's own delimiting shows
      // that bytes moved from the run into the content rather than the rebuild changing nothing.
      out.push(
        SIGNATURE_OPEN,
        "attribute",
        toFragmentText($textNodeFragmentText(node)),
        SIGNATURE_CLOSE,
      );
    } else if ($isTextNode(node)) {
      let text = $textNodeFragmentText(node);
      if (insideCharChildren) {
        let next = children[index + 1];
        while (splitByMark?.has(next) && $isPlainSignatureText(next, getMarkerFn)) {
          text += $textNodeFragmentText(next);
          index += 1;
          next = children[index + 1];
        }
        text = charOwnChildSignatureText(text);
      }
      out.push(toFragmentText(text));
    } else if ($isCharNode(node)) {
      // A known-marker span that reaches here is NOT a sentinel ($isRebuildSentinel already
      // filtered unknown markers) — fold its own stored `unknownAttributes` into the signature
      // alongside its recursed children. The attribute display run is a DERIVED CACHE
      // (attributeDisplay.utils.ts) that can lag the node's true attribute state — e.g. the run
      // was deleted but the field is still stale — so comparing children text alone could
      // mistake a genuine attribute change for a fixed point.
      out.push(SIGNATURE_OPEN, "char", JSON.stringify(node.getUnknownAttributes() ?? null));
      const { nodes, splitByMark: charSplitByMark } = $charChildrenThroughMarks(node.getChildren());
      $appendSignature(nodes, out, getMarkerFn, true, charSplitByMark);
      out.push(SIGNATURE_CLOSE);
    } else if ($isTypedMarkNode(node)) {
      // Transparent, mirroring `$appendNodesFragment`'s own wrapper branch: an annotation is a
      // host overlay, not document content, and the fragment the rebuilt side is tokenized from
      // carries only its children's bytes. Tagging the wrapper here would make every annotated
      // paragraph compare unequal to its own re-tokenization forever — a scope that can never
      // report a fixed point re-splices, and re-notifies the host, on every settle it is driven
      // through. A mark inside a CharNode never reaches here: the CharNode branch flattens its
      // children through their marks first, so text a mark split is signed joined.
      $appendSignature(node.getChildren(), out, getMarkerFn, insideCharChildren);
    } else if ($isElementNode(node)) {
      out.push(SIGNATURE_OPEN, node.getType());
      $appendSignature(node.getChildren(), out, getMarkerFn);
      out.push(SIGNATURE_CLOSE);
    } else {
      out.push(ATOMIC_SENTINEL);
    }
  }
}

/**
 * Exported for the read-only settle (virtualSettle.utils.ts): it computes this SAME signature for
 * the CURRENT live paragraph, to compare against a JSON-side mirror of this function run over the
 * freshly-rebuilt (but not yet materialized into live nodes) output — the fixed-point refusal
 * `$rebuildParas` applies below must not silently become optional just because the read-only path
 * cannot create nodes to run this live-node version on both sides.
 */
export function $signatureOf(nodes: LexicalNode[], getMarkerFn: MarkerLookup): string {
  const out: string[] = [];
  $appendSignature(nodes, out, getMarkerFn);
  return out.join("");
}

/** A serialized element's children, or `undefined` for a leaf. */
export function serializedChildren(
  node: SerializedLexicalNode,
): SerializedLexicalNode[] | undefined {
  const { children } = node as { children?: SerializedLexicalNode[] };
  return Array.isArray(children) ? children : undefined;
}

/** A serialized TextNode's text, or `undefined` for anything else. */
export function serializedText(node: SerializedLexicalNode): string | undefined {
  const { text } = node as { text?: string };
  return typeof text === "string" ? text : undefined;
}

/** A serialized text node's `textTypeState` tag (Lexical keeps node state under `$`), or
 * `undefined` for a node with none. */
function serializedTextType(node: SerializedLexicalNode): unknown {
  return (node as { $?: { textType?: unknown } }).$?.textType;
}

/** A serialized node's own `type` tag, or `""` for a shape with none. */
export function serializedType(node: SerializedLexicalNode): string {
  return (node as { type?: string }).type ?? "";
}

/** A serialized MarkerNode's canonical glyph text, re-derived from `marker`/`markerSyntax`/
 * `nested` — the exact mirror of `MarkerNode.ts`'s own (unexported) `getMarkerText`. */
export function serializedMarkerGlyphText(
  marker: string,
  markerSyntax: string | undefined,
  nested: boolean | undefined,
): string {
  if (markerSyntax === "closing") return closingMarkerText(marker, nested);
  if (markerSyntax === "selfClosing") return closingMarkerText("");
  return openingMarkerText(marker, nested);
}

/**
 * The children of an `attribute-run` wrapper sibling at `nodes[index]`, or `undefined` when that
 * slot is not one. `usjEditorAdaptor.serializeEditorState` (usj-editor.adaptor.ts, editable mode)
 * always wraps a fresh verse's `\va`/`\vp` triplet or a milestone's display run this way
 * (`addVerseAttributeRun`/`addMilestoneAttributeRun`) — `rebuilt` below is exactly that adaptor's
 * own canonical output, so a loose, unwrapped run never appears in it.
 */
export function serializedRunWrapperChildren(
  nodes: SerializedLexicalNode[],
  index: number,
): SerializedLexicalNode[] | undefined {
  const sibling = nodes[index];
  if (!sibling || serializedType(sibling) !== "attribute-run") return undefined;
  return serializedChildren(sibling) ?? [];
}

/**
 * JSON-serialized mirror of `$appendSignature`/`$signatureOf` above, for a FRESHLY-SERIALIZED
 * rebuild tree — never arbitrary live-tree debris, since that is the only tree this ever runs
 * over. This is the JSON side of the ONE fixed-point comparison BOTH settles make against
 * `$signatureOf` of the live scope, and both make it for their own load-bearing reason:
 *
 * - The MUTATING settle (`$rebuildParas` and its note/chapter siblings below) computes it on the
 *   serialized rebuild BEFORE `$parseSerializedNode`, so a refusal materializes NO live nodes.
 *   That is what makes a refused re-settle a true no-op: parse orphans count as dirty leaves,
 *   which turn a refusal into a real commit — reconciliation, a DOM selection round trip, and a
 *   follow-on caret-normalization commit that can displace the caret out from under an active
 *   gesture (observed: a caret parked in span content yanked to the paragraph glyph, so the next
 *   keystrokes landed outside the span).
 * - The READ-ONLY settle cannot parse at all (Lexical forbids creating nodes inside a `read()`),
 *   and without the refusal a rebuild the mutating settle would refuse as a no-op (its own
 *   displayed bytes are already what re-tokenizing them produces, once normalized — e.g. a
 *   structural NBSP separator and a user's own typed space both collapse to the same plain
 *   space) would get spliced into its OUTPUT, silently replacing the user's own
 *   currently-displayed bytes with a DIFFERENT-looking (though equivalent-by-signature) rebuild.
 *
 * One computation feeding both is also what keeps the two settles' refusal decisions from ever
 * drifting apart — a drift here is a fixed-point disagreement, i.e. the editor refusing to
 * converge.
 *
 * Never needs `$isRebuildSentinel`'s node-kind classification — NOT because a sentinel-class kind
 * (a note, an opaque block, a non-re-tokenizable milestone, a char span with unrecoverable
 * attributes) can never appear FRESH here: it can. An unknown marker typed inside note content,
 * for instance, tokenizes into a genuinely fresh "char" entry carrying `unknownAttributes`, which
 * this function's own "char" branch below walks structurally rather than collapsing to one
 * opaque character the way `$appendSignature` collapses its LIVE counterpart. The mirror stays
 * safe anyway: a freshly-emitted sentinel-class node is, by definition, content that was NOT
 * already sitting in the OLD live tree in that same opaque form, so `$signatureOf` of the old
 * content can never equal what this function produces for it — the comparison this function feeds
 * comes out UNEQUAL either way, which is exactly what correctly drives a splice instead of a
 * mistaken no-op refusal. A matching signature is the only outcome that would need this function
 * to classify a node identically to `$appendSignature`, and a fresh sentinel-class node can never
 * produce one against content that didn't already contain it.
 *
 * Its one classification asymmetry with `$appendSignature` is unreachable rather than deliberate:
 * the live side treats a `TypedMarkNode` TRANSPARENTLY (an annotation is a host overlay, not
 * document content) while this side has no mark branch and would tag one in its generic element
 * branch below — but a mark contributes no bytes to the fragment a rebuild is tokenized from, so
 * the rebuilt side never carries the comment-milestone bytes a serialized mark is built out of
 * (`replaceMilestonesWithMarkRecurse`, usj-editor.adaptor.ts). Were one ever to reach here, the
 * comparison would come out UNEQUAL, which splices rather than mistakenly refuses.
 */
export function serializedSignatureOf(
  nodes: SerializedLexicalNode[],
  getMarkerFn: MarkerLookup,
): string {
  const out: string[] = [];
  appendSerializedSignature(nodes, out, getMarkerFn);
  return out.join("");
}

/**
 * `insideCharChildren` is true only while appending a "char" node's OWN direct children (set by
 * this function's own "char" branch below) — the JSON-side mirror of `$appendSignature`'s own
 * `insideCharChildren` parameter above, including how it resets for anything nested one level
 * deeper that is not itself another "char" node.
 */
function appendSerializedSignature(
  children: SerializedLexicalNode[],
  out: string[],
  getMarkerFn: MarkerLookup,
  insideCharChildren = false,
): void {
  for (let index = 0; index < children.length; index++) {
    const node = children[index];
    const type = serializedType(node);
    if (type === "ms") {
      // Mirrors `$appendSignature`'s milestone branch: fold sid/eid/unknownAttributes in
      // alongside the recursed run, since the run's OWN text alone cannot distinguish a
      // re-tokenization from a stale display cache. Every fresh "ms" entry here IS
      // re-tokenizable by construction (see this function's own doc comment), so the
      // `$isReTokenizableMilestone` check is a defensive mirror, not a load-bearing gate.
      const milestone = node as {
        marker?: string;
        sid?: string;
        eid?: string;
        unknownAttributes?: unknown;
        attributeOrder?: unknown;
      };
      const runChildren = serializedRunWrapperChildren(children, index + 1);
      if (runChildren && $isReTokenizableMilestone(milestone.marker ?? "", getMarkerFn)) {
        out.push(
          SIGNATURE_OPEN,
          "ms",
          // `marker` mirrored from `$appendSignature`'s fold: a glyph RENAME leaves the displayed
          // bytes identical on both sides, so only the milestone's own stale `marker` reveals the
          // rebuild is not a no-op — and `marker` is exactly what the save leg serializes.
          // `attributeOrder` mirrored from `$appendSignature`'s fold: an attribute REORDER
          // (values unchanged) is a real document change — serialized key order follows it.
          JSON.stringify({
            marker: milestone.marker ?? "",
            sid: milestone.sid ?? null,
            eid: milestone.eid ?? null,
            unknownAttributes: milestone.unknownAttributes ?? null,
            attributeOrder: milestone.attributeOrder ?? null,
          }),
        );
        appendSerializedSignature(runChildren, out, getMarkerFn);
        out.push(SIGNATURE_CLOSE);
        index += 1;
      } else {
        out.push(ATOMIC_SENTINEL);
      }
      continue;
    }
    if (type === "verse") {
      // Mirrors `$appendSignature`'s verse branch. `unknownAttributes` has no display
      // representation at all, so a verse carrying it stays a sentinel on the live side
      // (`verseNeedsSentinel`) and can never appear fresh here either — this branch is a
      // defensive mirror of that, not a load-bearing gate (see this function's doc comment).
      const verse = node as {
        text?: string;
        number?: string;
        altnumber?: string;
        pubnumber?: string;
        unknownAttributes?: unknown;
      };
      if (verse.unknownAttributes) {
        out.push(ATOMIC_SENTINEL);
        continue;
      }
      out.push(
        SIGNATURE_OPEN,
        "verse",
        toFragmentText(verse.text ?? ""),
        JSON.stringify({
          number: verse.number ?? null,
          altnumber: verse.altnumber ?? null,
          pubnumber: verse.pubnumber ?? null,
        }),
      );
      // A verse can carry up to two independent wrapped runs (`\va` then `\vp`), each its own
      // immediately-following `attribute-run` sibling — mirrors `$verseAttributeRun`'s wrapped
      // case, the only shape a fresh, canonical rebuild ever produces.
      let consumed = 0;
      let runChildren = serializedRunWrapperChildren(children, index + 1 + consumed);
      while (runChildren) {
        appendSerializedSignature(runChildren, out, getMarkerFn);
        consumed++;
        runChildren = serializedRunWrapperChildren(children, index + 1 + consumed);
      }
      out.push(SIGNATURE_CLOSE);
      index += consumed;
      continue;
    }
    if (type === "marker") {
      // Delimited and tagged, mirroring `$appendSignature`'s marker branch — not the generic text
      // fallback below, which a bare `.text` field would otherwise match first. The glyph's own
      // `.text` field is NOT read: `usjEditorAdaptor.serializeEditorState`'s `createMarker` helper
      // builds this JSON directly (never through a live `MarkerNode`, whose `getTextContent()` is
      // itself computed from `marker`/`markerSyntax`/`nested`, never stored independently — see
      // `MarkerNode.ts`'s `getMarkerText`), and leaves `.text` empty; re-derive the SAME canonical
      // glyph text here instead, exactly as `MarkerNode`'s own `getMarkerText` would.
      const marker = node as { marker?: string; markerSyntax?: string; nested?: boolean };
      out.push(
        SIGNATURE_OPEN,
        "marker",
        toFragmentText(
          serializedMarkerGlyphText(marker.marker ?? "", marker.markerSyntax, marker.nested),
        ),
        SIGNATURE_CLOSE,
      );
      continue;
    }
    if (type === "linebreak") {
      out.push(lineBreakFragmentText(isSerializedVerseNode(children[index + 1])));
      continue;
    }
    if (type === "char") {
      const char = node as { unknownAttributes?: unknown };
      out.push(SIGNATURE_OPEN, "char", JSON.stringify(char.unknownAttributes ?? null));
      appendSerializedSignature(serializedChildren(node) ?? [], out, getMarkerFn, true);
      out.push(SIGNATURE_CLOSE);
      continue;
    }
    // Note/UnknownNode: defensive mirror of `$isRebuildSentinel`'s unconditional sentinel for
    // these kinds — unreachable in practice (see this function's doc comment), never load-bearing.
    if (type === "note" || type === "unknown") {
      out.push(ATOMIC_SENTINEL);
      continue;
    }
    if (type === "unmatched") {
      // Tagged, mirroring `$appendSignature`'s unmatched branch — the bare-text fallback below
      // would otherwise match this node's `.text` field and make the literal→flagged-element
      // resolution signature-invisible on the JSON side.
      const marker = isSerializedImmutableUnmatchedNode(node) ? node.marker : "";
      out.push(SIGNATURE_OPEN, "unmatched", toFragmentText(serializedText(node) ?? ""), marker);
      out.push(SIGNATURE_CLOSE);
      continue;
    }
    const text = serializedText(node);
    if (text !== undefined && serializedTextType(node) === "attribute") {
      // Tagged, mirroring `$appendSignature`'s attribute-run branch.
      out.push(SIGNATURE_OPEN, "attribute", toFragmentText(text), SIGNATURE_CLOSE);
      continue;
    }
    if (text !== undefined) {
      out.push(toFragmentText(insideCharChildren ? charOwnChildSignatureText(text) : text));
      continue;
    }
    const nodeChildren = serializedChildren(node);
    if (nodeChildren) {
      out.push(SIGNATURE_OPEN, type);
      appendSerializedSignature(nodeChildren, out, getMarkerFn);
      out.push(SIGNATURE_CLOSE);
    } else {
      out.push(ATOMIC_SENTINEL);
    }
  }
}

/** U+FFFC occurrences across a serialized tree — the serialize-side half of the symmetry
 * bail-out, for comparisons made before (or without) a parsed tree. */
export function countSerializedSentinels(nodes: SerializedLexicalNode[]): number {
  let count = 0;
  for (const node of nodes) {
    const children = serializedChildren(node);
    if (children) {
      count += countSerializedSentinels(children);
      continue;
    }
    const text = serializedText(node);
    if (text !== undefined)
      for (const character of text) if (character === ATOMIC_SENTINEL) count++;
  }
  return count;
}

function $appendChildrenFragment(
  element: ElementNode,
  out: FragmentAccumulator,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
  charLead?: { pending: boolean },
): void {
  $appendNodesFragment(element.getChildren(), out, getMarkerFn, viewOptions, charLead);
}

/**
 * `charLead`, when given, tracks a char span's ONE structural leading NBSP (see
 * {@link contentFragmentText}): it starts pending at the span's first child and is consumed by
 * the first content-position node — glyphs excluded — whether or not that node is the text that
 * carries the fused prefix (element-first content puts a pure spacer there instead, and any text
 * AFTER an element's slot has a data leading NBSP, never the structural one).
 */
function $appendNodesFragment(
  children: LexicalNode[],
  out: FragmentAccumulator,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
  charLead?: { pending: boolean },
): void {
  // Reads-and-clears the char span's pending structural-lead flag. Called from every
  // content-position branch below; glyphs (MarkerNode) never consume it, and the transparent
  // wrapper branch passes it through instead — a mark wrapper's children sit in the SAME content
  // positions the wrapper occupies.
  const consumeCharLead = (): boolean => {
    const pending = charLead?.pending === true;
    if (charLead) charLead.pending = false;
    return pending;
  };
  for (let index = 0; index < children.length; index++) {
    const node = children[index];
    if ($isMarkerNode(node)) {
      pushText(out, node, toFragmentText(node.getTextContent()));
    } else if ($isMilestoneNode(node)) {
      consumeCharLead();
      // The MilestoneNode itself contributes no bytes (an invisible decorator); its display
      // run is the marker's actual USFM representation. A re-tokenizable milestone's run flows
      // into the fragment as ordinary text — `scanMilestone` re-derives sid/eid/unknownAttributes
      // from it on tokenize, closing the loop that let an edited attribute value settle. A
      // milestone the tokenizer would not re-derive as one (`$isReTokenizableMilestone`) stays a
      // preserved sentinel, node and run together, exactly as before.
      const run = $milestoneDisplayRun(children, index);
      // Require a BYTE-BEARING run for the re-tokenizable path: a bare MilestoneNode (the collab
      // materializer `$createMilestone` builds these with no display-run siblings) would
      // contribute ZERO bytes here, so the rebuild would splice it away entirely — a silent
      // deletion. With no displayable bytes it degrades to an atomic sentinel and survives
      // (the spec's "state not recoverable from displayed bytes → atomic" self-protection).
      if ($isReTokenizableMilestone(node.getMarker(), getMarkerFn) && milestoneRunRendersBytes(run))
        $appendNodesFragment(run, out, getMarkerFn, viewOptions);
      else pushSentinel(out, [node, ...run]);
      index += run.length;
    } else if ($isNoteNode(node) && $isLiteralNoteShell(node)) {
      consumeCharLead();
      // The note's bytes as the screen shows them; the caller text's no-break space is the
      // separator after the caller, as a glyph's is.
      const caller = $noteEditableCallerNode(node);
      for (const child of node.getChildren())
        if (caller?.is(child)) pushText(out, child, toFragmentText(child.getTextContent()));
        else $appendNodesFragment([child], out, getMarkerFn, viewOptions);
    } else if ($isNoteNode(node) || $isUnknownNode(node)) {
      consumeCharLead();
      pushSentinel(out, [node]);
    } else if ($isVerseNode(node)) {
      consumeCharLead();
      // A sentinel verse's \va/\vp display run (attributeDisplay.utils.ts) rides inside its
      // sentinel, node and run together — exactly like a non-re-tokenizable milestone's run
      // above. Re-tokenizing the run's bytes on their own (after the verse's own opaque
      // placeholder) would hand the tokenizer `\va`/`\vp` with no verse to fold onto, degrading
      // them into unrelated standalone markers instead of leaving the paragraph untouched.
      // Otherwise (the common case) the verse's own glyph text flows into the fragment like any
      // other content, immediately followed by its run's bytes as ordinary siblings — the
      // tokenizer's attrCapture folds `\va`/`\vp` right back onto the freshly re-derived verse.
      const run = $verseAttributeRun(children, index);
      if (verseNeedsSentinel(node)) {
        pushSentinel(out, [node, ...run]);
      } else {
        pushText(out, node, toFragmentText($textNodeFragmentText(node)));
        $appendNodesFragment(run, out, getMarkerFn, viewOptions);
      }
      index += run.length;
    } else if ($isCharNode(node)) {
      consumeCharLead();
      // Unknown-marker spans (custom.sty) are not text-recoverable: the tokenizer would degrade
      // them to literal text (preserve-or-refuse). Likewise a span whose attributes have no
      // closing glyph to anchor a display run (`$hasUnrecoverableAttributes`) carries bytes with
      // no visible representation to re-derive from. Otherwise a KNOWN marker's attribute display
      // run (if any) is ordinary text among its children — it re-tokenizes and re-derives via
      // `extractAttributes` like the rest of the span's content. `$charNeedsSentinel` is the
      // shared authority, so this branch and `$isRebuildSentinel` cannot drift apart.
      if ($charNeedsSentinel(node, getMarkerFn)) pushSentinel(out, [node]);
      else $appendChildrenFragment(node, out, getMarkerFn, viewOptions, { pending: true });
    } else if ($isLineBreakNode(node)) {
      consumeCharLead();
      pushText(out, node, lineBreakFragmentText($isVerseLineBreak(node)));
    } else if ($isTextNode(node)) {
      // Glyph-adjacent structural text (the para-prefix separator, attribute runs — whose own
      // leading NBSP is the file's real separator byte before `|…`, a chapter's `\c N` glyph
      // text — whose NBSP is the separator after `\c`) keeps the blanket NBSP-to-space
      // flattening in every view; everything else is a content run, where the flattening is
      // view-dependent (see `contentFragmentText`).
      const parent = node.getParent();
      const isStructuralRun =
        $isMarkerTrailingSeparator(node) ||
        $getState(node, textTypeState) === "attribute" ||
        ($isChapterNode(parent) && !!$chapterGlyphTextNode(parent)?.is(node));
      const structuralLead = consumeCharLead() && !isStructuralRun;
      pushText(
        out,
        node,
        isStructuralRun
          ? toFragmentText($textNodeFragmentText(node))
          : contentFragmentText(
              $textNodeFragmentText(node),
              viewOptions,
              structuralLead,
              $isNbspContentAtMark(node),
            ),
      );
    } else if ($isElementNode(node)) {
      // TypedMarkNode and other transparent wrappers: an annotation is a host overlay, never
      // document content, so only its children's text reaches the tokenizer — in the SAME content
      // positions the wrapper occupies, so a char span's pending structural lead passes through to
      // the wrapper's children instead of being consumed by the wrapper itself. The wrapper is
      // re-applied around the same bytes after the splice (`$restoreMarkByteRanges`), which
      // is the only thing that brings a mark back — nothing here can.
      $appendChildrenFragment(node, out, getMarkerFn, viewOptions, charLead);
    } else {
      consumeCharLead();
      pushSentinel(out, [node]);
    }
  }
}

/**
 * Whether a paragraph scope's fragment opens with a nameless paragraph's glyph: ParatextData reads
 * `\p \ df` as a paragraph whose marker is the empty name, which the editor shows as a bare `\`.
 * Every tokenize of a paragraph scope passes this on, so that `\` re-tokenizes as the marker it
 * shows while a bare `\` anywhere else — including one left by deleting another paragraph
 * marker's name — stays text.
 */
export function $opensNamelessParagraph(paras: readonly LexicalNode[]): boolean {
  const [first] = paras;
  return $isParaNode(first) && first.getMarker() === "";
}

/**
 * Exported for two callers outside this module's own rebuild path. The read-only settle
 * (virtualSettle.utils.ts) builds the SAME fragment a mutating rebuild would, which is what makes
 * the settled USJ a consumer reads and the structure a later real settle produces one computation
 * rather than two implementations. A test also compares a loose-shape paragraph's fragment `.text`
 * against its hand-built wrapped-shape equivalent for byte-for-byte equality
 * (`tier2Rebuild.utils.test.tsx`) — the direct evidence that wrapping a run changes nothing about
 * what gets tokenized.
 */
export function $buildParaFragment(
  para: ParaNode,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): FragmentAccumulator | undefined {
  // Guard rails (preserve-or-refuse): a paragraph the engine cannot fully
  // re-derive from its text is never rebuilt — edits inside it stay literal text.
  if (para.getUnknownAttributes()) return undefined;
  // Known non-paragraph kinds can't be re-derived as paragraphs. Unknown markers
  // now round-trip: the tokenizer emits them as paragraphs in body context (PT9
  // DetermineUnknownTokenType), so they no longer refuse.
  const paraKind = getMarkerFn(para.getMarker())?.type;
  if (
    paraKind !== undefined &&
    paraKind !== MarkerType.Unknown &&
    paraKind !== MarkerType.Paragraph
  )
    return undefined;
  // Paragraphs inside opaque blocks (sidebars, periph, …) stay untouched.
  for (let parent = para.getParent(); parent !== null; parent = parent.getParent())
    if ($isUnknownNode(parent)) return undefined;
  const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  $appendChildrenFragment(para, out, getMarkerFn, viewOptions);
  return out;
}

/**
 * The root's implied paragraph's fragment: its children's bytes, since it has no marker of its
 * own. Only the settled-position basis builds one — for a scope that removes an emptied optbreak
 * husk from it, which nothing re-tokenizes — so its bytes serve to pair the two sides up and are
 * never tokenized.
 */
export function $buildImpliedParaFragment(
  para: ImpliedParaNode,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): FragmentAccumulator {
  const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  $appendChildrenFragment(para, out, getMarkerFn, viewOptions);
  return out;
}

/**
 * One paragraph SCOPE's fragment: each paragraph's own fragment ({@link $buildParaFragment})
 * concatenated, with a single space standing in for the newline between two of them and every
 * span rebased onto the joined text. `undefined` when the scope is empty or any paragraph in it
 * is excluded by the guard rails — a scope the engine cannot fully re-derive is never rebuilt.
 *
 * A scope of more than one paragraph is the unknown-split rejoin ({@link $unknownSplitRejoinScope},
 * markerEditTier1.utils.ts), whose whole point is that the tokenizer must see the JOINED bytes.
 *
 * ONE definition for every consumer of a paragraph scope's bytes: the mutating rebuild
 * ({@link $rebuildParas}), the read-only settle (`$settledParaScope`, virtualSettle.utils.ts) and
 * the settled-position basis (`settledScopes.utils.ts`) all tokenize or byte-map against this
 * text, so a difference in how any of them joined it would put those three out of agreement about
 * what the same scope says.
 *
 * Read-only: walks the nodes, so call inside `editor.update()` or an editor-state read.
 */
export function $buildParaScopeFragment(
  paras: readonly LexicalNode[],
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): FragmentAccumulator | undefined {
  if (paras.length === 0 || !paras.every($isParaNode)) return undefined;
  const combined: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  return $appendParaFragments(combined, paras, getMarkerFn, viewOptions) ? combined : undefined;
}

/**
 * One fragment over a mixed run of root children — paragraphs, the root's implied paragraph, a
 * chapter, a table, a sidebar, a stray char span — for the SETTLED side of a paragraph scope whose
 * typed block marker settled into a top-level item that is not a paragraph. `undefined` when a
 * paragraph's own guard rails ({@link $buildParaFragment}) refuse it.
 *
 * A chapter contributes only its OWN children: its adjacent `\ca`/`\cp` nodes are root children
 * of the same run, so {@link $buildChapterFragment} (which appends them too) would spell them
 * twice. Everything else is walked as {@link $appendNodesFragment} walks any sibling, so a sidebar
 * or other opaque block is one preserved-node sentinel.
 *
 * No separator bytes between the children: a separator names no node, and the live side of the
 * same scope is one paragraph whose text already spells every byte these children do.
 *
 * Only pairs bytes for the settled-position basis; never tokenized.
 */
export function $buildSettledRootFragment(
  nodes: readonly LexicalNode[],
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): FragmentAccumulator | undefined {
  const combined: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  for (const node of nodes) {
    if ($isParaNode(node)) {
      const fragment = $buildParaFragment(node, getMarkerFn, viewOptions);
      if (!fragment) return undefined;
      const base = combined.text.length;
      fragment.spans.forEach((span) =>
        combined.spans.push({ ...span, start: span.start + base, end: span.end + base }),
      );
      combined.sentinels.push(...fragment.sentinels);
      combined.text += fragment.text;
    } else if ($isChapterNode(node))
      $appendNodesFragment(node.getChildren(), combined, getMarkerFn, viewOptions);
    else $appendNodesFragment([node], combined, getMarkerFn, viewOptions);
  }
  return combined;
}

/**
 * Append each of `paras`' fragments to `combined` as the next LINE of one joined scope: a single
 * space stands in for the newline before each line that follows bytes, and every span shifts by
 * where its line lands. This is how a multi-paragraph scope is handed to the tokenizer as the bytes
 * the file would carry — and, since the unknown-split rejoin folds a paragraph back into the `\id`
 * line too, how the line's content and that paragraph are joined.
 *
 * Exported for the read-only settle (virtualSettle.utils.ts), which must build the SAME joined
 * bytes each mutating settle builds.
 *
 * Read-only: call inside `editor.update()` or an editor-state read.
 *
 * @returns `false` when a paragraph is excluded by {@link $buildParaFragment}'s guard rails —
 *   `combined` is then partially filled and must be discarded.
 */
export function $appendParaFragments(
  combined: FragmentAccumulator,
  paras: readonly ParaNode[],
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): boolean {
  for (const para of paras) {
    const fragment = $buildParaFragment(para, getMarkerFn, viewOptions);
    if (!fragment) return false;
    if (combined.text.length > 0) combined.text += " ";
    const base = combined.text.length;
    fragment.spans.forEach((span) =>
      combined.spans.push({ ...span, start: span.start + base, end: span.end + base }),
    );
    combined.sentinels.push(...fragment.sentinels);
    combined.text += fragment.text;
  }
  return true;
}

/** Replace each U+FFFC in the rebuilt tree with the next preserved node run. */
function $replaceSentinels(roots: LexicalNode[], originals: LexicalNode[][]): void {
  let queueIndex = 0;
  const visit = (node: LexicalNode): void => {
    if ($isTextNode(node)) {
      let current: TextNode | undefined = node;
      while (current) {
        const text: string = current.getTextContent();
        const at = text.indexOf(ATOMIC_SENTINEL);
        if (at < 0) break;
        let sentinelNode: TextNode = current;
        let after: TextNode | undefined;
        if (at > 0) [, sentinelNode] = current.splitText(at) as [TextNode, TextNode];
        if (sentinelNode.getTextContent().length > 1)
          [sentinelNode, after] = sentinelNode.splitText(1) as [TextNode, TextNode];
        const run = originals[queueIndex++];
        if (run && run.length > 0) {
          let previous: LexicalNode = sentinelNode;
          for (const original of run) {
            previous.insertAfter(original); // moves it out of the old paragraph
            previous = original;
          }
        }
        sentinelNode.remove();
        current = after;
      }
    } else if ($isElementNode(node)) {
      // copy: children may be replaced while visiting
      [...node.getChildren()].forEach(visit);
    }
  };
  roots.forEach(visit);
}

/**
 * Every VerseNode under `nodes`, depth-first in document order (including a verse nested inside
 * a char span that crosses it, per USFM ≤3.0 — see the crossing-span fixed-point test in
 * tier2Rebuild.utils.test.tsx). Backs sid carry-over in `$rebuildParas`: the OLD side is read into plain data before the
 * splice moves or destroys anything; the NEW side is read once the splice has settled.
 */
function $collectVerseNodes(nodes: LexicalNode[], out: VerseNode[] = []): VerseNode[] {
  for (const node of nodes) {
    if ($isVerseNode(node)) out.push(node);
    else if ($isElementNode(node)) $collectVerseNodes(node.getChildren(), out);
  }
  return out;
}

/** U+FFFC occurrences across a parsed node tree — must equal the preserved-run count. */
function countSentinelNodes(nodes: LexicalNode[]): number {
  let count = 0;
  const visit = (node: LexicalNode): void => {
    if ($isTextNode(node)) {
      for (const ch of node.getTextContent()) if (ch === ATOMIC_SENTINEL) count++;
    } else if ($isElementNode(node)) {
      node.getChildren().forEach(visit);
    }
  };
  nodes.forEach(visit);
  return count;
}

/** U+FFFC occurrences across tokenized content — must equal the preserved-run count. Exported for
 * the read-only settle (virtualSettle.utils.ts), which runs the same symmetry bail-out before it
 * splices anything into its output. */
export function countSentinels(content: MarkerContent[]): number {
  let count = 0;
  for (const item of content) {
    if (typeof item === "string") {
      for (const ch of item) if (ch === ATOMIC_SENTINEL) count++;
    } else if (item.content) {
      count += countSentinels(item.content);
    }
  }
  return count;
}

/** `nodes`' bytes, each node's children as one line of a joined scope, appended to `out` (a fresh
 * fragment when left out). */
function $spansForNodes(
  nodes: LexicalNode[],
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
  out: FragmentAccumulator = { text: "", spans: [], sentinels: [] },
): FragmentAccumulator {
  for (const node of nodes) {
    if (out.text.length > 0) out.text += " ";
    if ($isElementNode(node)) $appendChildrenFragment(node, out, getMarkerFn, viewOptions);
  }
  return out;
}

/**
 * The `\id` line scope's bytes as the tree now spells them: the line's content, then each block
 * after it as a following line — the same joined bytes {@link $rebuildBook} tokenized, read back
 * from the rebuilt nodes. Both settles re-derive a carried mark's bytes from this.
 *
 * Read-only: call inside `editor.update()` or an editor-state read.
 */
function $bookScopeSpans(
  book: BookNode,
  followingBlocks: LexicalNode[],
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): FragmentAccumulator {
  const { out } = $buildBookFragment(book, getMarkerFn, viewOptions);
  return $spansForNodes(followingBlocks, getMarkerFn, viewOptions, out);
}

/**
 * The caret as a BYTE anchor over the span text: how many non-whitespace characters precede it
 * (`nonWsBefore`), plus how many consecutive whitespace characters sit between the last of those
 * and the caret (`wsRun`, usually 0). Anchoring on non-whitespace characters — rather than a raw
 * cumulative character offset — keeps the caret attached to its BYTE across a rebuild that adds,
 * removes, or moves display whitespace around it: the engine's NBSP separators are inserted by
 * the canonical rebuild (a typed `|` that re-tokenizes from a glyph into span content gains a
 * separator BEFORE it, which shifted a cumulative offset to the wrong side of the byte), and the
 * inter-paragraph " " joiners come and go with paragraph splits. Where the settle does spell bytes
 * differently — an attribute section it re-spells, a typed literal it turns into one preserved
 * node — an anchor crosses from one side to the other through the scope's byte alignment
 * (`pairRuns`, settledOnlyRuns.utils.ts) rather than by the same count. A sentinel span counts as
 * its single placeholder char.
 */
export interface CaretByteAnchor {
  nonWsBefore: number;
  wsRun: number;
}

/** The point `anchorOffset` into the span keyed `anchorKey` as a byte anchor over `fragment`, or
 * `undefined` when no span of the fragment has that key. */
export function $caretSpanByteAnchor(
  fragment: { text: string; spans: FragmentSpan[] },
  anchorKey: string,
  anchorOffset: number,
): CaretByteAnchor | undefined {
  let nonWsBefore = 0;
  let wsRun = 0;
  for (const span of fragment.spans) {
    const spanLength = span.end - span.start;
    const isAnchorSpan = span.key === anchorKey;
    const limit = isAnchorSpan
      ? Math.min(span.isSentinel ? 1 : anchorOffset, spanLength)
      : spanLength;
    for (let i = 0; i < limit; i++) {
      if (FRAGMENT_WS.test(fragment.text[span.start + i])) wsRun++;
      else {
        nonWsBefore++;
        wsRun = 0;
      }
    }
    if (isAnchorSpan) return { nonWsBefore, wsRun };
  }
  return undefined;
}

/** Every key in `node`'s subtree, `node` included. */
function $collectKeys(node: LexicalNode, out: Set<NodeKey>): void {
  out.add(node.getKey());
  if ($isElementNode(node)) node.getChildren().forEach((child) => $collectKeys(child, out));
}

/** The span a `(key, offset)` pair addresses, if the fragment carries one for that node. */
export function spanFor(
  fragment: FragmentAccumulator,
  key: NodeKey,
  offset: number,
): FragmentSpan | undefined {
  return fragment.spans.find(
    (span) => !span.isSentinel && span.key === key && offset <= span.end - span.start,
  );
}

/**
 * The byte anchor for a point in a fragment's own tree, plus the byte of `fragment.text` it
 * anchored at. A text point anchors on its own bytes; an ELEMENT point is a boundary between
 * children, which anchors at the END of the last byte before it — the one spelling that is stable
 * when the boundary happens to sit in front of a preserved node, whose inner bytes are not
 * addressable at all. A boundary in front of all of an element's own content is where that
 * element starts, so it anchors on the element's first byte when there is one to anchor on.
 *
 * Shared by the settle's caret capture and the settled-position translation, so a caret and a
 * position at the same boundary spell the same anchor.
 *
 * Read-only: resolves span node keys, so call inside a read of the tree the fragment was built
 * over.
 */
export function $anchorForPoint(
  fragment: FragmentAccumulator,
  node: LexicalNode,
  offset: number,
): { anchor: CaretByteAnchor; position: number } | undefined {
  const anchored = (key: NodeKey, keyOffset: number) => {
    const anchor = $caretSpanByteAnchor(fragment, key, keyOffset);
    const span = spanFor(fragment, key, keyOffset);
    return anchor && span ? { anchor, position: span.start + keyOffset } : undefined;
  };
  // Deliberately not through `anchored`: the span before the boundary may be a preserved node's
  // one-byte SENTINEL, which `spanFor` refuses (its inner bytes are not addressable). The END of
  // that byte is exactly what the boundary means — just past the construct — and
  // `$caretSpanByteAnchor` spells a sentinel's end without trouble. A boundary in FRONT of a
  // sentinel is the case that genuinely has no spelling, and it is the fragment-start branch
  // below that refuses it.
  const anchoredAfter = (span: FragmentSpan) => {
    const keyOffset = span.end - span.start;
    const anchor = $caretSpanByteAnchor(fragment, span.key, keyOffset);
    return anchor ? { anchor, position: span.start + keyOffset } : undefined;
  };
  if (!$isElementNode(node)) return anchored(node.getKey(), offset);
  const before = new Set<NodeKey>();
  node
    .getChildren()
    .slice(0, offset)
    .forEach((child) => $collectKeys(child, before));
  const last = [...fragment.spans].reverse().find((span) => before.has(span.key));
  if (last) return anchoredAfter(last);

  // Nothing of the element's own is before the boundary, so it sits where the element starts —
  // the fragment's start only when the element opens the fragment. In front of the element's
  // first byte is the precise spelling: a boundary past the previous paragraph's last byte would
  // resolve into that paragraph wherever the two are joined by whitespace.
  const inside = new Set<NodeKey>();
  $collectKeys(node, inside);
  const firstInside = fragment.spans.find((span) => inside.has(span.key));
  if (firstInside && !firstInside.isSentinel) return anchored(firstInside.key, 0);
  // An element that opens with a preserved node, or holds no bytes at all, has no first byte to
  // stand in front of, so the boundary is spelled from the byte before the element instead.
  const lastOutside = [...fragment.spans]
    .reverse()
    .find((span) => !inside.has(span.key) && $getNodeByKey(span.key)?.isBefore(node));
  if (lastOutside) return anchoredAfter(lastOutside);
  // Nothing before the element either: it is the fragment's own start, which only a non-sentinel
  // first span can express — a sentinel anchor counts its placeholder byte and would land PAST the
  // construct rather than in front of it.
  const first = fragment.spans[0];
  return first && !first.isSentinel ? anchored(first.key, 0) : undefined;
}

/**
 * Whether a span is a CLOSING (or self-closing) marker glyph. The caret never lands on such a
 * glyph: a completed closer (`\nd*`) has the caret belong on the content AFTER it, not inside the
 * glyph where continued typing would edit the marker. An OPENING glyph is deliberately NOT matched
 * here — a half-typed opener keeps the caret in the glyph so the user can extend the marker name.
 *
 * Exported for the settled-position translation's own closing-glyph handling — a settled caret
 * inside a typed closer reports that closer, by the same span rule as here.
 */
export function $isClosingMarkerSpan(span: FragmentSpan): boolean {
  if (span.isSentinel) return false;
  const node = $getNodeByKey(span.key);
  return $isMarkerNode(node) && node.getMarkerSyntax() !== "opening";
}

/**
 * The position AFTER a closing marker glyph's enclosing span — the append position in the
 * paragraph, PAST the whole char span — for a typed closer (`\nd*`) at paragraph END with nothing
 * after it. The forward scan skips closing glyphs to land on the following content; when there IS no
 * following content (para end), the position still belongs after the closer, not at the end of the
 * span's inner text (which is the closer glyph's start-of-glyph boundary, i.e. INSIDE the span,
 * where continued typing edits within the marker). Reported as the element boundary just past the
 * span, whose closer is its last child.
 *
 * Only a genuine char-span closer has an enclosing span to escape from this way. A verse's
 * `\va`/`\vp` closer and a milestone's self-closing `\*` are never wrapped in a char span — they
 * ride as ordinary PARAGRAPH siblings (`$verseAttributeRun`/`$milestoneDisplayRun`), so the
 * glyph's parent is the paragraph itself. A boundary past the PARAGRAPH would move the point past
 * the whole paragraph (into the next block, or off the end of the document), not just past the
 * closer within it, so a paragraph-direct closer returns nothing and falls through to the caller's
 * other fallback instead.
 *
 * Exported for the settled-position translation, which also needs the point just past a closer
 * that is not the last span of its own fragment (a char closer directly followed by a note's own
 * closer, say) — a case this function already answers correctly on its own terms.
 */
export function $pointAfterClosingSpan(span: FragmentSpan): FragmentPoint | undefined {
  const glyph = $getNodeByKey(span.key);
  if (!$isMarkerNode(glyph)) return undefined;
  const enclosingSpan = glyph.getParent();
  if (!$isCharNode(enclosingSpan)) return undefined;
  const parent = enclosingSpan.getParent();
  if (!parent) return undefined;
  return {
    key: parent.getKey(),
    offset: enclosingSpan.getIndexWithinParent() + 1,
    type: "element",
  };
}

/**
 * The position AFTER a preserved node run the caret cannot enter — the append position past the
 * whole opaque construct — for an offset that ran off the end of a fragment whose last span is a
 * sentinel. The sibling of {@link $pointAfterClosingSpan}, for the other span kind the forward
 * scan skips: without it the caller's reverse-find walks BACKWARD past the construct and parks the
 * caret at the end of the preceding text, so a figure completed at the end of a paragraph leaves
 * everything typed next on the WRONG SIDE of it (`hello \fig …\fig*` + ` world` became
 * `hello  world\fig …\fig*`, doubled space included).
 *
 * A sentinel span records only the run's FIRST node, and a verse or milestone rides in its
 * sentinel together with its display run (`$appendNodesFragment`), so the append position is past
 * that run's LAST node — the boundary after the first would land inside the run. Every other
 * sentinel kind (unknown blocks, notes, unrecoverable char spans) is a one-node run and skips the
 * lookup.
 */
function $pointAfterSentinelRun(span: FragmentSpan): FragmentPoint | undefined {
  const first = $getNodeByKey(span.key);
  const parent = first?.getParent();
  const siblings = parent?.getChildren();
  if (!first || !parent || !siblings) return undefined;
  const index = siblings.findIndex((sibling) => sibling.is(first));
  if (index < 0) return undefined;
  const run = $isVerseNode(first)
    ? $verseAttributeRun(siblings, index)
    : $isMilestoneNode(first)
      ? $milestoneDisplayRun(siblings, index)
      : [];
  const last = run[run.length - 1] ?? first;
  return { key: parent.getKey(), offset: last.getIndexWithinParent() + 1, type: "element" };
}

/**
 * Where `anchor` (see {@link $caretSpanByteAnchor}) lands within `fragment`'s spans — a text
 * point in the span holding the byte, or, for a position that ran past every addressable span, an
 * ELEMENT boundary just past the construct the position belongs after
 * ({@link $pointAfterClosingSpan}, {@link $pointAfterSentinelRun}). `undefined` when the fragment
 * has no addressable span at all.
 *
 * Direction-agnostic: the mutating rebuild resolves a caret it captured from the pre-rebuild tree
 * into the fresh one ({@link $selectAtFragmentByteAnchor}), and the settled-position translation
 * resolves a byte of the settled document into the live tree. Both ask the same question — which
 * node and offset holds the byte this anchor names — so both walk this one implementation.
 *
 * `addressDisplayBytes` switches from CARET addressing to BYTE addressing, for a position that
 * names a USFM byte rather than a place the caret can rest. A caret never lands inside a completed
 * closing glyph and never at the front edge of one construct when the back edge of the previous
 * one says the same thing, so caret addressing skips closers and prefers the span the walk
 * finished in; a position that names `\nd*`'s second byte, or the `\` a marker starts with, needs
 * exactly those two spellings back.
 *
 * `endAfterSkippedConstruct` is for a position that ends a covered range rather than one a caret
 * rests at. One satisfied exactly at the end of a span caret addressing skips — a closing glyph or
 * a preserved node — and followed by another such span is the boundary right after the first
 * construct ({@link $pointAfterClosingSpan}, {@link $pointAfterSentinelRun}). Searching on would
 * carry the range's end past the second, such as a footnote right after `\nd*`. Followed by an
 * addressable span, the start of that span is the same boundary, and is kept: it is the spelling a
 * range over nothing but a preserved node resolves both its ends to.
 *
 * Read-only: resolves span node keys, so call inside `editor.update()` or an editor-state read.
 */
export function $resolveFragmentByteAnchor(
  fragment: { text: string; spans: FragmentSpan[] },
  anchor: CaretByteAnchor,
  {
    addressDisplayBytes = false,
    endAfterSkippedConstruct = false,
  }: { addressDisplayBytes?: boolean; endAfterSkippedConstruct?: boolean } = {},
): FragmentPoint | undefined {
  const { text, spans } = fragment;
  let best: { key: string; offset: number } | undefined;
  // The end of the span a byte position was satisfied at, held while the next span is looked for.
  let endOfSatisfied: { key: string; offset: number } | undefined;
  let remainingNonWs = anchor.nonWsBefore;
  let remainingWs = anchor.wsRun;
  // Whether the anchor position resolved INSIDE a span the caret cannot rest in — a sentinel
  // (inner text not addressable) or a closing marker glyph (see $isClosingMarkerSpan) — in which
  // case the position belongs at the start of the NEXT addressable span.
  let needNextAddressable = false;
  outer: for (const [index, span] of spans.entries()) {
    const spanLength = span.end - span.start;
    const addressable = !span.isSentinel && (addressDisplayBytes || !$isClosingMarkerSpan(span));
    if (needNextAddressable) {
      if (!addressable) continue;
      best = { key: span.key, offset: 0 };
      break;
    }
    for (let i = 0; i < spanLength; i++) {
      const ch = text[span.start + i];
      if (remainingNonWs === 0 && (remainingWs === 0 || !FRAGMENT_WS.test(ch))) {
        // The anchor's bytes are all behind us (any unconsumed ws run is clamped to the ws
        // actually present here): the position is immediately BEFORE this character.
        if (addressable) {
          best = { key: span.key, offset: i };
          break outer;
        }
        needNextAddressable = true;
        continue outer;
      }
      if (remainingNonWs > 0) {
        if (!FRAGMENT_WS.test(ch)) remainingNonWs--;
      } else remainingWs--;
    }
    if (remainingNonWs === 0 && remainingWs === 0) {
      // Satisfied exactly at this span's end. A caret prefers the end of the span the walk
      // finished in over the start of the next; a byte position prefers the span whose bytes it
      // names, which is the next one — unless that is a preserved node's placeholder, whose front
      // no position can name, where the end of this span is the same place.
      const nextIsSentinel = spans[index + 1]?.isSentinel === true;
      if (addressable && (!addressDisplayBytes || nextIsSentinel)) {
        best = { key: span.key, offset: spanLength };
        break;
      }
      const next = spans[index + 1];
      if (
        endAfterSkippedConstruct &&
        !addressable &&
        next &&
        (next.isSentinel || $isClosingMarkerSpan(next))
      ) {
        const after = span.isSentinel ? $pointAfterSentinelRun(span) : $pointAfterClosingSpan(span);
        if (after) return after;
      }
      // Past one preserved node and in front of the next: neither has a byte a position can rest
      // on, and the next addressable span is past the second node, so the position is the
      // boundary between the two.
      if (span.isSentinel && nextIsSentinel) {
        const between = $pointAfterSentinelRun(span);
        if (between) return between;
      }
      if (addressable) endOfSatisfied = { key: span.key, offset: spanLength };
      needNextAddressable = true;
    }
  }
  if (best) return { ...best, type: "text" };
  // A byte position satisfied at the end of the last span it could name, with nothing after it:
  // the end of those bytes, a closer's included. Whitespace the anchor counts past them that the
  // fragment does not have is clamped away, as it is in front of a byte.
  if (endOfSatisfied) return { ...endOfSatisfied, type: "text" };
  const final = spans[spans.length - 1];
  if (
    addressDisplayBytes &&
    remainingNonWs === 0 &&
    final &&
    !final.isSentinel &&
    final.end === text.length
  )
    return { key: final.key, offset: final.end - final.start, type: "text" };
  // The offset ran past every addressable span. Both span kinds the forward scan skips can be
  // the last thing in the fragment, and for both the position belongs AFTER them — an append
  // position in the paragraph — rather than at the end of the preceding text, which is where the
  // reverse-find fallback below would park it: a completed closer glyph (a typed `\nd*` at
  // paragraph end, nothing after), so continued typing is unstyled; or a sentinel, so continued
  // typing lands past the opaque construct instead of in front of it.
  const lastSpan = spans[spans.length - 1];
  if (lastSpan && $isClosingMarkerSpan(lastSpan)) {
    const point = $pointAfterClosingSpan(lastSpan);
    if (point) return point;
  }
  if (lastSpan?.isSentinel) {
    const point = $pointAfterSentinelRun(lastSpan);
    if (point) return point;
  }
  const last = [...spans].reverse().find((span) => !span.isSentinel && !$isClosingMarkerSpan(span));
  if (last) return { key: last.key, offset: last.end - last.start, type: "text" };
  return undefined;
}

/**
 * One `type:id` pair an annotation mark carries, together with the host callbacks registered for
 * it. Held as plain data (never a reference to the node's own callback maps), so it stays readable
 * after the node it came from has been spliced away.
 */
interface CarriedAnnotation {
  type: string;
  id: string;
  onClick?: TypedMarkOnClick;
  onRemove?: TypedMarkOnRemove;
  onMouseEnter?: TypedMarkOnMouseEnter;
  onMouseLeave?: TypedMarkOnMouseLeave;
}

/**
 * Where a carried mark BEGINS.
 *
 * `"byte"` is the ordinary case: a fragment byte anchor, read and resolved exactly the way the
 * caret's is.
 *
 * `"preserved"` is a mark that starts ON a preserved node — a note, an unrecoverable char span, a
 * sentinel verse or milestone run. Such a node contributes ONE U+FFFC placeholder to the fragment,
 * and NO byte position can name the boundary in front of it: a caret can never rest inside a
 * placeholder, so the anchor walk and the resolve both read a position on it as being AFTER the
 * node it stands for. The anchor here is therefore the position just past the run, and the run
 * itself is pulled back into the mark afterwards ({@link $extendMarkOverPreservedRun}). The run is
 * named by its index in the captured fragment's run list, which the restore pairs with the rebuilt
 * fragment's own run list (`pairRuns`) to find the same run there.
 */
type MarkStart =
  | { kind: "byte"; anchor: CaretByteAnchor }
  | { kind: "preserved"; anchor: CaretByteAnchor; run: number };

/**
 * One annotated range lifted out of a settle scope before the scope's bytes are re-tokenized: the
 * annotations it carries, and the two positions bracketing the bytes it covers. The range comes
 * either from an annotation mark, over the text the mark wraps, or from a display-byte carrier
 * (`displayAnnotationsState`), over the `[start, end)` bytes the carrier holds the annotation on.
 * A carrier is rebuilt as a fresh node, so its state needs carrying just as a mark does.
 *
 * A `TypedMarkNode` is TRANSPARENT in the fragment ({@link $appendNodesFragment}) — its text bytes
 * belong to its children's spans and the wrapper contributes none of its own — so re-tokenization
 * cannot reproduce it, and a splice that carried nothing across would drop every annotation
 * inside the paragraph the user is editing. Both ends anchor the way the caret does
 * ({@link $caretSpanByteAnchor}), so a mark follows its bytes through a rebuild that adds,
 * removes, or moves display whitespace around them.
 *
 * The END needs no preserved-node special case: a byte anchor that consumes the placeholder
 * resolves to the boundary just past the node, which is exactly where a mark ending on one stops.
 */
interface MarkByteRange {
  annotations: CarriedAnnotation[];
  start: MarkStart;
  end: CaretByteAnchor;
}

/** Every `TypedMarkNode` under `nodes`, depth-first. A mark nested inside another (the transient
 * shape `registerNestedElementResolver` un-nests) is collected as its own range. */
function $collectTypedMarks(nodes: LexicalNode[], out: TypedMarkNode[] = []): TypedMarkNode[] {
  for (const node of nodes) {
    if ($isTypedMarkNode(node)) out.push(node);
    if ($isElementNode(node)) $collectTypedMarks(node.getChildren(), out);
  }
  return out;
}

/** `node` and everything under it, by key — the span owners whose bytes a mark wraps. */
function $subtreeKeys(node: LexicalNode, out = new Set<NodeKey>()): Set<NodeKey> {
  out.add(node.getKey());
  if ($isElementNode(node)) node.getChildren().forEach((child) => $subtreeKeys(child, out));
  return out;
}

/**
 * Where a mark whose first covered span is `first` begins, `offset` bytes into it. A sentinel span
 * also carries its run's index, because its byte anchor names the position PAST the preserved node
 * rather than in front of it — see {@link MarkStart}.
 *
 * Read-only: walks the fragment's spans, so call inside `editor.update()` or an editor-state read.
 */
function $markStartAt(
  fragment: FragmentAccumulator,
  first: FragmentSpan,
  offset: number,
): MarkStart | undefined {
  const anchor = $caretSpanByteAnchor(fragment, first.key, offset);
  if (!anchor) return undefined;
  // `pushSentinel` records a run and its placeholder span together, so the n-th sentinel span is
  // the n-th run's placeholder.
  return first.isSentinel
    ? {
        kind: "preserved",
        anchor,
        run: fragment.spans.filter((span) => span.isSentinel).indexOf(first),
      }
    : { kind: "byte", anchor };
}

/**
 * The annotation marks a settle scope held, lifted out before its splice: their byte ranges, and
 * the scope's bytes and preserved runs as plain data, which is what lines the captured bytes up
 * with the rebuilt ones afterwards (`pairRuns`) once the nodes they were read from are gone.
 */
interface CapturedMarks {
  ranges: MarkByteRange[];
  /** Undefined when there are no ranges to carry, so a scope without marks pays nothing for it. */
  live: LiveRunSide | undefined;
}

/**
 * Every annotation mark in `scope`, and every range a display-byte carrier in it holds, as byte
 * ranges over `fragment`. Read BEFORE the splice, since the marks and carriers live on nodes the
 * splice destroys.
 *
 * A mark or carrier whose bytes are not in the fragment at all is skipped rather than guessed at:
 * that is one inside a preserved node (a note, an unrecoverable char span), which the splice moves
 * across whole and which therefore needs no carry.
 *
 * `carried` lists, per run of `fragment.sentinels`, the members the rebuild carries into its
 * output — every member, for a mutating rebuild, which moves each preserved run across whole.
 *
 * `callbacksFrom` is the editor whose display-annotation registrations supply a carrier range's
 * host callbacks, which a carrier has no mark node to hold. A read-only caller leaves it out, and
 * the ranges it captures carry no callbacks.
 *
 * Read-only: walks live nodes, so call inside `editor.update()` or an editor-state read.
 */
function $captureMarkByteRanges(
  scope: LexicalNode[],
  fragment: FragmentAccumulator,
  carried: readonly (readonly LexicalNode[])[] = fragment.sentinels,
  callbacksFrom?: LexicalEditor,
): CapturedMarks {
  const ranges: MarkByteRange[] = [];
  for (const mark of $collectTypedMarks(scope)) {
    const owners = $subtreeKeys(mark);
    const covered = fragment.spans.filter((span) => owners.has(span.key));
    // A mark's carried start is its first covered byte, a char span's opener glyph included: the
    // wrap holds a glyph's annotation on the glyph and keeps the opener's separator out on its own
    // (`$charSeparatorPrefixLength`), so starting on the glyph neither tears the span nor takes
    // the separator.
    const first = covered[0];
    const last = covered[covered.length - 1];
    if (!first || !last) continue;
    const start = $markStartAt(fragment, first, 0);
    const end = $caretSpanByteAnchor(fragment, last.key, last.end - last.start);
    if (!start || !end) continue;
    const onClicks = mark.getTypedOnClicks();
    const onRemoves = mark.getTypedOnRemoves();
    const onMouseEnters = mark.getTypedOnMouseEnters();
    const onMouseLeaves = mark.getTypedOnMouseLeaves();
    const annotations = Object.entries(mark.getTypedIDs()).flatMap(([type, ids]) =>
      ids.map((id) => ({
        type,
        id,
        onClick: onClicks[type]?.[id],
        onRemove: onRemoves[type]?.[id],
        onMouseEnter: onMouseEnters[type]?.[id],
        onMouseLeave: onMouseLeaves[type]?.[id],
      })),
    );
    if (annotations.length > 0) ranges.push({ annotations, start, end });
  }
  // Display bytes hold their annotations themselves (`displayAnnotationsState`), each range
  // captured like a mark's. A carrier with no span of its own is inside a preserved node, whose
  // state rides across on the same node. A whole-decorator range `(0, 0)` names no bytes to carry;
  // in Standard view such decorators only sit inside preserved notes.
  const $collect = (node: LexicalNode): void => {
    const key = node.getKey();
    for (const held of $displayAnnotationsOf(node)) {
      if (held.start === held.end || !spanFor(fragment, key, held.start)) continue;
      const start = $caretSpanByteAnchor(fragment, key, held.start);
      const end = $caretSpanByteAnchor(fragment, key, held.end);
      if (!start || !end) continue;
      const registration =
        callbacksFrom && getDisplayAnnotationRegistration(callbacksFrom, held.type, held.id);
      ranges.push({
        annotations: [
          {
            type: held.type,
            id: held.id,
            onClick: registration?.onClick,
            onRemove: registration?.onRemove,
            onMouseEnter: registration?.onMouseEnter,
            onMouseLeave: registration?.onMouseLeave,
          },
        ],
        start: { kind: "byte", anchor: start },
        end,
      });
    }
    if ($isElementNode(node)) node.getChildren().forEach($collect);
  };
  scope.forEach($collect);
  return { ranges, live: ranges.length > 0 ? $liveRunSide(fragment, carried) : undefined };
}

/**
 * Move the preserved node run beginning at `key` into the front of the mark that now sits directly
 * after it — the second half of restoring a mark that STARTED on a preserved node (see
 * {@link MarkStart}), whose wrap could only cover the content past the run.
 *
 * The run is located by node identity rather than re-resolved, because a preserved node survives
 * the splice as the same node, and a verse or milestone rides together with its display run (the
 * same run definition {@link $pointAfterSentinelRun} uses). A selection boundary would not do the
 * job: an element point in front of an inline element resolves to that element's first LEAF, so
 * wrapping from there would mark the preserved node's INTERNALS instead of the node.
 *
 * Does nothing unless the node after the run really is the mark just built for `type`/`id`, so a
 * shape the wrap did not produce is left alone.
 *
 * Mutating: call inside `editor.update()`, straight after the wrap.
 */
function $extendMarkOverPreservedRun(key: NodeKey, type: string, id: string): void {
  const run = $preservedRunAt(key);
  if (!run) return;
  const mark = run[run.length - 1].getNextSibling();
  if (!$isTypedMarkNode(mark) || !mark.hasID(type, id)) return;
  const target = mark.getFirstChild();
  if (!target) return;
  run.forEach((node) => target.insertBefore(node));
}

/**
 * Wrap the preserved node run beginning at `key` in a fresh mark carrying `annotation` — how a mark
 * over nothing BUT that run is restored. Both of such a mark's anchors land just past the run (see
 * {@link MarkStart}), so they bracket no bytes at all; the run itself, carried across the splice as
 * the same nodes, is the whole range.
 *
 * Mutating: call inside `editor.update()`, after the splice.
 */
function $wrapPreservedRun(key: NodeKey, annotation: CarriedAnnotation): void {
  const run = $preservedRunAt(key);
  if (!run) return;
  const mark = $createTypedMarkNode();
  mark.addID(
    annotation.type,
    annotation.id,
    annotation.onClick,
    annotation.onRemove,
    annotation.onMouseEnter,
    annotation.onMouseLeave,
  );
  run[0].insertBefore(mark);
  mark.append(...run);
}

/** The preserved node run beginning at `key`: the node, plus the display run a verse or milestone
 * rides together with (the same run definition {@link $pointAfterSentinelRun} uses). */
function $preservedRunAt(key: NodeKey): LexicalNode[] | undefined {
  const first = $getNodeByKey(key);
  const siblings = first?.getParent()?.getChildren();
  if (!first || !siblings) return undefined;
  const index = siblings.findIndex((sibling) => sibling.is(first));
  if (index < 0) return undefined;
  const run = $isVerseNode(first)
    ? $verseAttributeRun(siblings, index)
    : $isMilestoneNode(first)
      ? $milestoneDisplayRun(siblings, index)
      : [];
  return [first, ...run];
}

/**
 * Where one end of a carried mark lands in the rebuilt fragment: the point, and the non-whitespace
 * byte count it landed at (in the rebuilt fragment, or in the literal's spelling), plus — for an
 * end INSIDE a node the settle made from typed literal bytes — which of the rebuilt fragment's runs
 * it is inside, and for a start ON a preserved run, that run's first node (see {@link MarkStart}).
 */
interface ResolvedMarkEnd {
  point: FragmentPoint;
  at: number;
  literalRun?: number;
  preservedKey?: NodeKey;
}

/**
 * Where a mark end captured as `anchor` lands in `fragment`, the rebuilt scope's bytes. `pairing`
 * lines the captured bytes up with `fragment`'s: an anchor outside every literal the settle turned
 * into a preserved node is restated through the byte alignment, snapping LEFT when the byte it
 * sits in front of has no rebuilt counterpart (a re-spelled attribute's name); one inside such a
 * literal is resolved in that node's own spelling, on whichever byte of it the anchor names, a
 * marker glyph or an attribute run included — or refused when the settle re-spelled the byte it
 * names, which has no counterpart there.
 *
 * `isStart` selects byte addressing, since a start names the first byte a mark covers (see
 * {@link $restoreMarkByteRanges}). An end resolves as a caret does, except that one right after a
 * closing glyph or a preserved node stays right after it (`endAfterSkippedConstruct`).
 *
 * Read-only: resolves node keys, so call inside `editor.update()` or an editor-state read.
 */
function $resolveMarkEnd(
  anchor: CaretByteAnchor,
  fragment: FragmentAccumulator,
  pairing: RunPairing,
  isStart: boolean,
): ResolvedMarkEnd | undefined {
  const runs = pairing.settledOnlyRuns;
  const options = { addressDisplayBytes: isStart, endAfterSkippedConstruct: !isStart };
  const inside = literalContaining(runs, anchor);
  if (inside) {
    if (!inside.within) return undefined;
    const point = $resolveFragmentByteAnchor(inside.run.spelling, inside.within, options);
    if (!point) return undefined;
    return { point, at: inside.within.nonWsBefore, literalRun: inside.run.sentinelIndex };
  }
  // A mark that starts on a literal's first byte starts on the node the literal became, which
  // no byte position can name the front of — the same case as a mark starting on a preserved
  // node the capture already saw (see `MarkStart`).
  const onRun = isStart && literalStartingAt(runs, anchor);
  if (onRun) {
    const preservedKey = fragment.sentinels[onRun.sentinelIndex]?.[0]?.getKey();
    const past: CaretByteAnchor = {
      nonWsBefore: onRun.settledBefore + 1,
      wsRun: 0,
    };
    const point = $resolveFragmentByteAnchor(fragment, past, options);
    return point && preservedKey ? { point, at: past.nonWsBefore, preservedKey } : undefined;
  }
  const settledAnchor = anchorAcrossLiteralsSnapped(pairing.alignment, anchor, "toSettled");
  const point = $resolveFragmentByteAnchor(fragment, settledAnchor, options);
  return point && { point, at: settledAnchor.nonWsBefore };
}

/** Where a carried mark's START lands in `fragment` — see {@link $resolveMarkEnd}. A start on a
 * preserved run the capture saw finds that run in `fragment` through `pairing`. */
function $resolveMarkStart(
  start: MarkStart,
  fragment: FragmentAccumulator,
  pairing: RunPairing,
): ResolvedMarkEnd | undefined {
  if (start.kind === "byte") return $resolveMarkEnd(start.anchor, fragment, pairing, true);
  const settledRun = pairing.sentinelMap[start.run]?.find((member) => member !== undefined);
  const preservedKey = settledRun && fragment.sentinels[settledRun.sentinelIndex]?.[0]?.getKey();
  if (!preservedKey) return undefined;
  const settledAnchor = anchorAcrossLiteralsSnapped(pairing.alignment, start.anchor, "toSettled");
  const point = $resolveFragmentByteAnchor(fragment, settledAnchor, { addressDisplayBytes: true });
  return point && { point, at: settledAnchor.nonWsBefore, preservedKey };
}

/**
 * `point` as a boundary a selection can hold. A fragment span can belong to a leaf that is neither
 * text nor an element — a collapsed note's caller decorator, which spells the caller's bytes —
 * and a text point on such a leaf is refused by Lexical, so it stands as the boundary in front of
 * the leaf (offset 0) or past it. The wrap then holds the annotation on the whole decorator.
 *
 * Read-only: resolves the point's node key, so call inside `editor.update()` or an editor-state
 * read.
 */
function $selectablePoint(point: FragmentPoint): FragmentPoint | undefined {
  if (point.type !== "text") return point;
  const node = $getNodeByKey(point.key);
  if ($isTextNode(node)) return point;
  const parent = node?.getParent();
  if (!node || !parent) return undefined;
  const index = node.getIndexWithinParent() + (point.offset > 0 ? 1 : 0);
  return { key: parent.getKey(), offset: index, type: "element" };
}

/**
 * Whether two selectable points are the same boundary between nodes. A point at either edge of a
 * text node is also the element boundary on that side of it, and the two ends of a carried mark
 * can resolve to the two spellings of one boundary: a mark over nothing but a note that ends a
 * char span starts on `\w*` (a byte its start may name) and ends at the boundary in front of it
 * (an end stays right after a preserved node).
 *
 * Read-only: resolves the points' node keys, so call inside `editor.update()` or an editor-state
 * read.
 */
function $isSameBoundary(a: FragmentPoint, b: FragmentPoint): boolean {
  const asElement = (point: FragmentPoint): FragmentPoint => {
    if (point.type !== "text") return point;
    const node = $getNodeByKey(point.key);
    const parent = node?.getParent();
    if (!$isTextNode(node) || !parent) return point;
    if (point.offset === 0)
      return { key: parent.getKey(), offset: node.getIndexWithinParent(), type: "element" };
    if (point.offset === node.getTextContentSize())
      return { key: parent.getKey(), offset: node.getIndexWithinParent() + 1, type: "element" };
    return point;
  };
  const left = asElement(a);
  const right = asElement(b);
  return left.key === right.key && left.offset === right.offset && left.type === right.type;
}

/**
 * Re-wrap the annotations {@link $captureMarkByteRanges} lifted out, over whatever the rebuilt
 * nodes now spell at the same byte positions. `$freshFragment` re-derives the spliced tree's
 * spans; it is called again for every wrap because wrapping SPLITS the text nodes it covers, so
 * the span map one wrap resolved against no longer describes the tree the next one resolves in.
 *
 * The captured bytes and the rebuilt ones are lined up by `pairRuns` first, which is what carries a
 * mark across a literal the settle turned into a preserved node (a typed `\f + \ft note\f*` that
 * became a note): the rebuilt fragment spells that node as one placeholder byte where the captured
 * one spelled every byte of the literal. A mark past the literal is restated across it, and a mark
 * inside it lands on the same bytes of the node it became — both ends inside the same node, or the
 * mark is refused, since wrapping from inside a node to outside it would tear the node apart.
 *
 * The mark node is re-created rather than moved, which is what re-associates the AnnotationPlugin's
 * `type:id` → node-key map: its mutation listener sees the old key destroyed and the new one
 * created, and rebuilds the entry from the new node's own `typedIDs`. The host's callbacks ride
 * along per `type:id` through `$wrapSelectionInTypedMarkNode`, so they survive the new node key,
 * and no removal callback fires for the old node — a spliced-away subtree is garbage-collected
 * rather than `remove()`d, and `TypedMarkNode.remove` is the only source of a "destroyed"
 * notification.
 *
 * An end inside a marker glyph or an attribute run is carried like any other byte: the wrap
 * holds the annotation on such a node (`displayAnnotationsState`) and never moves or splits it,
 * so a construct cannot be torn apart by a carried end. The rule is by bytes: an annotation over
 * bytes the settle keeps or re-spells is carried to their settled counterpart; one over bytes it
 * discards is dropped, never moved.
 *
 * An anchor that no longer resolves is skipped, in the rebuild's own preserve-or-refuse spirit: a
 * dropped annotation is recoverable by the host re-applying it, one re-wrapped over the wrong
 * bytes is not. So is every wrap when `$freshFragment` cannot describe the rebuilt nodes at all,
 * and a mark whose resolved range names no bytes it covered:
 *
 * - two ends that land at the same byte count, where the mark's own ends did not — a mark over
 *   nothing but bytes the settle re-spelled (a typed `lemma="` that settles away). Comparing the
 *   points is not enough: the start is resolved with byte addressing and the end with caret
 *   addressing, so a count at a boundary between two text spans resolves to the next span's start
 *   and to the previous span's end, and the wrap would take in that whole previous span;
 * - two ends at the same point, which the wrap would turn into a mark over the bytes in front of
 *   it (below).
 *
 * Mutating: call inside `editor.update()`, after the splice.
 */
function $restoreMarkByteRanges(
  { ranges, live }: CapturedMarks,
  $freshFragment: () => FragmentAccumulator | undefined,
): void {
  if (ranges.length === 0 || !live) return;
  // Carrying a mark must leave the document selection exactly as it found it — the caller owns the
  // caret policy and applies it right after ($restoreSelectionAtOffset, which deliberately does
  // NOTHING when the caret was parked outside the scope being rebuilt, and so cannot undo anything
  // done here). `$wrapSelectionInTypedMarkNode` collapses the selection onto the mark it built for
  // the comment type, and a split text node moves any point that sat in it, so snapshot the
  // selection and put it back. A null snapshot is restored as null: a settle after blur must not
  // resurrect a selection.
  const selectionBefore = $getSelection()?.clone() ?? null;
  for (const range of ranges) {
    for (const annotation of range.annotations) {
      const fragment = $freshFragment();
      if (!fragment) continue;
      const pairing = pairRuns(live, $settledRunSide(fragment));
      // A mark's START names the first BYTE it covers, so it belongs at the front edge of the span
      // holding that byte — caret addressing (`addressDisplayBytes: false`) would instead park it
      // at the END of the preceding span, a caret's own preference, and the wrap would swallow
      // whatever sits there: a paragraph's glyph separator, or a char span's opening glyph. The
      // END is a boundary AFTER the last byte, which is exactly a caret position. A start on a
      // preserved node lands past that node either way, and the run is pulled back in below.
      const resolvedStart = $resolveMarkStart(range.start, fragment, pairing);
      const resolvedEnd = $resolveMarkEnd(range.end, fragment, pairing, false);
      if (!resolvedStart || !resolvedEnd) continue;
      if (resolvedStart.literalRun !== resolvedEnd.literalRun) continue;
      const startAnchor = range.start.anchor;
      if (
        resolvedStart.at === resolvedEnd.at &&
        startAnchor.nonWsBefore !== range.end.nonWsBefore &&
        !resolvedStart.preservedKey
      )
        continue;
      const { preservedKey } = resolvedStart;
      const start = $selectablePoint(resolvedStart.point);
      const end = $selectablePoint(resolvedEnd.point);
      if (!start || !end) continue;
      // A collapsed range covers no bytes, and the wrap holds nothing for one. The one collapsed
      // range that still names something is a mark over nothing but a preserved run, which is
      // pulled back in here, however its two ends happen to spell the boundary past it.
      if ($isSameBoundary(start, end)) {
        if (preservedKey) $wrapPreservedRun(preservedKey, annotation);
        continue;
      }
      const selection = $createRangeSelection();
      selection.anchor.set(start.key, start.offset, start.type);
      selection.focus.set(end.key, end.offset, end.type);
      $wrapSelectionInTypedMarkNode(
        selection,
        annotation.type,
        annotation.id,
        annotation.onClick,
        annotation.onRemove,
        annotation.onMouseEnter,
        annotation.onMouseLeave,
      );
      if (preservedKey) $extendMarkOverPreservedRun(preservedKey, annotation.type, annotation.id);
    }
  }
  $setSelection(selectionBefore);
}

/**
 * `fragment` with the byte range `[start, end)` removed: the text cut, and every span's bounds
 * restated in the shortened text's coordinates.
 *
 * A span the cut falls INSIDE keeps its start (so its head still maps offset-for-offset onto its
 * node) and loses the cut's length from its end; its tail no longer maps offset-for-offset, which a
 * caller that needs node offsets has to restate itself. A span entirely past the cut shifts back
 * wholesale. Spans the cut swallows entirely collapse to zero length rather than disappearing, so
 * a key stays findable.
 *
 * The `sentinels` run list passes through BY REFERENCE, so a run keeps its index no matter how many
 * cuts a fragment goes through — which is what lets a run be paired with its settled counterpart
 * positionally. The SPANS are a different matter: a cut whose range covers a sentinel span empties
 * that span, which is how a preserved node the settled side carries nothing of gets its
 * placeholder byte taken out of the text.
 */
export function cutFragment(
  fragment: FragmentAccumulator,
  start: number,
  end: number,
): FragmentAccumulator {
  if (end <= start) return fragment;
  const removed = end - start;
  const mapPosition = (position: number): number => {
    if (position <= start) return position;
    return position >= end ? position - removed : start;
  };
  return {
    text: fragment.text.slice(0, start) + fragment.text.slice(end),
    spans: fragment.spans.map((span) => ({
      ...span,
      start: mapPosition(span.start),
      end: mapPosition(span.end),
    })),
    sentinels: fragment.sentinels,
  };
}

/**
 * `fragment` with the placeholder byte of every run the settled side carries nothing of removed —
 * an emptied optbreak husk the settle splices out. `carried` lists, per run of
 * `fragment.sentinels`, the members the settled side carries.
 *
 * A dropped run still spells a U+FFFC in the live fragment's text, and the byte anchor the two
 * sides are otherwise paired through counts a placeholder as an ordinary document byte — it is
 * deliberately NOT whitespace ({@link $resolveFragmentByteAnchor}). Left in, every live position
 * past it answers a settled position one byte away, silently. Cut, the two fragments spell the
 * same document bytes again, which is the property the anchor relies on.
 *
 * The run's own span stays in the list, emptied, so the dropped node is still findable by key and
 * a position INSIDE it still resolves to the run it belongs to — which reports it at the boundary
 * where the run stood, the settled document having no node for it.
 */
export function withoutDroppedSentinels(
  fragment: FragmentAccumulator,
  carried: readonly (readonly LexicalNode[])[],
): FragmentAccumulator {
  const droppedKeys = fragment.sentinels
    .filter((run, index) => run.length > 0 && (carried[index]?.length ?? 0) === 0)
    .map((run) => run[0].getKey());
  // Later runs first: a cut only restates the positions after it, so each span's start is still
  // the one this loop looked it up by.
  return droppedKeys.reverse().reduce((cut, key) => {
    const span = cut.spans.find((candidate) => candidate.isSentinel && candidate.key === key);
    return span ? cutFragment(cut, span.start, span.end) : cut;
  }, fragment);
}

/**
 * A node's serialized form including its whole subtree — the recursive walker `exportNodeToJSON`
 * is internally, for the places a SUBTREE rather than a whole editor state has to be serialized.
 */
export function $exportSubtree(node: LexicalNode): SerializedLexicalNode {
  const json: SerializedLexicalNode & { children?: SerializedLexicalNode[] } = node.exportJSON();
  if ($isElementNode(node) && Array.isArray(json.children))
    node.getChildren().forEach((child) => json.children?.push($exportSubtree(child)));
  return json;
}

/**
 * The bytes the nodes a chapter scope settled into spell, read back the way the rest of the settle
 * reads them: through the chapter's own builder when they are the chapter and the `\\ca`/`\\cp` nodes
 * beside it, and as any settled root content otherwise — text typed ahead of the marker settles
 * as a line of its own, a `\\ca` that no longer folds as a paragraph of its own, and bytes that stop
 * reading as a chapter marker (`\\ 2`, `\\sc 2`) as no chapter at all.
 *
 * Read-only: call inside `editor.update()` or an editor-state read.
 */
export function $settledChapterScopeFragment(
  nodes: readonly LexicalNode[],
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): FragmentAccumulator | undefined {
  const chapter = nodes.find($isChapterNode);
  if (!chapter) return $buildSettledRootFragment(nodes, getMarkerFn, viewOptions);
  const region = new Set(
    [chapter, ...$chapterAdjacentAttributeNodes(chapter)].map((node) => node.getKey()),
  );
  return nodes.every((node) => region.has(node.getKey()))
    ? $buildChapterFragment(chapter, getMarkerFn, viewOptions)
    : $buildSettledRootFragment(nodes, getMarkerFn, viewOptions);
}

/** What a read-only settle's rebuilt nodes stand in for: whole paragraphs, a chapter and its
 * adjacent region, a note's content, or the `\id` line (the book holding the line's content, then
 * the blocks after it) — which decides how their bytes are read back. */
export type SettledScopeKind = "paras" | "chapter" | "noteContent" | "bookLine";

/**
 * `rebuilt` — the serialized nodes a read-only settle turns `scope` into — with the annotation
 * marks `scope` holds wrapped back over the same bytes, so a settled read taken while an edit is
 * pending carries exactly the marks the real settle will leave.
 *
 * It runs the mutating rebuilds' own capture ({@link $captureMarkByteRanges}) and restore
 * ({@link $restoreMarkByteRanges}), the restore over `rebuilt` materialized in a scratch editor,
 * so the two settles agree by construction rather than by a second implementation. The scratch
 * editor un-nests overlapping marks the way the live editor's `AnnotationPlugin` does. A mark
 * that begins on a preserved node names that node's run by its index in `fragment`, and the
 * restore finds the scratch copy of the same run by pairing the two run lists, for which
 * `carriedRuns` lists the live members `rebuilt` carries, per run of `fragment.sentinels`.
 *
 * `fragment` is the one the rebuild tokenized — with any transient bytes already cut out — so the
 * marks anchor in the coordinates `rebuilt` was built in. `rebuilt` comes back untouched, and no
 * scratch editor is made, when the scope holds no mark.
 *
 * Read-only on the live tree: call inside a read of it.
 */
export function $carryMarksIntoSerialized(
  scope: LexicalNode[],
  fragment: FragmentAccumulator,
  carriedRuns: readonly (readonly LexicalNode[])[],
  rebuilt: SerializedLexicalNode[],
  kind: SettledScopeKind,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): SerializedLexicalNode[] {
  // The settle splices a husk out of `rebuilt` without a trace, so its placeholder comes out of
  // the captured bytes too — left in, every mark past it would land one byte early.
  const captured = $captureMarkByteRanges(
    scope,
    withoutDroppedSentinels(fragment, carriedRuns),
    carriedRuns,
  );
  if (captured.ranges.length === 0) return rebuilt;
  // The scratch marks carry type and id only, since only `typedIDs` reach the serialized output. A
  // host callback on one would fire when the resolver below merges an emptied mark away, telling
  // the host a still-live annotation was destroyed, and the callback registry would keep an entry
  // for a node nobody ever sees.
  const idsOnly: CapturedMarks = {
    ...captured,
    ranges: captured.ranges.map((range) => ({
      ...range,
      annotations: range.annotations.map(({ type, id }) => ({ type, id })),
    })),
  };
  const scratch = createEditor({
    nodes: [TypedMarkNode, ...usjReactNodes],
    onError: (error) => {
      throw error;
    },
  });
  registerNestedElementResolver<TypedMarkNode>(
    scratch,
    TypedMarkNode,
    (from) => $createTypedMarkNode(from.getTypedIDs()),
    (from, to) =>
      Object.entries(from.getTypedIDs()).forEach(([type, ids]) =>
        ids.forEach((id) => to.addID(type, id)),
      ),
  );
  let holderKey: NodeKey | undefined;
  scratch.update(
    () => {
      const root = $getRoot();
      // Note content is inline, and the root holds only blocks.
      const holder = kind === "noteContent" ? $createImpliedParaNode() : root;
      if (holder !== root) root.append(holder);
      holderKey = holder.getKey();
      rebuilt.forEach((child) => holder.append($parseSerializedNode(child)));
      const $fresh = () => {
        const nodes = holder.getChildren();
        if (kind === "paras") return $spansForNodes(nodes, getMarkerFn, viewOptions);
        if (kind === "chapter")
          return $settledChapterScopeFragment(nodes, getMarkerFn, viewOptions);
        if (kind === "bookLine") {
          const [book, ...followingBlocks] = nodes;
          return $isBookNode(book)
            ? $bookScopeSpans(book, followingBlocks, getMarkerFn, viewOptions)
            : undefined;
        }
        const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
        $appendNodesFragment(nodes, out, getMarkerFn, viewOptions);
        return out;
      };
      $restoreMarkByteRanges(idsOnly, $fresh);
    },
    { discrete: true },
  );
  return scratch.getEditorState().read(() => {
    const holder = holderKey === undefined ? undefined : $getNodeByKey(holderKey);
    return $isElementNode(holder) ? holder.getChildren().map($exportSubtree) : rebuilt;
  });
}

/** Collapse the selection onto `point`; `false` when its node is no longer in the tree. */
function $selectPoint(point: FragmentPoint): boolean {
  const node = $getNodeByKey(point.key);
  if (!node?.isAttached()) return false;
  if (point.type === "text") {
    if (!$isTextNode(node)) return false;
    node.select(point.offset, point.offset);
    return true;
  }
  if (!$isElementNode(node)) return false;
  const selection = $createRangeSelection();
  selection.anchor.set(point.key, point.offset, "element");
  selection.focus.set(point.key, point.offset, "element");
  $setSelection(selection);
  return true;
}

/** Place the collapsed caret at the position `anchor` describes (see `$caretSpanByteAnchor`)
 * within the freshly-built spans, falling back to the first element. */
function $selectAtFragmentByteAnchor(
  fragment: { text: string; spans: FragmentSpan[] },
  anchor: CaretByteAnchor,
  newNodes: LexicalNode[],
): void {
  const point = $resolveFragmentByteAnchor(fragment, anchor);
  if (point?.type === "text") {
    if ($selectPoint(point)) return;
  } else if (point) {
    // An element boundary past a construct the caret cannot enter: select off the node it sits
    // after, which resolves to whatever follows (the next text run, the next block's start, or
    // the append position at the end of the parent).
    const parent = $getNodeByKey(point.key);
    const previous = $isElementNode(parent) ? parent.getChildAtIndex(point.offset - 1) : undefined;
    if (previous) {
      previous.selectNext(0, 0);
      return;
    }
  }
  newNodes.find($isElementNode)?.selectStart();
}

/**
 * The collapsed caret a settle lifts out of its scope before the splice, as plain data plus the
 * scope's live bytes, which is what lines it up with the rebuilt bytes afterwards (`pairRuns`)
 * once the nodes it was read from are gone.
 */
interface CapturedCaret {
  /** The caret as a byte anchor over the scope's live fragment, an element boundary spelled from
   * the child bytes beside it ({@link $anchorForPoint}); `undefined` when nothing of the fragment
   * spells it — a point inside a preserved run. */
  anchor: CaretByteAnchor | undefined;
  /** A caret inside a preserved run the settle carries across whole: the run member holding it,
   * and the child path from that member down to the caret's own node. */
  inRun:
    | (SettledRunMember & { path: number[]; offset: number; type: "text" | "element" })
    | undefined;
  live: LiveRunSide;
}

/**
 * The collapsed caret at `point` over `fragment`, the scope's live bytes. Every preserved run of
 * the fragment is one the settle carries across whole.
 *
 * Read-only: call inside `editor.update()`, before the splice.
 */
function $captureCaret(fragment: FragmentAccumulator, point: PointType): CapturedCaret {
  const node = point.getNode();
  const preserved = $preservedRunMember(fragment, node);
  const path = preserved && $childPath(preserved.member, node);
  return {
    // An element point (a click past a paragraph's trailing note) has no span of its own, so it
    // is spelled from the child bytes beside it, the same way a settled position spells one.
    anchor:
      point.type === "element"
        ? $anchorForPoint(fragment, node, point.offset)?.anchor
        : $caretSpanByteAnchor(fragment, point.key, point.offset),
    inRun:
      preserved && path
        ? {
            sentinelIndex: preserved.sentinelIndex,
            memberIndex: preserved.memberIndex,
            path,
            offset: point.offset,
            type: point.type,
          }
        : undefined,
    live: $liveRunSide(fragment, fragment.sentinels),
  };
}

/**
 * Put a caret {@link $captureCaret} lifted out back over `fragment`, the rebuilt scope's bytes,
 * through the byte alignment `pairRuns` lines the two sides up with:
 *
 * - inside a preserved run the settle carried across, on the same child of the same run member;
 * - inside a typed literal the settle turned into a preserved node, on the same byte of that
 *   node's own spelling — or, for a byte the settle spelled differently, where its differing
 *   bytes start;
 * - anywhere else, on the same byte, snapping LEFT to where the rebuilt side's differing bytes
 *   start when the byte it sits in front of has no rebuilt counterpart (a re-spelled attribute's
 *   name).
 *
 * Falls back to the first element's start when none of those resolve.
 *
 * Mutating: call inside `editor.update()`, after the splice and the mark carry.
 */
function $restoreCaret(
  fragment: FragmentAccumulator,
  caret: CapturedCaret | undefined,
  newNodes: LexicalNode[],
): void {
  const pairing = caret && pairRuns(caret.live, $settledRunSide(fragment));
  if (caret?.inRun && pairing) {
    const { sentinelIndex, memberIndex, path, offset, type } = caret.inRun;
    const settled = pairing.sentinelMap[sentinelIndex]?.[memberIndex];
    let node: LexicalNode | undefined =
      settled && fragment.sentinels[settled.sentinelIndex]?.[settled.memberIndex];
    for (const index of path)
      node = $isElementNode(node) ? (node.getChildAtIndex(index) ?? undefined) : undefined;
    if (node && $selectPoint({ key: node.getKey(), offset, type })) return;
  }
  if (!caret?.anchor || !pairing) {
    newNodes.find($isElementNode)?.selectStart();
    return;
  }
  const { anchor } = caret;
  const inside = literalContaining(pairing.settledOnlyRuns, anchor);
  if (inside) {
    const within = inside.within ?? {
      nonWsBefore: mapCountSnapped(inside.run.inner, inside.count, "live"),
      wsRun: anchor.wsRun,
    };
    const point = $resolveFragmentByteAnchor(inside.run.spelling, within);
    if (point && $selectPoint(point)) return;
  }
  $selectAtFragmentByteAnchor(
    fragment,
    anchorAcrossLiteralsSnapped(pairing.alignment, anchor, "toSettled"),
    newNodes,
  );
}

function $restoreSelectionAtOffset(
  newNodes: LexicalNode[],
  caret: CapturedCaret | undefined,
  anchorInParas: boolean,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): void {
  // The caret was somewhere else entirely (the primary completion flow: the user
  // typed a mid-edit marker, then clicked/arrowed into another paragraph, which is
  // what triggered this rebuild). The rebuilt paragraphs are not where the caret
  // lives, so leave the selection strictly untouched rather than yanking it back in.
  if (!anchorInParas) return;
  $restoreCaret($spansForNodes(newNodes, getMarkerFn, viewOptions), caret, newNodes);
}

/**
 * Restore the caret inside a rebuilt CONTENT REGION — the children of one preserved shell, which is
 * a note's expanded content or the `\id` line's content past its prefix. Unlike
 * `$restoreSelectionAtOffset`, those nodes form one contiguous region, so spans are computed with
 * `$appendNodesFragment` (no inter-node separators) to match the offset captured over
 * `$buildNoteFragment`/`$buildBookFragment`'s text.
 *
 * `liveContentNodes` must be re-fetched from the shell's OWN children AFTER `$replaceSentinels` has
 * run — never the flat `newNodes` array the caller parsed the fresh tokenizer output into. When a
 * preserved run (e.g. a co-resident note) sits between two pieces of a top-level TEXT node,
 * `$replaceSentinels` calls `splitText`, which truncates that array slot's node OBJECT IN PLACE and
 * creates the split-off tail as a NEW SIBLING, then `insertAfter`s the preserved run between them —
 * three tree children where the array still lists one. Walking the stale array under-counts bytes
 * (a caret meant to land after the split loses the selection entirely, since Lexical detects it was
 * never re-anchored) or over/under-shoots one meant to land past an EARLIER split (the caret lands
 * inside content that hasn't been typed yet). `$buildBookFragment`/`$buildNoteFragment`, called
 * again post-splice, hand back exactly this shell's current children with no more re-derivation
 * needed than the callers already trust for the first, pre-splice call.
 */
function $restoreSelectionInContentRegion(
  liveContentNodes: LexicalNode[],
  caret: CapturedCaret | undefined,
  anchorInShell: boolean,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): void {
  if (!anchorInShell) return;
  if (!caret?.anchor && !caret?.inRun) {
    $selectBeforeFirstUnaddressableRegionChild(liveContentNodes, getMarkerFn);
    return;
  }
  const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  $appendNodesFragment(liveContentNodes, out, getMarkerFn, viewOptions);
  $restoreCaret(out, caret, liveContentNodes);
}

/**
 * The no-byte-anchor fallback's own target: the first ELEMENT node among `liveContentNodes`,
 * entered at its own start — UNLESS that node is one `$appendNodesFragment` renders as an opaque
 * sentinel span (a collapsed note, an unknown node, an unrecoverable char span, a non-re-
 * tokenizable milestone, a sentinel verse — {@link $isRebuildSentinel}, the shared authority for
 * exactly this question). Entering a sentinel selects INSIDE content the fragment never gave the
 * caret a byte position in — invisible on screen, and (for a note) editing the note body instead of
 * the region typing was meant to land in. The caret belongs immediately BEFORE it instead: its own
 * parent, at its own index, the same boundary a caret genuinely resting there would occupy.
 */
function $selectBeforeFirstUnaddressableRegionChild(
  liveContentNodes: LexicalNode[],
  getMarkerFn: MarkerLookup,
): void {
  const target = liveContentNodes.find($isElementNode);
  if (target && $isRebuildSentinel(target, getMarkerFn)) {
    const parent = target.getParent();
    if (parent) {
      const index = target.getIndexWithinParent();
      parent.select(index, index);
      return;
    }
  }
  target?.selectStart();
}

/**
 * The mutating Tier-2 settle for a paragraph scope: serializes the displayed bytes of `paras`
 * (one settle scope — usually a single paragraph) into fragment text, re-tokenizes that text
 * through the USFM fragment tokenizer, and splices the resulting nodes in place — the settle IS
 * re-tokenization, never a hand-patched tree. Restores the caret afterwards by byte anchor, so a
 * settle under a live caret leaves it at the same displayed byte.
 *
 * Returns `true` when the document changed. `false` is a REFUSAL and a true no-op: serialized
 * signatures are compared BEFORE any mutation, so a scope already at its tokenized fixed point
 * changes nothing — which is also the acceptance for settled output (re-load it and every scope
 * must refuse; see settledGetUsj.test-helpers.tsx's `expectTier2FixedPoint`).
 *
 * Invariant: the read-only settle mirror (`$settledUsj`, virtualSettle.utils.ts) recomputes this
 * function's outcome over serialized JSON without mutating the editor, and the two must agree on
 * the resulting USJ byte-for-byte (pinned by settledGetUsj.test.tsx and
 * settleDifferential.test.tsx).
 *
 * Mutating: call inside `editor.update()` (dispatched from the Tier-2 trigger transform, the
 * caret-departure and commit paths in MarkerEditPlugin.tsx, and `$requestTier2ForNode`).
 */
export function $rebuildParas(paras: ParaNode[], context: Tier2Context): boolean {
  if (paras.length === 0) return false;
  const { viewOptions, getMarker: getMarkerFn, logger } = context;

  const combined = $buildParaScopeFragment(paras, getMarkerFn, viewOptions);
  if (!combined) {
    logger?.debug("[MarkerEdit] Tier 2 skipped: paragraph excluded by guard rails");
    return false;
  }

  // Capture the caret as a fragment byte anchor before mutating anything, and note whether
  // the anchor was actually inside the paragraphs being rebuilt (vs. parked elsewhere).
  let caret: CapturedCaret | undefined;
  let anchorInParas = false;
  const selection = $getSelection();
  if ($isRangeSelection(selection)) {
    for (let node: LexicalNode | null = selection.anchor.getNode(); node; node = node.getParent())
      if (paras.some((para) => para.is(node))) {
        anchorInParas = true;
        break;
      }
    if (selection.isCollapsed()) caret = $captureCaret(combined, selection.anchor);
  }
  // Annotation marks anchor the same way, two points each — they live on nodes the splice
  // destroys and are transparent to re-tokenization, so nothing else would bring them back.
  const markRanges = $captureMarkByteRanges(paras, combined, undefined, $getEditor());

  const content: MarkerContent[] = tokenizeFragment(combined, {
    getMarker: getMarkerFn,
    opensNamelessParagraph: $opensNamelessParagraph(paras),
  });
  if (content.length === 0) {
    logger?.debug("[MarkerEdit] Tier 2 skipped: tokenizer produced no content");
    return false;
  }
  // Symmetry bail-out: every preserved node run must have exactly one placeholder
  // in the output, or the rebuild aborts with the paragraph untouched. A tokenizer
  // bug must fail as "nothing happened", never as a silently dropped node.
  if (countSentinels(content) !== combined.sentinels.length) {
    logger?.warn("[MarkerEdit] Tier 2 aborted: sentinel/preserved-node count mismatch");
    return false;
  }

  const serialized = usjEditorAdaptor.serializeEditorState(
    { type: USJ_TYPE, version: USJ_VERSION, content },
    viewOptions,
  );

  // Fixed-point refusal (preserve-or-refuse). If the freshly-tokenized output is
  // structurally identical to the paragraphs it was derived from, this rebuild is a
  // no-op: splicing it in would reproduce the same unresolved literal text (a bare
  // `\` or an unterminated milestone run — the tokenizer's remaining
  // literal-degradation cases; a stray `\*`, most unknown markers, and non-attribute
  // content before a milestone's `\*` now resolve structurally instead, see
  // usfmFragmentToUsjContent's doc comment), re-arm the TextNode catch-all
  // transform, and — via the caret-departure/Enter completion path — drive an endless
  // resolve→rebuild→resolve cascade that hangs the main thread. Compare BEFORE any
  // mutation and bail. The signature normalizes preserved nodes and their U+FFFC
  // placeholders to the same token, so this is a structure+text comparison, not node
  // identity; a rebuild that actually restructures anything (literal `\nd x\nd*` → a
  // CharNode span, or an unknown opener splitting off its own paragraph) has a
  // different signature and is never mistaken for a no-op.
  //
  // Compared on the SERIALIZED rebuild (`serializedSignatureOf`, the same JSON-side computation
  // the read-only settle makes) rather than on parsed nodes, so a refusal materializes NO live
  // nodes at all. Parse orphans count as dirty leaves: they turned a refused (no-op) settle into
  // a real commit — reconciliation, a DOM selection round trip, and a follow-on
  // caret-normalization commit that could displace the caret out from under an active gesture
  // (observed: a caret parked in span content yanked to the paragraph's marker glyph, so the
  // next keystrokes landed outside the span). A refused re-settle must be a TRUE no-op.
  if (
    serializedSignatureOf(serialized.root.children, getMarkerFn) ===
    $signatureOf(paras, getMarkerFn)
  ) {
    logger?.debug("[MarkerEdit] Tier 2 skipped: rebuild is a no-op (fixed point)");
    return false;
  }

  const newNodes = serialized.root.children.map((child) => $parseSerializedNode(child));

  // Second sentinel check, now on the SERIALIZED->PARSED tree: the tokenizer-level count above
  // guards the MarkerContent, but the serialize/parse round trip is a separate place a U+FFFC
  // placeholder can vanish. If the parsed tree has fewer (or more) than the preserved-run count,
  // $replaceSentinels would silently drop or mis-pair a preserved node. Abort untouched instead.
  if (countSentinelNodes(newNodes) !== combined.sentinels.length) {
    logger?.warn("[MarkerEdit] Tier 2 aborted: serialized sentinel/preserved-node count mismatch");
    return false;
  }

  // Snapshot the old paragraphs' verse number/sid pairs, in document order, as plain data —
  // BEFORE the splice below moves or destroys the old paragraphs (a removed node's fields are
  // not safe to read afterward). Sid carry-over (below) pairs this against the freshly
  // re-tokenized tree's verses once the splice has settled.
  const oldVerseSids = $collectVerseNodes(paras).map((verse) => ({
    number: verse.getNumber(),
    sid: verse.getSid(),
  }));

  const firstPara = paras[0];
  newNodes.forEach((node) => firstPara.insertBefore(node));
  // Move originals BEFORE removing the old paragraphs (removal destroys leftovers).
  $replaceSentinels(newNodes, combined.sentinels);
  paras.forEach((para) => para.remove());
  // Sid carry-over: a freshly re-tokenized verse never has a sid — the tokenizer cannot derive
  // one from visible bytes — so pair the old and new
  // verses positionally in document order and copy the old sid onto its partner wherever the
  // verse NUMBER is unchanged. A renumbered verse (the pair's numbers disagree) gets no sid
  // synthesized; a sentinel verse (unknownAttributes) is the SAME instance on both sides of the
  // pairing, so this is a harmless no-op for it. Runs strictly AFTER the fixed-point check above,
  // which deliberately never looks at sid (see the `$appendSignature` verse branch) — sid is
  // reconciled here, once, only when a rebuild is already happening for some other reason.
  const newVerses = $collectVerseNodes(newNodes);
  for (let i = 0; i < oldVerseSids.length && i < newVerses.length; i++) {
    if (newVerses[i].getNumber() === oldVerseSids[i].number)
      newVerses[i].setSid(oldVerseSids[i].sid);
  }
  // Before the caret restore, so the caret resolves against the final tree: re-wrapping splits
  // the text nodes it covers.
  $restoreMarkByteRanges(markRanges, () => $spansForNodes(newNodes, getMarkerFn, viewOptions));
  $restoreSelectionAtOffset(newNodes, caret, anchorInParas, getMarkerFn, viewOptions);
  return true;
}

/**
 * The guard checks and child slicing {@link $buildNoteFragment} builds its fragment from — the
 * note's CONTENT children, everything strictly between its opening MarkerNode(s) + caller prefix
 * and its trailing closing MarkerNode(s) — WITHOUT building the fragment text/spans. Preserve-or-
 * refuse (returns `undefined`) when the note is collapsed, has an unrecoverable marker, or an
 * unexpected caller/prefix shape: a note the engine cannot cleanly re-derive is never rebuilt.
 *
 * Factored out so a caller that only needs the CURRENT content nodes — post-splice, to restore the
 * caret — is not also paying for `$appendNodesFragment`'s walk over them a second time.
 */
function $noteContentNodes(note: NoteNode): LexicalNode[] | undefined {
  // Only inline-expanded notes are re-tokenizable: a collapsed note's content is not
  // inline-editable and its display layout (interspersed spacing) is not text-recoverable.
  if (note.getIsCollapsed() !== false) return undefined;
  // The note node itself (marker, caller, and any unknown attributes such as the
  // unclosed-note `closed="false"`) is PRESERVED across the rebuild, so its own
  // attributes never disqualify a content re-tokenization; only a marker the engine
  // cannot recognize is refused as a sanity guard.
  if (!NoteNode.isValidMarker(note.getMarker())) return undefined;

  const children = note.getChildren();
  // Skip the leading opening-marker(s) prefix.
  let start = 0;
  while (start < children.length) {
    const node = children[start];
    if (!$isMarkerNode(node) || node.getMarkerSyntax() !== "opening") break;
    start++;
  }
  // Skip the caller node (an ImmutableNoteCallerNode, or the expanded editable caller
  // TextNode); anything else in this slot is an unexpected shape, so refuse.
  const callerNode = children[start];
  if (!callerNode) return undefined;
  const isCaller =
    $isImmutableNoteCallerNode(callerNode) ||
    ($isTextNode(callerNode) &&
      callerNode.getTextContent() === getEditableCallerText(note.getCaller()));
  if (!isCaller) return undefined;
  start++;
  // Skip the trailing closing-marker(s).
  let end = children.length;
  while (end > start) {
    const node = children[end - 1];
    if (!$isMarkerNode(node) || node.getMarkerSyntax() !== "closing") break;
    end--;
  }

  return children.slice(start, end);
}

/**
 * Build the re-tokenizable fragment for a note's CONTENT children. Preserve-or-refuse (returns
 * undefined) exactly as {@link $noteContentNodes} does — see it for the guard rails.
 *
 * Exported for the read-only settle (virtualSettle.utils.ts): note content is its own settle scope,
 * and the settled output a consumer reads must be built from the SAME fragment the mutating rebuild
 * below would build. Every other caller in this module still reaches it through
 * `$rebuildNoteContent`.
 */
export function $buildNoteFragment(
  note: NoteNode,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): { out: FragmentAccumulator; contentNodes: LexicalNode[] } | undefined {
  const contentNodes = $noteContentNodes(note);
  if (!contentNodes) return undefined;
  const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  $appendNodesFragment(contentNodes, out, getMarkerFn, viewOptions);
  return { out, contentNodes };
}

/**
 * The fragment over a run of sibling nodes, each walked as a paragraph's children are — for the
 * settled-position basis of a note a typed closer closes, whose bytes run on past the note into its
 * paragraph. Only pairs bytes for that basis; never tokenized.
 *
 * Read-only: walks the nodes, so call inside `editor.update()` or an editor-state read.
 */
export function $buildNodesFragment(
  nodes: LexicalNode[],
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): FragmentAccumulator {
  const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  $appendNodesFragment(nodes, out, getMarkerFn, viewOptions);
  return out;
}

/**
 * A foldable leading `\cat` span's category value, REMOVED from `content` — or `undefined` with
 * `content` untouched. Foldable mirrors ParatextData's note-category parse: explicitly closed
 * (no `closed` metadata and no other attributes riding the span), exactly one plain-text content
 * item, non-whitespace after the trim ParatextData applies, and no preserved-node placeholder
 * inside. Position zero of the note-content fragment IS "directly after the caller" — the only
 * place the fold ever happens.
 */
export function extractLeadingCategoryFold(content: MarkerContent[]): string | undefined {
  const first = content[0];
  if (typeof first !== "object" || first.type !== "char" || first.marker !== "cat")
    return undefined;
  const keys = Object.keys(first);
  if (!keys.every((key) => key === "type" || key === "marker" || key === "content"))
    return undefined;
  if (!first.content || first.content.length !== 1) return undefined;
  const text = first.content[0];
  if (typeof text !== "string" || text.includes(ATOMIC_SENTINEL)) return undefined;
  const trimmed = text.trim();
  if (trimmed === "") return undefined;
  content.shift();
  return trimmed;
}

/**
 * Note-scoped Tier 2 re-tokenization. Mirrors `$rebuildParas` but
 * operates on a single note's CONTENT children. The note node identity, its opening
 * marker(s), its caller, and its closing marker(s) are PRESERVED; only the content is
 * re-tokenized — with the note's `category` DERIVED from it each pass (the leading `\cat`
 * fold), so the displayed run bytes win exactly like every other settled byte. Preserve-or-
 * refuse: any guard-rail failure returns false with the note
 * untouched (never a partial mutation, never an infinite loop). A NoteNode inside a
 * PARAGRAPH rebuild stays an atomic sentinel; only this path descends into its content.
 *
 * Deliberately a parallel algorithm rather than a shared core with `$rebuildParas`: the two
 * differ in exactly the load-bearing parts — the rebuild scope (note content vs whole
 * paragraphs), what is preserved (the note shell vs nothing), the tokenizer options (note
 * context, expanded notes), and the splice shape (unwrap the tokenizer's default `\p` wrapper vs
 * replace paragraphs). Parameterizing those out would obscure both.
 */
export function $rebuildNoteContent(note: NoteNode, context: Tier2Context): boolean {
  const { viewOptions, getMarker: getMarkerFn, logger } = context;
  const built = $buildNoteFragment(note, getMarkerFn, viewOptions);
  if (!built) {
    logger?.debug("[MarkerEdit] Note Tier 2 skipped: note excluded by guard rails");
    return false;
  }
  const { out, contentNodes } = built;

  // Capture the caret as a fragment byte anchor before mutating, noting whether the anchor
  // was actually inside this note (vs. parked elsewhere) — mirror `$rebuildParas`.
  let caret: CapturedCaret | undefined;
  let anchorInNote = false;
  const selection = $getSelection();
  if ($isRangeSelection(selection)) {
    for (let node: LexicalNode | null = selection.anchor.getNode(); node; node = node.getParent())
      if (note.is(node)) {
        anchorInNote = true;
        break;
      }
    if (selection.isCollapsed()) caret = $captureCaret(out, selection.anchor);
  }
  // Annotations inside the note's content anchor the same way — mirror `$rebuildParas`. A
  // note's content is reachable by USJ location, so `setAnnotation` can put a mark in an
  // expanded note exactly as it can in a paragraph.
  const markRanges = $captureMarkByteRanges(contentNodes, out, undefined, $getEditor());

  const content: MarkerContent[] = tokenizeFragment(out, {
    getMarker: getMarkerFn,
    isNoteContext: true,
  });
  if (content.length === 0) {
    logger?.debug("[MarkerEdit] Note Tier 2 skipped: tokenizer produced no content");
    return false;
  }
  // Symmetry bail-out (see `$rebuildParas`): a preserved-run/placeholder mismatch aborts
  // the rebuild with the note untouched rather than silently dropping a node.
  if (countSentinels(content) !== out.sentinels.length) {
    logger?.warn("[MarkerEdit] Note Tier 2 aborted: sentinel/preserved-node count mismatch");
    return false;
  }

  // The tokenizer wraps a note-content fragment in its default `\p` — unwrap it here (the
  // USJ-side twin of the serialized-side unwrap this function used to do), refusing any other
  // top-level shape.
  const [tokenizedWrapper] = content;
  if (
    content.length !== 1 ||
    typeof tokenizedWrapper !== "object" ||
    tokenizedWrapper.type !== "para"
  ) {
    logger?.warn("[MarkerEdit] Note Tier 2 aborted: unexpected tokenized shape");
    return false;
  }
  const noteContent = tokenizedWrapper.content ?? [];

  // The category fold, mirrored from ParatextData's parse: a `\cat` span DIRECTLY after the
  // note's caller — which is position zero of this content fragment, since the fragment starts
  // right after the caller — folds onto the note as its `category` iff it is explicitly closed
  // with non-empty plain-text content. Anything else (markup inside, an empty span, an unclosed
  // span, a preserved-node placeholder, text before it) is NOT foldable and stays first-class
  // content, exactly as ParatextData keeps it. The note's category is then whatever folded — or
  // cleared when nothing did, so deleting the displayed run genuinely deletes the category
  // instead of the sync resurrecting it from stale state.
  const foldedCategory = extractLeadingCategoryFold(noteContent);

  // A closer the user typed into an unclosed note ends the note right there.
  const closedAt = splitUnclosedNoteAtOwnCloser(note, noteContent);
  if (closedAt)
    return $closeNoteAtOwnCloser(
      note,
      closedAt,
      foldedCategory,
      out.sentinels,
      context,
      anchorInNote,
    );

  // The fresh content children come from serializing the WHOLE note expanded and unwrapping its
  // shell; `$serializeExpandedNoteContent` (settleShared.utils.ts) states why, and is shared with
  // the read-only settle so the two can never unwrap the same shell differently. Parse the
  // returned children into live nodes here — that materialization is the one half a read-only
  // settle cannot share.
  const unwrapped = $serializeExpandedNoteContent(note, noteContent, foldedCategory, viewOptions);
  if (unwrapped.failure !== undefined) {
    if (unwrapped.failure === "empty")
      logger?.debug("[MarkerEdit] Note Tier 2 skipped: no content nodes after unwrap");
    else
      logger?.warn(
        unwrapped.failure === "caller"
          ? "[MarkerEdit] Note Tier 2 aborted: serialized note lacks the editable caller"
          : "[MarkerEdit] Note Tier 2 aborted: unexpected serialized shape",
      );
    return false;
  }
  // Second sentinel check, now on the SERIALIZED tree (the mirror of `$rebuildParas`' recount and
  // of the read-only settle's own): the tokenizer-level count above guards the MarkerContent, but
  // serialization is a separate place a U+FFFC placeholder can vanish. If the unwrapped content
  // has fewer (or more) than the preserved-run count, `$replaceSentinels` would silently drop or
  // mis-pair a preserved node. Abort untouched — before the category write below, which is also
  // derived from this rebuild's output — instead.
  if (countSerializedSentinels(unwrapped.children) !== out.sentinels.length) {
    logger?.warn(
      "[MarkerEdit] Note Tier 2 aborted: serialized sentinel/preserved-node count mismatch",
    );
    return false;
  }

  // The category write happens whether or not the content splice below is refused: an EDITED
  // `\cat` value serializes to the same canonical bytes the live tree already displays (the
  // user's edit IS those bytes), so the structural comparison legitimately reports a fixed point
  // — but the note's `category` state still lags the displayed value and must catch up here.
  // Idempotent (`setCategory` no-ops on equality), so an unchanged category adds nothing.
  const categoryChanged = note.getCategory() !== foldedCategory;
  if (categoryChanged) note.setCategory(foldedCategory);

  // Fixed-point refusal (preserve-or-refuse) on the CONTENT nodes only: if the freshly
  // tokenized content is structurally identical to what it was derived from, splicing it
  // would re-arm the trigger and loop. Compare BEFORE any mutation and bail — reporting the
  // category catch-up (a real mutation) when one happened. Compared on the SERIALIZED rebuild
  // (`serializedSignatureOf`), before any nodes are parsed, so a refusal materializes no live
  // nodes — see `$rebuildParas`' fixed-point comment for why orphan-free refusal is load-bearing.
  if (
    serializedSignatureOf(unwrapped.children, getMarkerFn) ===
    $signatureOf(contentNodes, getMarkerFn)
  ) {
    logger?.debug("[MarkerEdit] Note Tier 2 skipped: rebuild is a no-op (fixed point)");
    return categoryChanged;
  }

  const newNodes = unwrapped.children.map((child) => $parseSerializedNode(child));

  // Parse-leg recount: the serialized-level count above cleared serialization, but the parse into
  // live nodes is one more place a placeholder could in principle vanish. Abort the splice; the
  // category catch-up above already happened and is reported truthfully.
  if (countSentinelNodes(newNodes) !== out.sentinels.length) {
    logger?.warn("[MarkerEdit] Note Tier 2 aborted: parsed sentinel/preserved-node count mismatch");
    return categoryChanged;
  }

  // Splice: insert the new content before the first old content node (or before the
  // closing marker / at the note end when the note had no prior content), move preserved
  // sentinel runs into place, then remove the originals.
  const firstContent = contentNodes[0];
  if (firstContent) {
    newNodes.forEach((node) => firstContent.insertBefore(node));
  } else {
    const closing = note
      .getChildren()
      .find((child) => $isMarkerNode(child) && child.getMarkerSyntax() === "closing");
    newNodes.forEach((node) => (closing ? closing.insertBefore(node) : note.append(node)));
  }
  $replaceSentinels(newNodes, out.sentinels);
  // Unlike `$rebuildParas` (which removes container PARAGRAPHS the preserved nodes were
  // already moved out of), the old content list here contains the preserved sentinel nodes
  // THEMSELVES — `$replaceSentinels` just moved them into the rebuilt content, so removing
  // them here would silently delete them from their new home. Skip them.
  const preservedKeys = new Set(out.sentinels.flat().map((node) => node.getKey()));
  contentNodes.forEach((node) => {
    if (preservedKeys.has(node.getKey())) return;
    // An annotation wrapping note content is one of the note's own children, so it is removed
    // DIRECTLY here — and `TypedMarkNode.remove` reports a direct removal to the host as a
    // destroyed annotation. The annotation is not destroyed: `$restoreMarkByteRanges` below
    // re-wraps it over the rebuilt bytes. Suppress the notification the way every other
    // re-creation of a mark node does (AnnotationPlugin's nested-element resolver,
    // `TypedMarkNode`'s own sibling merges). A mark nested DEEPER needs nothing: a detached
    // subtree is garbage-collected without `remove()` ever running on it, which is why the
    // paragraph rebuild (whole paragraphs removed, marks always inside them) stays quiet.
    if ($isTypedMarkNode(node)) node.getWritable().__suppressOnRemoveCallbacks = true;
    node.remove();
  });
  // Before the caret restore, so the caret resolves against the final tree — mirror
  // `$rebuildParas`. Both re-read the note's CURRENT content rather than reuse `newNodes`:
  // moving a preserved run into place and re-wrapping a mark both split direct text children of
  // the note, which `newNodes` then no longer lists. The same walk the capture above used, so the
  // bytes line up.
  const $settledNoteContent = () => $buildNoteFragment(note, getMarkerFn, viewOptions);
  $restoreMarkByteRanges(markRanges, () => $settledNoteContent()?.out);
  $restoreSelectionInContentRegion(
    $settledNoteContent()?.contentNodes ?? newNodes,
    caret,
    anchorInNote,
    getMarkerFn,
    viewOptions,
  );
  return true;
}

/**
 * Replaces `note` with itself closed at the closer the user typed into it (see
 * `splitUnclosedNoteAtOwnCloser`), rebuilt in the view's own note mode - so a view that collapses
 * its closed notes now shows this one as its caller - followed by whatever came after the closer,
 * as paragraph content. The caret, when it was in the note, goes where the user was typing: past
 * the note whenever it collapsed OR nothing governs its shell through its own UI - which is every
 * ordinary close, including Unformatted view's expanded notes - so the next keystroke joins the
 * paragraph rather than extending the note's last run. Only a host whose note editor owns the
 * shell (`ViewOptions.isNoteShellEditable: false`) keeps the caret IN the note: there, the text
 * that followed the closer is about to be taken out of this editor entirely (see
 * `EditorRef.getOpsAfterNote`/`takeOpsAfterNote`), and the caret has to stay put for that. Preserve-
 * or-refuse: `false` with the note untouched when the rebuilt shape cannot carry every preserved
 * node.
 */
function $closeNoteAtOwnCloser(
  note: NoteNode,
  { before, after }: { before: MarkerContent[]; after: MarkerContent[] },
  foldedCategory: string | undefined,
  sentinels: LexicalNode[][],
  context: Tier2Context,
  anchorInNote: boolean,
): boolean {
  const { viewOptions, logger } = context;
  const serialized = $serializeNoteClosedAtOwnCloser(
    note,
    before,
    after,
    foldedCategory,
    viewOptions,
  );
  if (!serialized || countSerializedSentinels(serialized) !== sentinels.length) {
    logger?.warn("[MarkerEdit] Note close aborted: the closed note does not carry its content");
    return false;
  }
  const newNodes = serialized.map((child) => $parseSerializedNode(child));
  const [closedNote] = newNodes;
  if (!$isNoteNode(closedNote) || countSentinelNodes(newNodes) !== sentinels.length) {
    logger?.warn("[MarkerEdit] Note close aborted: the closed note does not carry its content");
    return false;
  }
  let previous: LexicalNode = note;
  for (const node of newNodes) {
    previous.insertAfter(node);
    previous = node;
  }
  $replaceSentinels(newNodes, sentinels);
  // The note stays the same node, taking on the closed note's content and attributes: closing a note
  // is an edit to it, not a new note, and a host tells the two apart by whether the node is new (a
  // new note is where a host opens its note editor).
  // Appended before the old children go: a note left empty removes itself.
  const oldChildren = note.getChildren();
  note.append(...closedNote.getChildren());
  oldChildren.forEach((child) => child.remove());
  note
    .setCaller(closedNote.getCaller())
    .setCategory(closedNote.getCategory())
    .setUnknownAttributes(closedNote.getUnknownAttributes())
    .setIsCollapsed(closedNote.getIsCollapsed());
  closedNote.remove();
  if (anchorInNote) {
    if (note.getIsCollapsed() !== true && viewOptions?.isNoteShellEditable === false)
      $selectNote(note, viewOptions);
    else $selectAfterNote(note, { isContentChange: true });
  }
  return true;
}

/**
 * The `\id` line's CONTENT children {@link $buildBookFragment} builds its fragment from —
 * everything after the immutable `\id GEN ` prefix glyph (markerMode "hidden" builds none, so the
 * skip is conditional on finding one) — WITHOUT building the fragment text/spans.
 *
 * Factored out for the same reason {@link $noteContentNodes} is: a caller that only needs the
 * CURRENT content nodes post-splice is not also paying for `$appendNodesFragment`'s walk again.
 */
function $bookContentNodes(book: BookNode): LexicalNode[] {
  const children = book.getChildren();
  return $isBookPrefixGlyph(children[0]) ? children.slice(1) : children;
}

/**
 * Build the re-tokenizable fragment for the `\id` line's CONTENT children.
 *
 * The book node itself is PRESERVED across the rebuild, exactly as a note's shell is: its marker
 * is always `\id`, its code names the book, and the view renders both as one decorator the caret
 * cannot enter — so none of it is ever re-derived from displayed bytes, and none of it can
 * disqualify a rebuild of the line's content the way a paragraph's own unknown attributes do.
 *
 * Exported for the read-only settle (virtualSettle.utils.ts), the same sharing contract
 * `$buildNoteFragment` has.
 *
 * Read-only: call inside `editor.update()` or an editor-state read.
 */
export function $buildBookFragment(
  book: BookNode,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): { out: FragmentAccumulator; contentNodes: LexicalNode[] } {
  const contentNodes = $bookContentNodes(book);
  const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  $appendNodesFragment(contentNodes, out, getMarkerFn, viewOptions);
  return { out, contentNodes };
}

/**
 * Bytes that literally OPEN with the tokenizer's default paragraph marker, so a wrapper built from
 * them is the author's own `\p` rather than the implied one — see {@link tokenizedBookLine}.
 *
 * Both edges mirror the tokenizer, since this re-derives from the bytes a decision it already made.
 * A leading whitespace run is dropped ahead of a block marker only when it holds a line break; any
 * other run (a space, a tab, an NBSP) is content, which the tokenizer wraps in the implied `\p`. And
 * a marker name ends where `scanMarkerName` ends it — at whitespace, a ZWSP, `\` or `|` — so
 * `\p\bd …` is the author's `\p` too, while `\p*` is a different marker altogether.
 */
const LEADING_DEFAULT_PARA_MARKER = new RegExp(
  `^(?:[\\s\\u200B]*[\\r\\n][\\s\\u200B]*)?\\\\${PARA_MARKER_DEFAULT}(?=[\\s\\u200B\\\\|]|$)`,
);

/**
 * The freshly tokenized `\id` line bytes, split where the line ENDS: `lineContent` is what the book
 * holds, and `followingBlocks` are the blocks a typed block marker starts after it (a `\p` or `\ip`
 * starts a paragraph, a `\c` a chapter) — exactly where the file bytes would end the line, which is
 * how PT9 reads them and how our own tokenizer reads them back on the next load. `content` is the
 * whole tokenized list, for the sentinel symmetry checks.
 *
 * The tokenizer wraps a body-context fragment's leading inline material in an implied `\p`, so the
 * line's own content arrives as that wrapper's content. Bytes that literally BEGIN with `\p`
 * tokenize to a wrapper indistinguishable from the implied one, and are told apart by the bytes
 * themselves: that `\p` is the author's, so the line is left empty and the paragraph follows it.
 *
 * Exported for the read-only settle (virtualSettle.utils.ts), which must reach the SAME split from
 * the same bytes — the sharing contract every other fragment helper here has.
 */
export function tokenizedBookLine(
  fragment: FragmentAccumulator,
  getMarkerFn: MarkerLookup,
): { content: MarkerContent[]; lineContent: MarkerContent[]; followingBlocks: MarkerContent[] } {
  const content: MarkerContent[] = tokenizeFragment(fragment, { getMarker: getMarkerFn });
  const [first, ...rest] = content;
  const opensWithImpliedPara =
    typeof first === "object" &&
    first.type === "para" &&
    first.marker === PARA_MARKER_DEFAULT &&
    !LEADING_DEFAULT_PARA_MARKER.test(fragment.text);
  return opensWithImpliedPara
    ? { content, lineContent: first.content ?? [], followingBlocks: rest }
    : { content, lineContent: [], followingBlocks: content };
}

/**
 * Book-scoped Tier 2 re-tokenization — the fourth settle scope, beside `$rebuildParas`,
 * `$rebuildNoteContent` and `$rebuildChapter`. Mirrors `$rebuildNoteContent`: it operates on the
 * `\id` line's CONTENT children while the book node, its code, and its prefix glyph are preserved.
 *
 * The line's text is content like any paragraph's — PT9 accepts char spans and notes in `\id`
 * text, and our own tokenizer parses them back as real markers on the next load — so without this
 * scope a marker typed there stayed literal on screen while the save wrote a real one. A typed
 * BLOCK marker ends the line the same way ({@link tokenizedBookLine}): the tail after it becomes
 * the new block, inserted directly after the book, just as a paragraph split starts its new
 * paragraph after the old one.
 *
 * `trailingParas` widens the scope past the line the way `$rebuildParas` widens a paragraph's: the
 * paragraphs directly after the book are joined onto the line's bytes as following lines
 * ({@link $appendParaFragments}) and replaced by whatever the joined bytes tokenize to. That is the
 * unknown-split rejoin (`$unknownSplitRejoinScope`), which folds a paragraph the line's own bytes
 * split off back into the line once its leading marker stops being block-shaped.
 *
 * Mutating: call inside `editor.update()` (dispatched from the Tier-2 trigger transform, the
 * caret-departure and commit paths in MarkerEditPlugin.tsx, `$requestTier2ForNode`, and — with
 * `trailingParas` — the unknown-split rejoin in markerEditTier1.utils.ts).
 */
export function $rebuildBook(
  book: BookNode,
  context: Tier2Context,
  trailingParas: ParaNode[] = [],
): boolean {
  const { viewOptions, getMarker: getMarkerFn, logger } = context;
  const { out, contentNodes } = $buildBookFragment(book, getMarkerFn, viewOptions);
  if (!$appendParaFragments(out, trailingParas, getMarkerFn, viewOptions)) {
    logger?.debug("[MarkerEdit] Book Tier 2 skipped: paragraph excluded by guard rails");
    return false;
  }
  const scopes: LexicalNode[] = [book, ...trailingParas];

  // Capture the caret as a fragment byte anchor before mutating, noting whether the anchor was
  // actually inside this scope (vs. parked elsewhere) — mirror `$rebuildNoteContent`.
  let caret: CapturedCaret | undefined;
  let anchorInScope = false;
  const selection = $getSelection();
  if ($isRangeSelection(selection)) {
    for (let node: LexicalNode | null = selection.anchor.getNode(); node; node = node.getParent())
      if (scopes.some((scope) => scope.is(node))) {
        anchorInScope = true;
        break;
      }
    if (selection.isCollapsed()) caret = $captureCaret(out, selection.anchor);
  }
  // Annotations on the line's text, and in the widened paragraphs, anchor the same way — mirror
  // `$rebuildParas` and `$rebuildNoteContent`.
  const markRanges = $captureMarkByteRanges(
    [...contentNodes, ...trailingParas],
    out,
    undefined,
    $getEditor(),
  );

  const tokenized = tokenizedBookLine(out, getMarkerFn);
  // Symmetry bail-out (see `$rebuildParas`): a preserved-run/placeholder mismatch aborts the
  // rebuild with the line untouched rather than silently dropping a node.
  if (countSentinels(tokenized.content) !== out.sentinels.length) {
    logger?.warn("[MarkerEdit] Book Tier 2 aborted: sentinel/preserved-node count mismatch");
    return false;
  }

  const serialized = $serializeBookLine(
    book,
    tokenized.lineContent,
    tokenized.followingBlocks,
    viewOptions,
  );
  if (serialized.failure !== undefined) {
    if (serialized.failure === "empty")
      logger?.debug("[MarkerEdit] Book Tier 2 skipped: no content nodes after unwrap");
    else logger?.warn("[MarkerEdit] Book Tier 2 aborted: unexpected serialized shape");
    return false;
  }
  // Second sentinel check on the SERIALIZED tree, the mirror of `$rebuildNoteContent`'s:
  // serialization is a separate place a U+FFFC placeholder can vanish.
  const serializedRegion = [...serialized.children, ...serialized.followingBlocks];
  if (countSerializedSentinels(serializedRegion) !== out.sentinels.length) {
    logger?.warn("[MarkerEdit] Book Tier 2 aborted: serialized sentinel/preserved-node mismatch");
    return false;
  }

  // Fixed-point refusal (preserve-or-refuse) on the CONTENT nodes and the widened paragraphs,
  // compared on the SERIALIZED rebuild before any nodes are parsed, so a refusal materializes no
  // live nodes — see `$rebuildParas`' fixed-point comment for why orphan-free refusal is
  // load-bearing. Without `trailingParas`, a rebuild that starts a following block restructures the
  // document, so it is never a fixed point.
  if (
    serialized.followingBlocks.length === trailingParas.length &&
    serializedSignatureOf(serialized.followingBlocks, getMarkerFn) ===
      $signatureOf(trailingParas, getMarkerFn) &&
    serializedSignatureOf(serialized.children, getMarkerFn) ===
      $signatureOf(contentNodes, getMarkerFn)
  ) {
    logger?.debug("[MarkerEdit] Book Tier 2 skipped: rebuild is a no-op (fixed point)");
    return false;
  }

  const newContent = serialized.children.map((child) => $parseSerializedNode(child));
  const newBlocks = serialized.followingBlocks.map((child) => $parseSerializedNode(child));
  const newNodes = [...newContent, ...newBlocks];
  // Parse-leg recount, the mirror of `$rebuildNoteContent`'s.
  if (countSentinelNodes(newNodes) !== out.sentinels.length) {
    logger?.warn("[MarkerEdit] Book Tier 2 aborted: parsed sentinel/preserved-node mismatch");
    return false;
  }

  // Snapshot the old content's verse number/sid pairs, in document order, as plain data — BEFORE
  // the splice below moves or destroys the old content nodes (a removed node's fields are not safe
  // to read afterward). Sid carry-over (below) pairs this against the freshly re-tokenized line's
  // verses once the splice has settled — mirrors `$rebuildParas`.
  const oldVerseSids = $collectVerseNodes([...contentNodes, ...trailingParas]).map((verse) => ({
    number: verse.getNumber(),
    sid: verse.getSid(),
  }));

  // Splice: insert the new content before the first old content node (or at the line's end when it
  // had none) and the new blocks directly after the book, move preserved sentinel runs into place,
  // then remove the originals — skipping the preserved nodes themselves, which `$replaceSentinels`
  // has just moved into their new home. A widened paragraph goes whole, as `$rebuildParas` removes
  // its own: its preserved runs have already moved out.
  const firstContent = contentNodes[0];
  if (firstContent) newContent.forEach((node) => firstContent.insertBefore(node));
  else newContent.forEach((node) => book.append(node));
  newBlocks.reduce<LexicalNode>((previous, block) => previous.insertAfter(block), book);
  $replaceSentinels(newNodes, out.sentinels);
  const preservedKeys = new Set(out.sentinels.flat().map((node) => node.getKey()));
  contentNodes.forEach((node) => {
    if (preservedKeys.has(node.getKey())) return;
    // An annotation on the line's text is one of the book's own children, removed directly here,
    // and it is not destroyed: `$restoreMarkByteRanges` below re-wraps it over the rebuilt bytes.
    // Its removal notification is suppressed for the reason `$rebuildNoteContent` gives.
    if ($isTypedMarkNode(node)) node.getWritable().__suppressOnRemoveCallbacks = true;
    node.remove();
  });
  trailingParas.forEach((para) => para.remove());
  // Before the content is re-read for the sid carry-over and the caret restore, since re-wrapping
  // a mark splits and re-parents the book's direct text children.
  $restoreMarkByteRanges(markRanges, () =>
    $bookScopeSpans(book, newBlocks, getMarkerFn, viewOptions),
  );
  // Re-derived from the book's OWN children now that the splice has settled, PLUS the freshly
  // inserted following blocks — included because a preserved run CAN resolve into a new following
  // block (e.g. typing a block marker at the very start of the line sends the whole tokenized
  // content, preserved runs included, to `followingBlocks`), not only into the book's own children
  // — see $restoreSelectionInContentRegion's doc comment for why the flat `newNodes` array is
  // stale for the book's own content, and $rebuildBook's own splice comment for why a typed block
  // marker's caret can resolve past the line's content into the new block after it. `$bookContentNodes`
  // alone (not `$buildBookFragment`) because only the content nodes are needed here — re-walking
  // their fragment text/spans a second time would be wasted work.
  const liveContentNodes = [...$bookContentNodes(book), ...newBlocks];
  // Sid carry-over — identical logic to `$rebuildParas`' own, see its comment for the rationale.
  // Collected from `liveContentNodes`, not the stale pre-splice `newNodes`: `$replaceSentinels`
  // (above) splices each preserved sentinel run into the live tree, so a sentinel verse is missing
  // from `newNodes` and every sid pairing after it shifts by one.
  const newVerses = $collectVerseNodes(liveContentNodes);
  for (let i = 0; i < oldVerseSids.length && i < newVerses.length; i++) {
    if (newVerses[i].getNumber() === oldVerseSids[i].number)
      newVerses[i].setSid(oldVerseSids[i].sid);
  }
  $restoreSelectionInContentRegion(
    liveContentNodes,
    caret,
    anchorInScope,
    getMarkerFn,
    viewOptions,
  );
  return true;
}

/** The markers whose FIRST-CLASS char form, sitting at document root directly after a chapter,
 * ParatextData folds back onto the chapter on parse — the chapter's attribute markers. A root
 * `\ca`/`\cp` char is the transient pre-fold shape (an unclosed/empty/markup-bearing span the
 * fold refused, or a mid-edit literal), so its edits settle through the CHAPTER scope. */
const CHAPTER_ATTRIBUTE_CHAR_MARKERS: ReadonlySet<string> = new Set(["ca", "cp"]);

/** The one chapter attribute marker whose first-class form is a PARAGRAPH, not a char span: `cp`
 * has no closing marker, so its span ends at the next block boundary and the tokenizer emits a
 * real `\cp` para for it (`ATTRIBUTE_MARKERS`, shape `"para"`). It takes that form when the fold
 * refuses — markup in the value, or an emptied one. */
const CHAPTER_ATTRIBUTE_PARA_MARKER = "cp";

/**
 * Whether `node` is an IMPLIED paragraph whose content re-tokenizes to ONLY chapter-attribute
 * (`\ca`/`\cp`) material — the settle-artifact shape a typed literal takes right after a
 * chapter: `$rebuildChapter`'s tokenized output strands non-chapter residue as a root-level
 * STRING, which the adaptor wraps in an `ImpliedParaNode`. That wrapper carries NO paragraph
 * marker byte (the file has no `\p` there), so its bytes and the chapter's legitimately
 * re-tokenize TOGETHER — which is exactly what the fold needs. It joins the chapter settle
 * region on the same terms as a first-class `\ca`/`\cp` char.
 *
 * The membership test is the tokenizer itself — never a byte regex — so the region's meaning
 * cannot drift from the fold authority: tokenize the implied paragraph's own fragment bytes,
 * unwrap the tokenizer's fabricated default `\p` (body-context fragments wrap leading inline
 * material in one; bytes that literally START with `\p` are NOT unwrapped — a typed `\p` is
 * real paragraph material, not an artifact wrapper), and require every item to be a `\ca`/`\cp`
 * char or para, or insignificant whitespace. Anything else — plain words, other markers, a
 * preserved-node sentinel — keeps the implied paragraph OUTSIDE the region: real content never
 * settles through the chapter, so a `\nd` literal cannot be restructured into a fabricated
 * root char, and an implied paragraph of ordinary text keeps its (deliberate) no-scope rest.
 *
 * Classified with the BUNDLED marker table on both the fragment walk and the tokenize: region
 * membership must be identical for every caller — the mutating settle, the read-only settle,
 * and the scope resolver, some of which have no `MarkerLookup` in reach ($settleScopeForNode) —
 * and `ca`/`cp` folding is ParatextData parse behavior, not a stylesheet-configurable property
 * (the same reason CHAPTER_ATTRIBUTE_CHAR_MARKERS is a literal set).
 *
 * Cost: the tokenize runs only for an `ImpliedParaNode` sitting in a chapter-adjacency probe —
 * a rare, transient shape whose content is a keystroke-sized literal. Every other node fails
 * the instanceof check first.
 *
 * Read-only: safe inside `editor.getEditorState().read(...)` or an update.
 */
function $isChapterAttributeImpliedPara(node: LexicalNode): node is ImpliedParaNode {
  if (!$isImpliedParaNode(node)) return false;
  const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  // View-independent classification probe: NBSP mapping cannot change whether the text
  // tokenizes as a chapter-attribute literal, so no view options are threaded here.
  $appendChildrenFragment(node, out, bundledGetMarker, undefined);
  if (out.sentinels.length > 0) return false;
  const text = out.text;
  if (text.trim() === "") return false;
  const content = usfmFragmentToUsjContent(withoutDisplayLineBreaks(text), {
    getMarker: bundledGetMarker,
  });
  const [first] = content;
  const items =
    content.length === 1 &&
    typeof first === "object" &&
    first.type === "para" &&
    first.marker === "p" &&
    !/^\s*\\p\s/.test(text)
      ? (first.content ?? [])
      : content;
  if (items.length === 0) return false;
  return items.every((item) =>
    typeof item === "string"
      ? item.trim() === ""
      : (item.type === "char" || item.type === "para") &&
        (item.marker === "ca" || item.marker === CHAPTER_ATTRIBUTE_PARA_MARKER),
  );
}

/**
 * The chapter settle REGION beyond `chapter`'s own children: the contiguous run of first-class
 * `\ca`/`\cp` char spans sitting at document root directly after it, plus — closing the run — a
 * real `\cp` PARAGRAPH. Their bytes re-tokenize together with the chapter's (`\c 1 \ca 3\ca*`
 * folds; the capture-pinned post-`\ca` whitespace skip applies), so a foldable span or paragraph
 * folds onto the chapter on settle instead of waiting for a reload, while an unfoldable one
 * (empty, unclosed, markup-bearing) re-tokenizes to the identical first-class shape — a fixed
 * point, refused without churn. The tokenizer stays the single fold authority either way.
 *
 * A `\cp` paragraph CLOSES the region because that is what it does in the file: with no closing
 * marker its span runs to the next block boundary, so nothing past it is still the chapter's.
 *
 * An IMPLIED paragraph holding only `\ca`/`\cp` material ({@link $isChapterAttributeImpliedPara}
 * — the typed-literal settle artifact) is a continuing member like the chars: its bytes carry no
 * paragraph marker, so nothing about it bounds the chapter's span in the file.
 *
 * Exported for the read-only settle (virtualSettle.utils.ts), which must splice the SAME region
 * out of its serialized output that `$rebuildChapter` replaces in the live tree.
 *
 * Read-only: safe inside `editor.getEditorState().read(...)` or an update.
 */
export function $chapterAdjacentAttributeNodes(chapter: ChapterNode): LexicalNode[] {
  const region: LexicalNode[] = [];
  for (let sibling = chapter.getNextSibling(); sibling; sibling = sibling.getNextSibling()) {
    if (
      ($isCharNode(sibling) && CHAPTER_ATTRIBUTE_CHAR_MARKERS.has(sibling.getMarker())) ||
      $isChapterAttributeImpliedPara(sibling)
    ) {
      region.push(sibling);
      continue;
    }
    if ($isParaNode(sibling) && sibling.getMarker() === CHAPTER_ATTRIBUTE_PARA_MARKER)
      region.push(sibling);
    break;
  }
  return region;
}

/**
 * The chapter that `rootChild` — a node sitting directly under the document root — is an
 * attribute marker of, reached through only other chapter attribute chars (or attribute-material
 * implied paragraphs); `undefined` when it is not one, or when anything but a chapter precedes
 * it. The inverse of {@link $chapterAdjacentAttributeNodes}: a root child is in a chapter's
 * region exactly when that chapter is the one this returns.
 *
 * Read-only: safe inside `editor.getEditorState().read(...)` or an update.
 */
function $chapterOfAdjacentAttributeNode(rootChild: LexicalNode): ChapterNode | undefined {
  const isContinuingMember = (node: LexicalNode): boolean =>
    ($isCharNode(node) && CHAPTER_ATTRIBUTE_CHAR_MARKERS.has(node.getMarker())) ||
    $isChapterAttributeImpliedPara(node);
  const isAttributeNode =
    isContinuingMember(rootChild) ||
    ($isParaNode(rootChild) && rootChild.getMarker() === CHAPTER_ATTRIBUTE_PARA_MARKER);
  if (!isAttributeNode) return undefined;
  for (
    let sibling: LexicalNode | null = rootChild.getPreviousSibling();
    sibling;
    sibling = sibling.getPreviousSibling()
  ) {
    if ($isChapterNode(sibling)) return sibling;
    if (!isContinuingMember(sibling)) return undefined;
  }
  return undefined;
}

/**
 * Build the re-tokenizable fragment for an editable chapter's OWN displayed bytes — its `\c N`
 * glyph text plus (when displayed) its `\ca` run's bytes — plus the bytes of the adjacent
 * first-class `\ca`/`\cp` spans and `\cp` paragraph ({@link $chapterAdjacentAttributeNodes}: the
 * settle region is the chapter AND those nodes, so a foldable one re-tokenizes onto the chapter).
 * Preserve-or-refuse (returns undefined) when the chapter carries unknown attributes (bytes
 * cannot re-derive them), when an adjacent `\cp` paragraph carries them (the same rule
 * `$buildParaFragment` applies to any paragraph), or when anything in the region degrades to a
 * preserved-node sentinel (nothing the adaptor builds in the chapter ever should; an adjacent
 * span or paragraph holding an unrecoverable construct refuses the same way).
 *
 * Exported for the read-only settle (virtualSettle.utils.ts), the same sharing contract
 * `$buildNoteFragment` has.
 */
export function $buildChapterFragment(
  chapter: ChapterNode,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): FragmentAccumulator | undefined {
  if (Object.keys(chapter.getUnknownAttributes() ?? {}).length > 0) return undefined;
  const adjacent = $chapterAdjacentAttributeNodes(chapter);
  if (adjacent.some((node) => $isParaNode(node) && node.getUnknownAttributes())) return undefined;
  const out: FragmentAccumulator = { text: "", spans: [], sentinels: [] };
  $appendNodesFragment(chapter.getChildren(), out, getMarkerFn, viewOptions);
  $appendNodesFragment(adjacent, out, getMarkerFn, viewOptions);
  if (out.sentinels.length > 0) return undefined;
  return out;
}

/** A bare backslash and the separator after it: a marker with no name. */
const NAMELESS_MARKER_REGEX = /^\\(?:\s|$)/;

/** A `\p` spelled at the start of a fragment, which the tokenizer then opens as typed. */
const LEADING_PARA_MARKER_REGEX = /^\s*\\p(?:\s|$)/;

/**
 * What a chapter's displayed bytes tokenize to, in the shape the document holds them.
 *
 * The tokenizer reads a fragment as paragraph content, so it opens a `\p` for text that comes
 * before any paragraph marker. On a chapter line nobody typed that `\p`: bytes left there that are
 * no longer a chapter marker (`c 2`, or text typed ahead of the `\c`) stand markerless, as
 * Paratext 9 keeps them, and a bare backslash (`\ 2`) opens a paragraph with no marker name. Neither is the glyph's trailing separator their content — it is display —
 * so a line left as text does not keep it.
 *
 * Display-only line breaks are not read ({@link withoutDisplayLineBreaks}). Exported for the
 * read-only settle (virtualSettle.utils.ts), which must read the same content.
 */
export function chapterFragmentContent(text: string, getMarkerFn: MarkerLookup): MarkerContent[] {
  const content = usfmFragmentToUsjContent(withoutDisplayLineBreaks(text), {
    getMarker: getMarkerFn,
  });
  const [first, ...others] = content;
  if (
    typeof first !== "object" ||
    first.type !== "para" ||
    first.marker !== "p" ||
    LEADING_PARA_MARKER_REGEX.test(text)
  )
    return content;
  const lineContent = [...(first.content ?? [])];
  const last = lineContent.at(-1);
  if (typeof last === "string") {
    const trimmed = last.trimEnd();
    if (trimmed) lineContent[lineContent.length - 1] = trimmed;
    else lineContent.pop();
  }
  // A bare backslash is a marker with no name, which is how ParatextData reads `\ 2` and writes it
  // back; holding the same paragraph means the saved chapter reads back as what was sent.
  const [lead, ...afterLead] = lineContent;
  if (typeof lead === "string" && NAMELESS_MARKER_REGEX.test(lead)) {
    const leadText = lead.replace(NAMELESS_MARKER_REGEX, "");
    const content = leadText ? [leadText, ...afterLead] : afterLead;
    return [{ type: "para", marker: "", content }, ...others];
  }
  return [...lineContent, ...others];
}

/**
 * Whether text joining the end of a paragraph needs a space put between them. The line break the
 * text stood behind is whitespace in USFM, so ParatextData reads `\toc1 stuff` and then `x\c 1` as
 * `\toc1 stuff x`. Nothing is added where whitespace is already there: at the end of the
 * paragraph's text, in its marker's separator or a verse's, or at the start of the text.
 *
 * @param lastType The `type` of the paragraph's last child, or `undefined` when it has none.
 * @param lastText That child's text when it is a text or a verse node, which can end in whitespace.
 * @param firstText The joining text's first text, when it starts with text.
 */
function needsJoiningSpace(
  lastType: string | undefined,
  lastText: string | undefined,
  firstText: string | undefined,
): boolean {
  if (lastType === undefined || /^\s/.test(firstText ?? "")) return false;
  if (lastText !== undefined) return !/\s$/.test(lastText);
  // A marker glyph is followed by its separator, which supplies the space itself.
  return lastType !== MarkerNode.getType();
}

/** Whether a node of `type` carries text that can end in whitespace. */
function isTextBearingType(type: string): boolean {
  return type === TextNode.getType() || type === VerseNode.getType();
}

/**
 * Joins the markerless line a chapter settle left first onto the end of the paragraph before it.
 * USFM puts text standing behind a line break with no marker of its own into the paragraph before
 * it, so the chapter's save and reload put it there too, and Paratext 9 keeps it there as typed.
 * The line's nodes move as they are, so a caret restored into them stays with them.
 *
 * @param line The first node the settle put in the chapter's place.
 */
function $joinLeadingLineToPreviousParagraph(line: LexicalNode | undefined): void {
  if (!$isImpliedParaNode(line)) return;
  const previous = line.getPreviousSibling();
  if (!$isParaNode(previous) && !$isImpliedParaNode(previous)) return;
  const moving = line.getChildren();
  const last = previous.getLastChild();
  const first = moving.at(0);
  const lastType = last?.getType();
  if (
    needsJoiningSpace(
      lastType,
      last && lastType && isTextBearingType(lastType) ? last.getTextContent() : undefined,
      $isTextNode(first) ? first.getTextContent() : undefined,
    )
  )
    previous.append($createTextNode(" "));
  previous.append(...moving);
  line.remove();
}

/** Whether two serialized text nodes differ only in their text, as text Lexical merges does. */
function areSerializedTextsMergeable(
  previous: SerializedLexicalNode,
  next: SerializedLexicalNode,
): boolean {
  if (serializedType(previous) !== TextNode.getType()) return false;
  if (serializedType(next) !== TextNode.getType()) return false;
  const { text: _previousText, ...previousRest } = previous as { text?: string };
  const { text: _nextText, ...nextRest } = next as { text?: string };
  return JSON.stringify(previousRest) === JSON.stringify(nextRest);
}

/** A plain serialized space, the node `$createTextNode(" ")` exports. */
const SERIALIZED_SPACE = {
  type: "text",
  version: 1,
  detail: 0,
  format: 0,
  mode: "normal",
  style: "",
  text: " ",
};

/**
 * The read-only mirror of {@link $joinLeadingLineToPreviousParagraph}, over a serialized document:
 * joins the markerless line at `siblings[index]` onto the end of the paragraph before it, as the
 * live settle does, including the text merge Lexical makes once the moved text sits beside the
 * paragraph's own.
 *
 * Exported for the read-only settle (virtualSettle.utils.ts).
 *
 * @param siblings The children the chapter's settled nodes were spliced into.
 * @param index Where the first of those nodes now is.
 */
export function joinSerializedLeadingLineToPreviousParagraph(
  siblings: SerializedLexicalNode[],
  index: number,
): void {
  const line = siblings.at(index);
  const previous = index > 0 ? siblings[index - 1] : undefined;
  if (!line || !previous || serializedType(line) !== ImpliedParaNode.getType()) return;
  const previousType = serializedType(previous);
  if (previousType !== ParaNode.getType() && previousType !== ImpliedParaNode.getType()) return;
  const moving = serializedChildren(line);
  const children = serializedChildren(previous);
  if (!moving || !children) return;
  const last = children.at(-1);
  const first = moving.at(0);
  const lastType = last ? serializedType(last) : undefined;
  if (
    needsJoiningSpace(
      lastType,
      last && lastType && isTextBearingType(lastType) ? serializedText(last) : undefined,
      first ? serializedText(first) : undefined,
    )
  )
    children.push({ ...SERIALIZED_SPACE });
  for (const node of moving) {
    const end = children.at(-1);
    if (end && areSerializedTextsMergeable(end, node))
      Object.assign(end, { text: `${serializedText(end) ?? ""}${serializedText(node) ?? ""}` });
    else children.push(node);
  }
  siblings.splice(index, 1);
}

/** Whether `item` is a chapter marker. */
function isChapterContent(item: MarkerContent | undefined): item is MarkerContent & object {
  return typeof item === "object" && item.type === "chapter";
}

/**
 * Chapter-scoped Tier 2 re-tokenization — the third settle scope, beside `$rebuildParas` and
 * `$rebuildNoteContent`. The whole chapter node re-serializes from its re-tokenized bytes:
 * `number`, `altnumber`, and `pubnumber` come from the bytes (the tokenizer's chapter-path
 * attrCapture folds well-formed `\ca`/`\cp` spans back onto the chapter), while `sid` — never
 * derivable from visible bytes — is carried over.
 *
 * Bytes that no longer read as a chapter marker — `\ 2` or `c 2` after a deletion, another marker
 * typed over the `\c`, text typed ahead of it — become what they now are
 * ({@link chapterFragmentContent}): the region is replaced by that content, as Paratext 9 keeps
 * the bytes it holds, and the host puts back a marker the chapter needs on save. Markerless text
 * left first then joins a paragraph before the chapter
 * ({@link $joinLeadingLineToPreviousParagraph}). Bytes that are nothing at all once the glyph's
 * separator is set aside remove the region, but not while the caret is in it, which would leave
 * the caret nowhere; deleting a chapter outright is `$chapterNodeTransform`'s empty-children path.
 *
 * Carries annotation marks across like its paragraph and note-content siblings. The chapter marker
 * itself has no content children for a `UsjDocumentLocation` to land in, but the adjacent
 * `\ca`/`\cp` spans and `\cp` paragraph in the region do, and a span that does not fold keeps its
 * content. A mark whose bytes DO fold onto the chapter lands in its attribute run's glyph bytes and
 * is dropped, as a mark over bytes that became a marker is anywhere. The signature reads a mark
 * transparently, so a region whose only difference is a mark reports a fixed point and is left
 * exactly as it stands.
 */
export function $rebuildChapter(chapter: ChapterNode, context: Tier2Context): boolean {
  const { viewOptions, getMarker: getMarkerFn, logger } = context;
  // The settle REGION: the chapter plus the adjacent first-class `\ca`/`\cp` spans and `\cp`
  // paragraph at root — captured BEFORE the splice below detaches them, and the same region
  // `$buildChapterFragment` reads its bytes from.
  const region: LexicalNode[] = [chapter, ...$chapterAdjacentAttributeNodes(chapter)];
  const out = $buildChapterFragment(chapter, getMarkerFn, viewOptions);
  if (!out) {
    logger?.debug("[MarkerEdit] Chapter Tier 2 skipped: chapter excluded by guard rails");
    return false;
  }

  // Capture the caret as a fragment byte anchor before mutating — mirror `$rebuildParas`. The
  // anchor check spans the whole region: an edit inside an adjacent first-class char (the fold's
  // primary trigger) holds its caret in the CHAR, not the chapter, and must be restored into
  // the rebuilt output the same way.
  let caret: CapturedCaret | undefined;
  let anchorInRegion = false;
  const selection = $getSelection();
  if ($isRangeSelection(selection)) {
    for (let node: LexicalNode | null = selection.anchor.getNode(); node; node = node.getParent())
      if (region.some((member) => member.is(node))) {
        anchorInRegion = true;
        break;
      }
    if (selection.isCollapsed()) caret = $captureCaret(out, selection.anchor);
  }

  // The adjacent spans and `\cp` paragraph hold content a mark can cover, and the splice below
  // destroys them — carried the way `$rebuildParas` carries a paragraph's.
  const markRanges = $captureMarkByteRanges(region, out, undefined, $getEditor());

  const content = chapterFragmentContent(out.text, getMarkerFn);
  if (content.length === 0 && anchorInRegion) {
    logger?.debug("[MarkerEdit] Chapter Tier 2 deferred: emptied chapter line holds the caret");
    return false;
  }
  if (countSentinels(content) !== 0) {
    logger?.warn("[MarkerEdit] Chapter Tier 2 aborted: unexpected preserved-node placeholder");
    return false;
  }
  const [first] = content;
  const freshChapter = isChapterContent(first) ? first : undefined;

  // Sid carry-over BEFORE serialization — never derivable from visible bytes. `altnumber` and
  // `pubnumber` both come from the bytes now that both runs display: absent bytes mean deleted.
  // Carried to the chapter even when text typed ahead of it now comes first.
  const survivingChapter = content.find(isChapterContent);
  if (survivingChapter && chapter.getSid() !== undefined) survivingChapter.sid = chapter.getSid();

  const serialized = usjEditorAdaptor.serializeEditorState(
    { type: USJ_TYPE, version: USJ_VERSION, content },
    viewOptions,
  );

  // Fixed-point refusal (preserve-or-refuse), the same comparison the other two scopes make —
  // but with the STATE catch-up the note scope's category write also needs: an edited (or
  // deleted) run's fresh serialization is byte-identical to what the live tree already displays
  // (the user's edit IS those bytes), so the structural comparison legitimately reports a fixed
  // point while `number`/`altnumber`/`pubnumber` still lag the displayed bytes. Reconcile them
  // here; the splice path below needs none of this (the fresh nodes replace the region, state
  // and all). Compared over the whole REGION: an adjacent unfoldable first-class char that
  // re-tokenizes to its identical self is part of the fixed point, not a difference. Compared on
  // the SERIALIZED rebuild (`serializedSignatureOf`), before any nodes are parsed, so a refusal
  // materializes no live nodes — see `$rebuildParas`' fixed-point comment for why orphan-free
  // refusal is load-bearing.
  if (
    freshChapter &&
    serializedSignatureOf(serialized.root.children, getMarkerFn) ===
      $signatureOf(region, getMarkerFn)
  ) {
    let reconciled = false;
    if (chapter.getNumber() !== (freshChapter.number ?? "")) {
      chapter.setNumber(freshChapter.number ?? "");
      reconciled = true;
    }
    if (chapter.getAltnumber() !== freshChapter.altnumber) {
      chapter.setAltnumber(freshChapter.altnumber);
      reconciled = true;
    }
    if (chapter.getPubnumber() !== freshChapter.pubnumber) {
      chapter.setPubnumber(freshChapter.pubnumber);
      reconciled = true;
    }
    if (!reconciled)
      logger?.debug("[MarkerEdit] Chapter Tier 2 skipped: rebuild is a no-op (fixed point)");
    return reconciled;
  }

  const newNodes = serialized.root.children.map((child) => $parseSerializedNode(child));
  newNodes.forEach((node) => chapter.insertBefore(node));
  region.forEach((node) => node.remove());
  // Before the caret restore, so the caret resolves against the final tree — mirror
  // `$rebuildParas`.
  $restoreMarkByteRanges(markRanges, () =>
    $settledChapterScopeFragment(newNodes, getMarkerFn, viewOptions),
  );
  $restoreSelectionAtOffset(newNodes, caret, anchorInRegion, getMarkerFn, viewOptions);
  $joinLeadingLineToPreviousParagraph(newNodes.at(0));
  return true;
}

/**
 * The re-tokenization SCOPE a node belongs to: the expanded note whose content contains it, the
 * editable chapter whose display bytes contain it, the `\id` line whose content contains it, or
 * the paragraph that contains it — or `undefined` when it has none (an opaque block interior,
 * where the bytes stay literal, or a detached node). The nearest scope wins — a note inside
 * a paragraph is its own scope: the note node, its marker glyphs, and its caller are preserved
 * across a rebuild while only its content re-tokenizes, and the same holds for a note inside the
 * `\id` line. A note whose own glyph has become a literal ({@link $isLiteralNoteShell}) is no
 * scope: its glyph bytes are what changed, so its paragraph (or line) re-tokenizes them with the
 * rest of the note's bytes.
 *
 * The walk runs to the DOCUMENT ROOT, not just to the first Note/Para match: a paragraph can itself
 * be nested inside an opaque block (a sidebar's own paragraphs — see `$buildParaFragment`'s matching
 * ancestor guard), so an `UnknownNode` anywhere between `node` and the root — even above the nearest
 * Note/Para — still means "opaque block interior", overriding whatever scope was found closer in.
 * The override applies just the same when the nearest scope found is a NOTE, not only a paragraph:
 * a well-formed, expanded note can itself live inside a sidebar, and an `UnknownNode` further out
 * still wins over it — matching the pend path's own full-chain literal-only guard
 * (`$isInLiteralOnlyBlock`, shared), which never pends a key whose divergence
 * could never settle in the first place.
 *
 * One scope is not an ancestor: a chapter's attribute markers sitting at DOCUMENT ROOT directly
 * adjacent to it (through only other such spans) settle through that CHAPTER's scope, because
 * only a re-tokenize that sees the `\c` and the `\ca`/`\cp` bytes TOGETHER can fold them back
 * onto it ({@link $chapterAdjacentAttributeNodes}, whose region `$rebuildChapter` rebuilds).
 * Without this arm the fold waited for a reload. Two shapes reach it:
 *
 * - a first-class `\ca`/`\cp` CHAR, which has no Note/Para/Chapter ancestor at all;
 * - a real `\cp` PARAGRAPH, which does have one — itself. Its own paragraph scope is what a
 *   `\cp` paragraph must NOT settle through: re-tokenizing `\cp 1` alone can only ever produce a
 *   `\cp` paragraph, so the chapter has to be in the fragment for the fold to be expressible at
 *   all. The chapter therefore OVERRIDES a paragraph scope that is the root child itself, while
 *   any scope found deeper in (a note inside that paragraph) still wins — it is the nearer
 *   scope, and its own rebuild is the right one.
 *
 * The single definition of scope, shared by the mutating settle below and the read-only settle in
 * virtualSettle.utils.ts. Both must route a given pending key to the SAME scope, or the settled USJ
 * a consumer reads and the structure a later real settle produces would be derived from different
 * regions of the document.
 */
export function $settleScopeForNode(
  node: LexicalNode,
): ParaNode | NoteNode | ChapterNode | BookNode | undefined {
  let scope: ParaNode | NoteNode | ChapterNode | BookNode | undefined;
  let rootChild: LexicalNode | undefined;
  for (let current: LexicalNode | null = node; current; current = current.getParent()) {
    if ($isUnknownNode(current)) return undefined;
    if (
      !scope &&
      (($isNoteNode(current) && !$isLiteralNoteShell(current)) ||
        $isParaNode(current) ||
        $isChapterNode(current) ||
        $isBookNode(current))
    )
      scope = current;
    if ($isRootNode(current.getParent())) rootChild = current;
  }
  // A scope found DEEPER than the root child is the nearer one and wins outright; only the root
  // child itself can be a chapter's attribute marker.
  if (scope && !scope.is(rootChild)) return scope;
  return (rootChild ? $chapterOfAdjacentAttributeNode(rootChild) : undefined) ?? scope;
}

/** Route a Tier-1-unexpressible edit to Tier 2 via its scope ({@link $settleScopeForNode}).
 * Returns whether the routed rebuild actually SPLICED — a guard-rail or fixed-point refusal mutates
 * nothing, and the deferred-resolution history bookkeeping ($resolvePendingMarkers callers) needs to
 * tell the two apart. */
export function $requestTier2ForNode(node: LexicalNode, context: Tier2Context): boolean {
  const scope = $settleScopeForNode(node);
  if (!scope) return false;
  if ($isNoteNode(scope)) return $rebuildNoteContent(scope, context);
  if ($isChapterNode(scope)) return $rebuildChapter(scope, context);
  if ($isBookNode(scope)) return $rebuildBook(scope, context);
  return $rebuildParas([scope], context);
}

/** USJ marker-object keys that are never attribute-list display bytes. `closed` is a USJ key but
 * is excluded from rendered attribute text (ATTRIBUTE_EXCLUDED_KEYS in the display layer), so
 * folding it would let its letters mask a genuine loss of the same characters. */
const CONTENT_BYTE_BASE_KEYS = new Set(["type", "marker", "content", "closed"]);

function appendAttributeListBytes(item: MarkerObject, out: string[]): void {
  const entries = Object.entries(item).filter(
    (entry): entry is [string, string] =>
      typeof entry[1] === "string" && !CONTENT_BYTE_BASE_KEYS.has(entry[0]),
  );
  if (entries.length === 0) return;
  out.push("|");
  for (const [key, value] of entries) out.push(`${key}="${value}"`);
}

/**
 * Fold tokenized content back into an approximation of its USFM display bytes, for the
 * byte-preservation comparison in {@link $idleSettleWouldDiscardCaretHeldBytes}. Whitespace is
 * irrelevant to the comparison (the counter ignores it), and ADDED bytes are harmless — only a
 * byte the fold FAILS to re-emit can misreport a loss, which merely defers that settle to caret
 * departure. So the fold favors emitting too much over too little (e.g. a default attribute the
 * canonical display would render bare is folded as `name="value"`), and unknown shapes fall to a
 * marker-plus-content default.
 */
function appendContentBytes(content: MarkerContent[] | undefined, out: string[]): void {
  if (!content) return;
  for (const item of content) {
    if (typeof item === "string") {
      out.push(item);
      continue;
    }
    const marker = item.marker ?? "";
    const closed = (item as { closed?: string }).closed;
    switch (item.type) {
      case "verse":
        out.push(`\\${marker} ${item.number ?? ""}`);
        if (item.altnumber !== undefined) out.push(`\\va ${item.altnumber}\\va*`);
        if (item.pubnumber !== undefined) out.push(`\\vp ${item.pubnumber}\\vp*`);
        break;
      case "chapter":
        out.push(`\\${marker} ${item.number ?? ""}`);
        if (item.altnumber !== undefined) out.push(`\\ca ${item.altnumber}\\ca*`);
        if (item.pubnumber !== undefined) out.push(`\\cp ${item.pubnumber}`);
        break;
      case "ms":
        out.push(`\\${marker}`);
        appendAttributeListBytes(item, out);
        out.push("\\*");
        break;
      case "unmatched":
        out.push(`\\${marker}`);
        break;
      case "char":
        out.push(`\\${marker} `);
        appendContentBytes(item.content, out);
        appendAttributeListBytes(item, out);
        if (closed !== "false") out.push(`\\${marker}*`);
        break;
      case "note": {
        const caller = (item as { caller?: string }).caller;
        const category = (item as { category?: string }).category;
        out.push(`\\${marker} ${caller ?? ""}`);
        if (category !== undefined) out.push(`\\cat ${category}\\cat*`);
        appendContentBytes(item.content, out);
        if (closed !== "false") out.push(`\\${marker}*`);
        break;
      }
      default:
        // Paragraphs and anything else block-shaped: the marker plus its content. Attribute-ish
        // keys (a para's vid/sid) are not display bytes, so they are deliberately NOT folded —
        // emitting them could mask a loss of the same characters.
        out.push(`\\${marker} `);
        appendContentBytes(item.content, out);
    }
  }
}

/**
 * Whether settling `node`'s scope on the IDLE clock would DISCARD displayed non-whitespace bytes
 * out from under the collapsed caret holding that scope. The one shape this is true for is a
 * typed byte the re-tokenization legitimately drops — e.g. a lone `|` in a milestone run:
 * `\qt-s|\*` tokenizes to a milestone with NO attributes, so the canonical rebuild has no `|`
 * left for the caret to sit after. Settling that mid-composition is accept-then-discard (the
 * no-silent-no-ops rule's exact forbidden shape) AND destroys the caret's byte position, so the
 * idle caller re-pends instead and the site settles on genuine caret departure, where the
 * tokenizer's meaning wins with no held caret to betray.
 *
 * The comparison is a non-whitespace character count: every non-whitespace character of the
 * scope's displayed fragment must be re-emitted by folding the tokenized output back to bytes
 * ({@link appendContentBytes}). Whitespace is excluded because the engine legitimately adds,
 * moves, and flattens display whitespace (NBSP separators, joiners). A false positive (the fold
 * under-emitting an exotic shape, a typographic quote the tokenizer regularizes) only defers
 * that settle to caret departure — the pre-idle-clock behavior.
 *
 * Paragraph and `\id`-line scopes only — both re-tokenize plain content, where the shape exists.
 * The chapter and note scopes fold values byte-preservingly (an unparseable value lands in
 * altnumber/category verbatim), so no byte-dropping shape is known there; their idle settles are
 * not second-guessed.
 *
 * Read-only (reads the live selection and tree, never mutates): call inside `editor.update()`,
 * where the settle passes already run.
 */
export function $idleSettleWouldDiscardCaretHeldBytes(
  node: LexicalNode,
  getMarkerFn: MarkerLookup,
  viewOptions: ViewOptions | undefined,
): boolean {
  const scope = $settleScopeForNode(node);
  if (!$isParaLikeNode(scope)) return false;
  const selection = $getSelection();
  if (!$isRangeSelection(selection) || !selection.isCollapsed()) return false;
  let caretInScope = false;
  for (
    let current: LexicalNode | null = selection.anchor.getNode();
    current;
    current = current.getParent()
  )
    if (scope.is(current)) {
      caretInScope = true;
      break;
    }
  if (!caretInScope) return false;
  const fragment = $isBookNode(scope)
    ? $buildBookFragment(scope, getMarkerFn, viewOptions).out
    : $buildParaFragment(scope, getMarkerFn, viewOptions);
  if (!fragment) return false;
  const content = tokenizeFragment(fragment, {
    getMarker: getMarkerFn,
    opensNamelessParagraph: $opensNamelessParagraph([scope]),
  });
  if (content.length === 0) return false;
  const counts = new Map<string, number>();
  for (const ch of fragment.text)
    if (!FRAGMENT_WS.test(ch)) counts.set(ch, (counts.get(ch) ?? 0) + 1);
  const folded: string[] = [];
  appendContentBytes(content, folded);
  // Fragment text spells a data NBSP as `~` (in every view: the standard-view display already
  // shows `~`, and `contentFragmentText` spells unformatted content NBSPs the same way), while
  // the fold emits the real NBSP byte — which `\s` matches, so it would silently vanish from
  // this count and report every caret-held data NBSP as a discard. Count it as the fragment
  // spells it.
  for (const ch of folded.join("").replaceAll(NBSP, "~")) {
    if (FRAGMENT_WS.test(ch)) continue;
    const remaining = counts.get(ch);
    if (remaining !== undefined && remaining > 0) counts.set(ch, remaining - 1);
  }
  for (const remaining of counts.values()) if (remaining > 0) return true;
  return false;
}
