const applyingByEditor = new WeakMap();
/**
 * Mark `editor` as committing an update applied from `source`, or as not applying one
 * (`undefined`). Set it inside a DISCRETE update and clear it once that commit lands (its
 * `onUpdate`) or the update throws, so it covers exactly that commit's transforms and listeners.
 */
export function markApplyingUpdate(editor, source) {
    if (source)
        applyingByEditor.set(editor, source);
    else
        applyingByEditor.delete(editor);
}
/** Where the update `editor` is committing was applied from, or `undefined` when it is not
 * committing an applied update (see {@link markApplyingUpdate}). */
export function getApplyingUpdateSource(editor) {
    return applyingByEditor.get(editor);
}
